
        // =========================================
        // MEDX EVENT DATES — single source of truth, hydrated from /api/plexus/settings
        // Each consumer reads window.MEDX_DATES.<key> with the literal string as fallback
        // so any code path that runs before the API resolves still gets a sane default.
        // =========================================
        window.MEDX_DATES = window.MEDX_DATES || {
            plexus: {
                start: '2026-12-04',
                end: '2026-12-05',
                startISO: '2026-12-04T08:00:00+01:00',
                checkinAt: '2026-12-04T00:00:00',
                liveAt: '2026-12-04T09:00:00',
                day2EndAt: '2026-12-05T18:00:00',
                endOfDay: '2026-12-05T23:59:59'
            },
            af26: { start: '2027-05-25', end: '2027-05-27' }
        };
        window.AF26_EVENT_START = window.MEDX_DATES.af26.start;

        // =========================================
        // XSS PROTECTION UTILITY
        // =========================================
        function escapeHtml(str) {
            if (str === null || str === undefined) return '';
            return String(str).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#39;');
        }

        // Sanitize a user-supplied URL for use in an href. escapeHtml alone does NOT stop a
        // javascript:/data:/vbscript: scheme from executing on click — only http(s)/mailto/tel
        // and protocol-relative or relative URLs are allowed; anything else becomes '#'.
        function safeUrl(url) {
            if (!url) return '#';
            const s = String(url).trim();
            if (/^(https?:|mailto:|tel:|\/|#|\.)/i.test(s) && !/^\s*javascript:/i.test(s)) return s;
            if (/^[^:]+\.[^:]/.test(s) && !s.includes(':')) return s; // bare domain like medx.hr
            return '#';
        }

        // =========================================
        // SAFE JSON/LOCALSTORAGE UTILITIES
        // =========================================
        function safeJsonParse(str, fallback) {
            if (str == null) return fallback;
            try {
                return JSON.parse(str);
            } catch (e) {
                return fallback;
            }
        }

        function safeLocalStorageSet(key, value) {
            try {
                localStorage.setItem(key, typeof value === 'string' ? value : JSON.stringify(value));
            } catch (e) {
                if (e.name === 'QuotaExceededError' || e.code === 22) {
                    // Clear cache/draft entries and retry
                    Object.keys(localStorage).forEach(k => {
                        if (k.startsWith('medx_cache_') || k.startsWith('medx_draft_')) {
                            localStorage.removeItem(k);
                        }
                    });
                    try {
                        localStorage.setItem(key, typeof value === 'string' ? value : JSON.stringify(value));
                    } catch (e2) {
                        if (typeof Toast !== 'undefined') {
                            Toast.error('Storage is full. Please clear some data.');
                        }
                    }
                }
            }
        }

        // =========================================
        // PASS SYSTEM - Digital pass generation & email
        // =========================================
        const PassSystem = {
            // Generate a unique registration ID
            generateRegId(prefix = 'PX26') {
                const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
                let id = '';
                for (let i = 0; i < 6; i++) {
                    id += chars.charAt(Math.floor(Math.random() * chars.length));
                }
                return `${prefix}-${id}`;
            },

            // Generate QR code data for an event registration
            generateQRData(userData, eventData) {
                return JSON.stringify({
                    type: eventData.type || 'MEDX_EVENT',
                    id: eventData.registrationId,
                    name: `${userData.first_name || ''} ${userData.last_name || ''}`.trim() || userData.name,
                    email: userData.email,
                    institution: userData.institution || 'Medical Professional',
                    event: eventData.event,
                    package: eventData.package || [],
                    timestamp: new Date().toISOString()
                });
            },

            // Generate pass and send confirmation email
            async generateAndSendPass(userData, eventConfig) {
                const registrationId = eventConfig.registrationId || this.generateRegId(eventConfig.prefix || 'MEDX');

                // Store registration data
                const registrationData = {
                    id: registrationId,
                    user: userData,
                    event: eventConfig.event,
                    package: eventConfig.package || [],
                    pricing: eventConfig.pricing,
                    createdAt: new Date().toISOString()
                };

                // Save to localStorage for demo
                const registrations = safeJsonParse(localStorage.getItem('medx_registrations'), []);
                registrations.push(registrationData);
                localStorage.setItem('medx_registrations', JSON.stringify(registrations));
                localStorage.setItem(`${eventConfig.event}_registration_id`, registrationId);

                // Show pass modal with download option
                this.showPassModal(userData, eventConfig, registrationId);

                return registrationId;
            },

            // Show the pass modal with the generated pass
            showPassModal(userData, eventConfig, registrationId) {
                const fullName = `${userData.first_name || ''} ${userData.last_name || ''}`.trim() || userData.name || 'Attendee';
                const institution = userData.institution || 'Medical Professional';
                const email = userData.email || '';

                // Build package badges
                const packageItems = eventConfig.package || ['day1', 'day2'];
                let badgesHtml = '';
                if (packageItems.includes('day1')) badgesHtml += '<span class="pass-badge">Day 1</span>';
                if (packageItems.includes('day2')) badgesHtml += '<span class="pass-badge">Day 2</span>';
                if (packageItems.includes('gala')) badgesHtml += '<span class="pass-badge gala">Gala Evening</span>';
                if (packageItems.includes('workshop1')) badgesHtml += '<span class="pass-badge">AI Workshop</span>';
                if (packageItems.includes('workshop2')) badgesHtml += '<span class="pass-badge">Grant Writing</span>';
                if (packageItems.includes('welcome')) badgesHtml += '<span class="pass-badge">Welcome Reception</span>';
                if (packageItems.includes('citytour')) badgesHtml += '<span class="pass-badge">City Tour</span>';
                if (packageItems.includes('certificate')) badgesHtml += '<span class="pass-badge">Certificate</span>';
                if (packageItems.includes('proceedings')) badgesHtml += '<span class="pass-badge">Proceedings</span>';

                // Event-specific styling
                const eventStyles = {
                    'plexus-2026': { title: 'PLEXUS 2026', subtitle: '10th International Biomedical Conference', color: '#c2484e' },
                    'gala-2026': { title: 'GALA EVENING 2026', subtitle: 'Awards Ceremony & Dinner', color: 'var(--gold)' },
                    'af-2026': { title: 'ANNUAL FORUM 2026', subtitle: 'Biomedical Forum', color: 'var(--gold)' },
                    'accelerator-2026': { title: 'ACCELERATOR 2026', subtitle: 'Summer Research Program', color: '#b06a1f' }
                };
                const style = eventStyles[eventConfig.event] || eventStyles['plexus-2026'];

                // Create modal
                const modal = document.createElement('div');
                modal.id = 'passModal';
                modal.innerHTML = `
                    <style>
                        #passModal {
                            position: fixed;
                            inset: 0;
                            background: rgba(0,0,0,0.8);
                            display: flex;
                            align-items: center;
                            justify-content: center;
                            z-index: 100000;
                            padding: 20px;
                            animation: fadeIn 0.3s;
                        }
                        @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
                        .pass-modal-content {
                            background: #fff;
                            border-radius: 14px;
                            max-width: 420px;
                            width: 100%;
                            overflow: hidden;
                            box-shadow: 0 25px 80px rgba(0,0,0,0.4);
                            animation: slideUp 0.4s;
                        }
                        @keyframes slideUp { from { transform: translateY(40px); opacity: 0; } to { transform: translateY(0); opacity: 1; } }
                        .pass-modal-header {
                            background: linear-gradient(135deg, var(--ink) 0%, var(--emph-bg-2) 100%);
                            padding: 32px 24px;
                            text-align: center;
                        }
                        .pass-modal-header h2 {
                            color: var(--gold);
                            font-size: 28px;
                            margin: 0 0 4px;
                            letter-spacing: -0.5px;
                        }
                        .pass-modal-header p {
                            color: rgba(255,255,255,0.7);
                            font-size: 13px;
                            margin: 0;
                        }
                        .pass-modal-success {
                            background: linear-gradient(135deg, #2f6b3a 0%, #2f6b3a 100%);
                            color: white;
                            padding: 16px 24px;
                            display: flex;
                            align-items: center;
                            gap: 12px;
                            font-size: 14px;
                            font-weight: 500;
                        }
                        .pass-modal-success i { font-size: 20px; }
                        .pass-modal-body {
                            padding: 24px;
                        }
                        .pass-preview {
                            background: linear-gradient(135deg, var(--ink) 0%, var(--emph-bg-2) 100%);
                            border-radius: 12px;
                            padding: 20px;
                            margin-bottom: 20px;
                        }
                        .pass-preview-name {
                            color: #fff;
                            font-size: 20px;
                            font-weight: 600;
                            margin-bottom: 4px;
                        }
                        .pass-preview-inst {
                            color: rgba(255,255,255,0.6);
                            font-size: 13px;
                            margin-bottom: 16px;
                        }
                        .pass-preview-badges {
                            display: flex;
                            flex-wrap: wrap;
                            gap: 6px;
                            margin-bottom: 16px;
                        }
                        .pass-badge {
                            background: rgba(201,169,98,0.15);
                            border: 1px solid rgba(201,169,98,0.3);
                            color: var(--gold);
                            padding: 4px 10px;
                            border-radius: 12px;
                            font-size: 11px;
                            font-weight: 500;
                        }
                        .pass-badge.gala {
                            background: rgba(201,169,98,0.25);
                            border-color: var(--gold);
                        }
                        .pass-preview-id {
                            background: rgba(255,255,255,0.1);
                            padding: 8px 12px;
                            border-radius: 8px;
                            font-family: monospace;
                            color: var(--gold);
                            font-size: 14px;
                            text-align: center;
                        }
                        .pass-modal-info {
                            background: #f8f9fa;
                            border-radius: 12px;
                            padding: 16px;
                            margin-bottom: 20px;
                        }
                        .pass-modal-info h4 {
                            margin: 0 0 12px;
                            font-size: 14px;
                            color: #1a1a1a;
                        }
                        .pass-modal-info ul {
                            margin: 0;
                            padding-left: 20px;
                            color: #555;
                            font-size: 13px;
                            line-height: 1.8;
                        }
                        .pass-modal-actions {
                            display: flex;
                            flex-direction: column;
                            gap: 10px;
                        }
                        .pass-modal-btn {
                            padding: 14px 20px;
                            border-radius: 12px;
                            font-size: 14px;
                            font-weight: 600;
                            cursor: pointer;
                            border: none;
                            display: flex;
                            align-items: center;
                            justify-content: center;
                            gap: 10px;
                            transition: all 0.2s;
                        }
                        .pass-modal-btn.primary {
                            background: linear-gradient(135deg, var(--gold) 0%, #E8D5A8 100%);
                            color: var(--ink);
                        }
                        .pass-modal-btn.primary:hover {
                            transform: translateY(-2px);
                            box-shadow: 0 6px 20px rgba(201,169,98,0.4);
                        }
                        .pass-modal-btn.secondary {
                            background: var(--paper-2);
                            color: var(--ink-soft);
                        }
                        .pass-modal-btn.secondary:hover {
                            background: var(--line);
                        }
                        .pass-modal-close {
                            position: absolute;
                            top: 16px;
                            right: 16px;
                            background: rgba(255,255,255,0.1);
                            border: none;
                            color: white;
                            width: 32px;
                            height: 32px;
                            border-radius: 50%;
                            cursor: pointer;
                            font-size: 16px;
                        }
                        .pass-modal-close:hover {
                            background: rgba(255,255,255,0.2);
                        }
                    </style>
                    <div class="pass-modal-content">
                        <div class="pass-modal-header" style="position: relative;">
                            <button class="pass-modal-close" onclick="document.getElementById('passModal').remove()">
                                <i class="fas fa-times"></i>
                            </button>
                            <h2>${style.title}</h2>
                            <p>${style.subtitle}</p>
                        </div>
                        <div class="pass-modal-success">
                            <i class="fas fa-check-circle"></i>
                            <span>Registration confirmed! Your pass is ready.</span>
                        </div>
                        <div class="pass-modal-body">
                            <div class="pass-preview" id="passPreview">
                                <div class="pass-preview-name">${fullName}</div>
                                <div class="pass-preview-inst">${institution}</div>
                                <div class="pass-preview-badges">${badgesHtml || '<span class="pass-badge">Conference Access</span>'}</div>
                                <div style="display: flex; justify-content: center; margin: 16px 0;">
                                    <canvas id="passQrCanvas" width="120" height="120"></canvas>
                                </div>
                                <div class="pass-preview-id">${registrationId}</div>
                            </div>
                            <div class="pass-modal-info">
                                <h4><i class="fas fa-mobile-alt" style="margin-right: 8px; color: var(--gold);"></i>Your Digital Pass</h4>
                                <ul>
                                    <li>A confirmation email with your pass has been sent to <strong>${email}</strong></li>
                                    <li>Save it to your phone's home screen for quick access</li>
                                    <li>Show the QR code at registration to check in</li>
                                </ul>
                            </div>
                            <div class="pass-modal-actions">
                                <button class="pass-modal-btn primary" onclick="PassSystem.downloadPass('${registrationId}', '${eventConfig.event}')">
                                    <i class="fas fa-download"></i> Download Pass
                                </button>
                                <button class="pass-modal-btn secondary" onclick="PassSystem.resendEmail('${email}', '${registrationId}')">
                                    <i class="fas fa-envelope"></i> Resend Email
                                </button>
                                <button class="pass-modal-btn secondary" onclick="document.getElementById('passModal').remove()">
                                    <i class="fas fa-check"></i> Done
                                </button>
                            </div>
                        </div>
                    </div>
                `;
                document.body.appendChild(modal);

                // Generate QR code on the pass
                if (typeof QRCode !== 'undefined') {
                    const passQrCanvas = document.getElementById('passQrCanvas');
                    if (passQrCanvas) {
                        const qrData = JSON.stringify({
                            type: 'PLEXUS2026',
                            userId: userData.id || '',
                            regId: registrationId,
                            name: fullName,
                            email: email
                        });
                        QRCode.toCanvas(passQrCanvas, qrData, {
                            width: 120, margin: 1,
                            color: { dark: '#0f172a', light: '#ffffff' }
                        });
                    }
                }

                // Close on background click
                modal.addEventListener('click', (e) => {
                    if (e.target === modal) modal.remove();
                });
            },

            // Download pass as PNG image
            downloadPass(registrationId, event) {
                const passEl = document.getElementById('passPreview');
                if (!passEl) {
                    this.showToast('Pass not found. Please try again.');
                    return;
                }

                this.showToast('Preparing your pass for download...');

                if (typeof html2canvas !== 'undefined') {
                    html2canvas(passEl, {
                        scale: 3,
                        backgroundColor: null,
                        useCORS: true,
                        allowTaint: true
                    }).then(canvas => {
                        const link = document.createElement('a');
                        link.download = 'plexus-2026-pass.png';
                        link.href = canvas.toDataURL('image/png');
                        link.click();
                        this.showToast('Pass downloaded! Your digital pass has also been sent to your email.');
                    }).catch(err => {
                        console.error('Pass download failed:', err);
                        window.print();
                    });
                } else {
                    // Fallback: print
                    window.print();
                }
            },

            // Resend confirmation email
            resendEmail(email, registrationId) {
                this.showToast(`Confirmation email resent to ${email}`);
            },

            // Show toast notification
            showToast(message) {
                message = (window.mxLocalizeToast ? window.mxLocalizeToast(message) : message);
                const toast = document.createElement('div');
                toast.setAttribute('role', 'status');
                toast.setAttribute('aria-live', 'polite');
                toast.style.cssText = 'position: fixed; bottom: 24px; left: 50%; transform: translateX(-50%); background: var(--ink); color: white; padding: 16px 24px; border-radius: 12px; box-shadow: 0 10px 40px rgba(0,0,0,0.3); z-index: 100001; font-size: 14px; display: flex; align-items: center; gap: 12px;';
                toast.innerHTML = '<i class="fas fa-check-circle" style="color: #2f6b3a;"></i> ';
                toast.appendChild(document.createTextNode(message));
                document.body.appendChild(toast);
                setTimeout(() => {
                    toast.style.opacity = '0';
                    toast.style.transition = 'opacity 0.3s';
                    setTimeout(() => toast.remove(), 300);
                }, 3000);
            }
        };

        // =========================================
        // REWARDS PORTAL - Med&X Rewards Program
        // =========================================
        // =========================================
        // MED&X REWARDS — server-backed members-club ledger.
        // Source of truth = points_ledger via /api/rewards/summary.
        // No client minting: legacy award/add methods are inert stubs kept
        // only so older call sites do not throw. Earning happens server-side.
        // =========================================
        const RewardsPortal = {
            data: null,
            _ledgerLimit: 12,
            // Legacy-compat shape read by dashboard/account widgets.
            userRewards: { pointsBalance: 0, lifetime: 0, tier: 'member', coupons: [] },

            // Documented economy defaults (member summary does not expose earn settings).
            EARN_ROWS: [
                { icon: 'fa-receipt', titleKey: 'rw.earnPayTitle', subKey: 'rw.earnPaySub', valKey: 'rw.earnPayVal' },
                { icon: 'fa-qrcode', titleKey: 'rw.earnCheckTitle', subKey: 'rw.earnCheckSub', val: '+100' },
                { icon: 'fa-user-check', titleKey: 'rw.earnProfTitle', subKey: 'rw.oneTime', val: '+50' },
                { icon: 'fa-envelope', titleKey: 'rw.earnVerifyTitle', subKey: 'rw.oneTime', val: '+25' }
            ],

            REASONS: {
                payment: { labelKey: 'rw.earnPayTitle', icon: 'fa-receipt' },
                checkin: { labelKey: 'rw.earnCheckTitle', icon: 'fa-qrcode' },
                profile: { labelKey: 'rw.rProfile', icon: 'fa-user-check' },
                verify: { labelKey: 'rw.rVerify', icon: 'fa-envelope' },
                admin_adjust: { labelKey: 'rw.rAdjust', icon: 'fa-sliders-h' },
                redeem: { labelKey: 'rw.rRedeem', icon: 'fa-gift' }
            },

            init() { this.load(); },

            async load() {
                try {
                    const d = await UserPortal.api('/api/rewards/summary');
                    this.data = d;
                    this.userRewards.pointsBalance = d.balance || 0;
                    this.userRewards.lifetime = d.lifetime_points || 0;
                    this.userRewards.coupons = (d.redemptions || []).map(r => ({
                        code: r.coupon_code,
                        value: r.coupon_value_eur,
                        used: r.status === 'used'
                    }));
                    this._checkEarnToast(d.balance || 0);
                    this.render();
                    this.updateAllDisplays();
                } catch (e) {
                    console.error('rewards load error', e);
                    const led = document.getElementById('rw2Ledger');
                    if (led) led.innerHTML = '<div class="rw2-empty"><i class="fas fa-exclamation-circle"></i>' + t('rw.loadErr') + '</div>';
                }
            },

            render() {
                if (!this.data) return;
                this.renderHero();
                this.renderEarn();
                this.renderTiers();
                this.renderCodes();
                this.renderLedger();
            },

            renderHero() {
                const b = document.getElementById('rw2Balance');
                const l = document.getElementById('rw2Lifetime');
                const mp = document.getElementById('rw2MinPurchase');
                if (b) b.textContent = this._fmtNum(this.data.balance);
                if (l) l.textContent = this._fmtNum(this.data.lifetime_points);
                if (mp) mp.textContent = '€' + (this.data.min_purchase || 50);
            },

            renderEarn() {
                const wrap = document.getElementById('rw2Earn');
                if (!wrap) return;
                wrap.innerHTML = this.EARN_ROWS.map(r => (
                    '<div class="rw2-earn-row">' +
                        '<div class="rw2-earn-ico"><i class="fas ' + r.icon + '"></i></div>' +
                        '<div class="rw2-earn-txt"><b>' + escapeHtml(t(r.titleKey)) + '</b><span>' + escapeHtml(t(r.subKey)) + '</span></div>' +
                        '<div class="rw2-earn-val">' + (r.valKey ? t(r.valKey) : r.val) + '</div>' +
                    '</div>'
                )).join('');
            },

            renderTiers() {
                const wrap = document.getElementById('rw2Tiers');
                if (!wrap) return;
                const tiers = (this.data.tiers || []).slice().sort((a, b) => a.points - b.points);
                const balance = this.data.balance || 0;
                // Best affordable tier = highest-points tier the member can afford.
                let bestPoints = -1;
                tiers.forEach(t => { if (balance >= t.points && t.points > bestPoints) bestPoints = t.points; });
                wrap.innerHTML = tiers.map(t => {
                    const affordable = balance >= t.points;
                    const isBest = t.points === bestPoints;
                    let btn, need = '';
                    if (isBest) {
                        btn = '<button class="rw2-tier-btn primary" onclick="RewardsPortal.redeem(' + t.points + ')">' + window.t('rw.tierRedeem') + '</button>';
                    } else if (affordable) {
                        btn = '<button class="rw2-tier-btn ghost" onclick="RewardsPortal.redeem(' + t.points + ')">' + window.t('rw.tierRedeem') + '</button>';
                    } else {
                        btn = '<button class="rw2-tier-btn locked" disabled>' + window.t('rw.tierLocked') + '</button>';
                        need = window.t('rw.tierMore', { n: RewardsPortal._fmtNum(t.points - balance) });
                    }
                    return (
                        '<div class="rw2-tier' + (isBest ? ' best' : '') + '">' +
                            '<div class="rw2-tier-euro">€' + t.euros + '</div>' +
                            '<div class="rw2-tier-pts">' + RewardsPortal._fmtNum(t.points) + ' ' + window.t('rw.pointsWord') + '</div>' +
                            btn +
                            '<div class="rw2-tier-need">' + need + '</div>' +
                        '</div>'
                    );
                }).join('');
            },

            renderCodes() {
                const wrap = document.getElementById('rw2Codes');
                if (!wrap) return;
                const reds = this.data.redemptions || [];
                if (!reds.length) {
                    wrap.innerHTML = '<div class="rw2-empty"><i class="fas fa-ticket-alt"></i>' + t('rw.noCodes') + '</div>';
                    return;
                }
                wrap.innerHTML = reds.map(r => {
                    const st = (r.status || 'active').toLowerCase();
                    const active = st === 'active';
                    return (
                        '<div class="rw2-code">' +
                            '<span class="rw2-code-mono">' + escapeHtml(r.coupon_code) + '</span>' +
                            '<span class="rw2-code-meta">€' + r.coupon_value_eur + (active ? ' · ' + t('rw.exp') + ' ' + this._fmtDate(r.expires_at) : '') + '</span>' +
                            '<span class="rw2-code-status ' + st + '">' + (st==='active'?t('rw.stActive'):(st==='used'?t('rw.stUsed'):(st==='expired'?t('rw.stExpired'):st))) + '</span>' +
                            (active ? '<button class="rw2-code-copy" title="' + t('rw.copyCode') + '" onclick="RewardsPortal.copy(\'' + r.coupon_code + '\')"><i class="fas fa-copy"></i></button>' : '') +
                        '</div>'
                    );
                }).join('');
            },

            renderLedger() {
                const wrap = document.getElementById('rw2Ledger');
                const more = document.getElementById('rw2More');
                if (!wrap) return;
                const rows = this.data.ledger || [];
                if (!rows.length) {
                    wrap.innerHTML = '<div class="rw2-empty"><i class="fas fa-clock"></i>' + t('rw.noActivity') + '</div>';
                    if (more) more.style.display = 'none';
                    return;
                }
                const shown = rows.slice(0, this._ledgerLimit);
                wrap.innerHTML = shown.map(row => {
                    const meta = this.REASONS[row.reason] || { labelKey: null, label: row.reason, icon: 'fa-circle' };
                    const pos = row.delta >= 0;
                    const title = row.note ? row.note : (meta.labelKey ? t(meta.labelKey) : meta.label);
                    return (
                        '<div class="rw2-led-row">' +
                            '<div class="rw2-led-ico"><i class="fas ' + meta.icon + '"></i></div>' +
                            '<div class="rw2-led-txt"><b>' + escapeHtml(title) + '</b><span>' + this._fmtDate(row.created_at) + '</span></div>' +
                            '<div class="rw2-led-delta ' + (pos ? 'pos' : 'neg') + '">' + (pos ? '+' : '') + RewardsPortal._fmtNum(row.delta) + '</div>' +
                        '</div>'
                    );
                }).join('');
                if (more) more.style.display = rows.length > this._ledgerLimit ? '' : 'none';
            },

            showMoreLedger() {
                this._ledgerLimit += 24;
                this.renderLedger();
            },

            // ===== Redeem flow =====
            redeem(points) {
                if (!this.data) return;
                const tier = (this.data.tiers || []).find(t => t.points === points);
                if (!tier) return;
                if ((this.data.balance || 0) < points) {
                    Toast.warning(t('rw.tNeedMore', { n: this._fmtNum(points - (this.data.balance || 0)) }));
                    return;
                }
                const card = document.getElementById('rw2ModalCard');
                card.innerHTML =
                    '<div class="rw2-modal-eyebrow">' + t('rw.confirmRedemption') + '</div>' +
                    '<h3 class="rw2-modal-title">' + t('rw.redeemQ', { n: this._fmtNum(points), e: tier.euros }) + '</h3>' +
                    '<p class="rw2-modal-text">' + t('rw.redeemText', { m: (this.data.min_purchase || 50) }) + '</p>' +
                    '<div class="rw2-modal-actions">' +
                        '<button class="rw2-modal-btn ghost" onclick="RewardsPortal.closeModal()">' + t('rw.cancel') + '</button>' +
                        '<button class="rw2-modal-btn primary" id="rw2ConfirmBtn" onclick="RewardsPortal.confirmRedeem(' + points + ')">' + t('rw.tierRedeem') + '</button>' +
                    '</div>';
                this._openModal();
            },

            async confirmRedeem(points) {
                const btn = document.getElementById('rw2ConfirmBtn');
                if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i>'; }
                try {
                    const res = await UserPortal.api('/api/rewards/redeem', {
                        method: 'POST',
                        body: JSON.stringify({ tier: points })
                    });
                    this._showCoupon(res);
                    // Reflect the new balance without a full toast (this is a spend, not an earn).
                    localStorage.setItem('medx_rewards_last_balance', String(res.balance));
                    this.load();
                } catch (e) {
                    const b = e && e.body;
                    if (b && b.error === 'Insufficient points') {
                        Toast.warning(t('rw.tNotEnough', { have: this._fmtNum(b.balance), need: this._fmtNum(b.needed || points) }));
                    } else {
                        Toast.error((b && b.error) || t('rw.tRedeemFail'));
                    }
                    this.closeModal();
                }
            },

            _showCoupon(res) {
                const card = document.getElementById('rw2ModalCard');
                card.innerHTML =
                    '<div class="rw2-modal-eyebrow">' + t('rw.couponReady') + '</div>' +
                    '<h3 class="rw2-modal-title">' + t('rw.couponOff', { e: res.coupon_value_eur }) + '</h3>' +
                    '<div class="rw2-modal-code" id="rw2CouponCode">' + escapeHtml(res.coupon_code) + '</div>' +
                    '<button class="rw2-modal-btn primary" style="width:100%;" onclick="RewardsPortal.copy(\'' + res.coupon_code + '\')"><i class="fas fa-copy"></i> ' + t('rw.copyCode') + '</button>' +
                    '<p class="rw2-modal-hint">' + t('rw.couponHint', { d: this._fmtDate(res.expires_at), m: (res.min_purchase || 50) }) + '</p>' +
                    '<div class="rw2-modal-actions"><button class="rw2-modal-btn ghost" onclick="RewardsPortal.closeModal()">' + t('rw.done') + '</button></div>';
                this._openModal();
            },

            copy(code) {
                const done = () => Toast.success(t('rw.tCopied'));
                if (navigator.clipboard && navigator.clipboard.writeText) {
                    navigator.clipboard.writeText(code).then(done).catch(() => this._fallbackCopy(code, done));
                } else {
                    this._fallbackCopy(code, done);
                }
            },

            _fallbackCopy(code, done) {
                const ta = document.createElement('textarea');
                ta.value = code; ta.style.position = 'fixed'; ta.style.left = '-9999px';
                document.body.appendChild(ta); ta.select();
                try { document.execCommand('copy'); done(); } catch (e) { Toast.info(t('rw.tYourCode', { code: code })); }
                ta.remove();
            },

            _openModal() {
                const m = document.getElementById('rw2Modal');
                if (m) m.classList.add('open');
                this._esc = (e) => { if (e.key === 'Escape') this.closeModal(); };
                document.addEventListener('keydown', this._esc);
            },

            closeModal() {
                const m = document.getElementById('rw2Modal');
                if (m) m.classList.remove('open');
                if (this._esc) { document.removeEventListener('keydown', this._esc); this._esc = null; }
            },

            // ===== Earn notice (display-only diff) =====
            _checkEarnToast(balance) {
                try {
                    const key = 'medx_rewards_last_balance';
                    const prev = localStorage.getItem(key);
                    if (prev !== null && prev !== '') {
                        const diff = balance - parseInt(prev, 10);
                        if (diff > 0) {
                            var _pn = RewardsPortal._fmtNum(diff); if (window.MedXI18n && MedXI18n.get && MedXI18n.get()==='hr') { var _pm = diff%100, _pd = diff%10; var _pw = (_pd===1&&_pm!==11)?'bod':((_pd>=2&&_pd<=4&&!(_pm>=12&&_pm<=14))?'boda':'bodova'); Toast.success('Skupili ste ' + _pn + ' ' + _pw + '.'); } else { Toast.success('You earned ' + _pn + ' point' + (diff === 1 ? '' : 's') + '.'); }
                        }
                    }
                    localStorage.setItem(key, String(balance));
                } catch (e) {}
            },

            _fmtDate(s) {
                if (!s) return '';
                let d = new Date(s);
                if (isNaN(d.getTime())) { d = new Date(String(s).replace(' ', 'T')); }
                if (isNaN(d.getTime())) return '';
                return d.toLocaleDateString((window.MedXI18n && MedXI18n.dateLocale) ? MedXI18n.dateLocale() : 'en-US', { day: 'numeric', month: 'short', year: 'numeric' });
            },

            // Locale-aware integer formatting for points / tier costs. HR uses '.' as the thousands
            // separator, so a bare toLocaleString() renders 1000 as '1,000' and reads as one-point-zero
            // to a Croatian professional. Follows the active MedXI18n locale, not the browser locale.
            _fmtNum(n) {
                var loc = (window.MedXI18n && MedXI18n.dateLocale) ? MedXI18n.dateLocale() : 'en-US';
                return Number(n || 0).toLocaleString(loc);
            },

            // ===== Cross-app displays (nav chips + legacy hidden widgets) =====
            updateAllDisplays() {
                const balance = this.userRewards.pointsBalance || 0;
                const fmt = this._fmtNum(balance);
                const chip = document.getElementById('upAcctRewardsChip');
                if (chip) chip.textContent = fmt;
                const mmx = document.getElementById('mymedxRewardsBalance');
                if (mmx) mmx.textContent = fmt;
                // Legacy hidden widgets — keep in sync so nothing looks stale if revealed.
                const hd = document.getElementById('hubDropdownPoints');
                if (hd) hd.innerHTML = (typeof Dashboard!=='undefined' && Dashboard._ptsHTML) ? Dashboard._ptsHTML(fmt) : (fmt + '<span>pts</span>');
                const mc = document.getElementById('memberCardPoints');
                if (mc) mc.textContent = fmt;
                // Dashboard snapshot "Points balance" tile — same ledger total as the account
                // chip so the two can never diverge (fixes chip 410 vs tile 0).
                const ds = document.getElementById('dsPoints');
                if (ds) ds.textContent = fmt;
            },

            // ===== Legacy-compat stubs (NO client minting) =====
            loadUserRewards() { this.load(); },
            getNextTierInfo() {
                return {
                    currentTier: 'member', currentTierName: 'Med&X Member',
                    nextTier: null, nextTierName: null, pointsNeeded: 0, progress: 0,
                    pointsBalance: this.userRewards.pointsBalance || 0,
                    totalPointsEarned: this.userRewards.lifetime || 0
                };
            },
            awardActivityPoints() { return 0; },
            awardPurchasePoints() { return 0; },
            saveUserRewards() {},
            showPointsEarned() {},
            showPointsPopup() {}
        };

        // NetworkActions helper — dashboard widget interactions
        const NetworkActions = {
            acceptConnection(connectionId) {
                const btn = event.currentTarget;
                btn.disabled = true;
                btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i>';

                UserPortal.api('/api/networking/connections/' + connectionId, {
                    method: 'PUT',
                    body: JSON.stringify({ status: 'accepted' })
                }).then(() => {
                    btn.innerHTML = '<i class="fas fa-check"></i> Accepted';
                    btn.style.background = '#2f6b3a';
                    btn.style.color = 'white';
                    RewardsPortal.showPointsEarned(10, 'Connection accepted!');
                }).catch(() => {
                    btn.innerHTML = '<i class="fas fa-check"></i> Accepted';
                    btn.style.background = '#2f6b3a';
                    btn.style.color = 'white';
                });
            },

            sendConnectionRequest(userId) {
                const btn = event.currentTarget;
                btn.disabled = true;
                btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i>';

                UserPortal.api('/api/networking/connections', {
                    method: 'POST',
                    body: JSON.stringify({ receiver_id: userId })
                }).then(() => {
                    btn.innerHTML = '<i class="fas fa-check"></i> Sent';
                    btn.style.background = 'rgba(47, 107, 58, 0.1)';
                    btn.style.color = '#2f6b3a';
                    RewardsPortal.showPointsEarned(5, 'Connection request sent!');
                }).catch(() => {
                    btn.innerHTML = '<i class="fas fa-check"></i> Sent';
                    btn.style.background = 'rgba(47, 107, 58, 0.1)';
                    btn.style.color = '#2f6b3a';
                });
            },

            openMessage(userId) {
                // Navigate to Network section with messages tab
                UserPortal.showSection('network');
                setTimeout(() => {
                    NetworkingPortal.showTab('messages');
                }, 300);
                Toast.success('Opening messages...');
            }
        };

        // =========================================
        // MY MED&X PORTAL - Personal hub
        // =========================================
        const MyMedXPortal = {
            init() {
                this.renderMyEvents();
                this.renderTierCard();
                this.renderMembershipCardVisual();
                this.loadPhoto();
                this.loadPoints();
                this.renderPrograms();
                this.renderQRCodes();
                this.renderInterests();
                this.renderNetworkStats();
                this.renderRecord();
                this.renderGuestPasses();
                this.renderGiving();
                this.renderMyCme();
            },

            // MY EVENTS — one card per upcoming registration across ALL event types, each with
            // its QR ticket and calendar link (backend: /api/my/events). Hidden when empty.
            renderMyEvents() {
                var el = document.getElementById('mymedxMyEvents');
                if (!el) return;
                var token = (typeof UserPortal !== 'undefined' && UserPortal.token) || localStorage.getItem('medx_user_token');
                var apiBase = (typeof API_BASE !== 'undefined') ? API_BASE : '';
                fetch(apiBase + '/api/my/events', { headers: token ? { 'Authorization': 'Bearer ' + token } : {} })
                    .then(function(r){ return r.ok ? r.json() : null; })
                    .then(function(data){
                        if (!data || !Array.isArray(data.upcoming) || !data.upcoming.length) { el.style.display = 'none'; el.innerHTML = ''; return; }
                        var esc = function(x){ return String(x == null ? '' : x).replace(/[&<>"]/g, function(c){ return ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'})[c]; }); };
                        var fmtDate = function(d){
                            if (!d) return '';
                            try { return new Date(String(d).slice(0,10) + 'T12:00:00').toLocaleDateString((typeof dateLocale === 'function') ? dateLocale() : 'en-GB', { weekday: 'short', day: 'numeric', month: 'short', year: 'numeric' }); } catch(e){ return d; }
                        };
                        var cards = data.upcoming.map(function(ev){
                            var badge = ev.waitlisted
                                ? '<span style="background:rgba(180,83,9,0.12);color:#b45309;padding:2px 10px;border-radius:10px;font-size:10.5px;font-weight:700;text-transform:uppercase;">' + esc(t('myev.waitlist')) + '</span>'
                                : (ev.checked_in ? '<span style="background:rgba(22,163,74,0.12);color:#16a34a;padding:2px 10px;border-radius:10px;font-size:10.5px;font-weight:700;text-transform:uppercase;">' + esc(t('myev.checkedIn')) + '</span>' : '');
                            var btns = '';
                            if (ev.ticket) btns += '<a href="' + esc(ev.ticket) + '" target="_blank" rel="noopener" style="display:inline-flex;align-items:center;gap:6px;padding:7px 14px;border:1px solid var(--up-border,#e5e0d8);border-radius:9px;font-size:12.5px;font-weight:600;color:var(--up-text,#1d1d1f);text-decoration:none;"><i class="fas fa-qrcode"></i> ' + esc(t('myev.ticket')) + '</a>';
                            if (ev.calendar) btns += '<a href="' + esc(ev.calendar) + '" style="display:inline-flex;align-items:center;gap:6px;padding:7px 14px;border:1px solid var(--up-border,#e5e0d8);border-radius:9px;font-size:12.5px;font-weight:600;color:var(--up-text,#1d1d1f);text-decoration:none;margin-left:8px;"><i class="far fa-calendar-plus"></i> ' + esc(t('myev.calendar')) + '</a>';
                            return '<div style="border:1px solid var(--up-border,#e5e0d8);border-radius:12px;padding:14px 16px;">'
                                + '<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:10px;flex-wrap:wrap;">'
                                + '<div style="font-weight:600;color:var(--up-text,#1d1d1f);">' + esc(ev.title) + '</div>' + badge + '</div>'
                                + '<div style="font-size:12.5px;color:var(--up-text-muted,#6b6b70);margin-top:6px;">'
                                + esc(fmtDate(ev.date)) + (ev.venue ? ' &middot; ' + esc(ev.venue) : '') + '</div>'
                                + (btns ? '<div style="margin-top:10px;">' + btns + '</div>' : '')
                                + '</div>';
                        }).join('');
                        var pastLine = (data.past && data.past.length)
                            ? '<p style="font-size:11.5px;color:var(--up-text-muted,#6b6b70);margin:10px 0 0;padding-left:4px;">' + esc(t('myev.pastCount', { n: data.past.length })) + '</p>' : '';
                        el.innerHTML = '<h3 style="font-size:16px;font-weight:600;color:var(--up-text,#1d1d1f);margin:0 0 8px;padding-left:4px;">' + esc(t('myev.title')) + '</h3>'
                            + '<div style="display:flex;flex-direction:column;gap:12px;">' + cards + '</div>' + pastLine;
                        el.style.display = '';
                    })
                    .catch(function(){ el.style.display = 'none'; });
            },

            // The member's own CME record (queue 5a5c) — read-only self-view. Official chamber
            // credit, kept distinct from rewards points. Hidden entirely when there is no record.
            renderMyCme() {
                var el = document.getElementById('mymedxCme');
                if (!el) return;
                var token = (typeof UserPortal !== 'undefined' && UserPortal.token) || localStorage.getItem('medx_user_token');
                var apiBase = (typeof API_BASE !== 'undefined') ? API_BASE : '';
                fetch(apiBase + '/api/plexus/cme/my', { headers: token ? { 'Authorization': 'Bearer ' + token } : {} })
                    .then(function(r){ return r.ok ? r.json() : []; })
                    .then(function(rows){
                        if (!Array.isArray(rows) || !rows.length) { el.style.display = 'none'; el.innerHTML = ''; return; }
                        var esc = function(x){ return String(x == null ? '' : x).replace(/[&<>"]/g, function(c){ return ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'})[c]; }); };
                        var items = rows.map(function(r){
                            var when = r.consent_at ? String(r.consent_at).slice(0,10) : '';
                            var pts = (r.points_value != null) ? ('<span style="font-weight:700;color:var(--crimson,#9b1b22);">' + esc(r.points_value) + '</span> <span style="font-size:12px;color:var(--up-text-muted,#6b6b70);">' + esc(t('cme.pointsUnit')) + '</span>') : '';
                            return '<div style="border:1px solid var(--up-border,#e5e0d8);border-radius:12px;padding:14px 16px;">'
                                + '<div style="display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;">'
                                + '<div style="font-weight:600;color:var(--up-text,#1d1d1f);">' + esc(r.conference_name || '') + '</div>'
                                + '<div>' + pts + '</div></div>'
                                + '<div style="font-size:12px;color:var(--up-text-muted,#6b6b70);margin-top:8px;">OIB ' + esc(r.oib || '') + ' &middot; ' + esc(t('cme.myConsentedOn')) + ' ' + esc(when) + '</div>'
                                + '</div>';
                        }).join('');
                        el.innerHTML = '<h3 style="font-size:16px;font-weight:600;color:var(--up-text,#1d1d1f);margin:0 0 8px;padding-left:4px;">' + esc(t('cme.myTitle')) + '</h3>'
                            + '<p class="mmx-purchase-intro">' + esc(t('cme.myIntro')) + '</p>'
                            + '<div style="display:flex;flex-direction:column;gap:12px;">' + items + '</div>'
                            + '<p style="font-size:11px;color:var(--up-text-muted,#6b6b70);margin:10px 0 0;padding-left:4px;">' + esc(t('cme.myProtected')) + '</p>';
                        el.style.display = '';
                    })
                    .catch(function(){ el.style.display = 'none'; });
            },

            // Member-initiated guest passes ("Bring a colleague") — renders the plexus + bridges hub.
            renderGuestPasses() { try { if (window.GuestPass) GuestPass.renderHub('mymedxGuestPasses'); } catch(e){} },

            // Giving / supporter recognition (WARMTH PACK). Reads the real giving signal from
            // /api/member/giving. The thank-you card is shown to every supporter — including quiet
            // gala/forum members — because it is dignified, not gamified. The Supporter chip lives on
            // the recognition rail (renderRecognition), which sits in the quiet-hidden sidecol.
            _giving: undefined,
            renderGiving() {
                var self = this;
                var token = (typeof UserPortal !== 'undefined' && UserPortal.token) || localStorage.getItem('medx_user_token');
                var apiBase = (typeof API_BASE !== 'undefined') ? API_BASE : '';
                fetch(apiBase + '/api/member/giving', { headers: token ? { 'Authorization': 'Bearer ' + token } : {} })
                    .then(function(r){ return r.ok ? r.json() : null; })
                    .then(function(d){ self._giving = d || { is_supporter: false }; self._paintGiving(); if (self._regs) self.renderRecognition(self._regs); })
                    .catch(function(){ self._giving = { is_supporter: false }; self._paintGiving(); });
            },
            _paintGiving() {
                var el = document.getElementById('mymedxGiving');
                if (!el) return;
                var g = this._giving || {};
                if (!g.is_supporter) { el.style.display = 'none'; el.innerHTML = ''; return; }
                el.style.display = '';
                el.innerHTML = '<div class="mmx-giving">'
                    + '<div class="mmx-giving-eyebrow"><i class="fas fa-hand-holding-heart"></i> <span>' + t('mmx.givingEyebrow') + '</span></div>'
                    + '<div class="mmx-giving-title">' + t('mmx.givingTitle') + '</div>'
                    + '<p class="mmx-giving-body">' + t('mmx.givingBody') + '</p>'
                + '</div>';
            },

            // ===== Member data (single fetch → Recognition + Wallet) =====
            renderTierCard() { this._loadMemberData(); },

            _loadMemberData() {
                if (this._memberDataLoading) return;
                this._memberDataLoading = true;
                var self = this;
                var token = (typeof UserPortal !== 'undefined' && UserPortal.token) || localStorage.getItem('medx_user_token');
                var apiBase = typeof API_BASE !== 'undefined' ? API_BASE : '';
                var wc = document.getElementById('mymedxQRCodes');
                if (wc) wc.innerHTML = '<div style="grid-column:1/-1;text-align:center;padding:20px;color:var(--muted);font-size:13px;">' + t('mmx.loadingTickets') + '</div>';
                fetch(apiBase + '/api/registrations/my', { headers: token ? { 'Authorization': 'Bearer ' + token } : {} })
                    .then(function(r){ return r.ok ? r.json() : Promise.reject('err'); })
                    .then(function(regs){
                        self._regs = Array.isArray(regs) ? regs : [];
                        self._saveTicketCache(self._regs);
                        self.renderRecognition(self._regs); self._renderWalletCards(self._regs); self.renderPurchases(self._regs);
                    })
                    .catch(function(){
                        // R3-3 offline ticket suite: the API is unreachable (event-day dead spots,
                        // airplane mode). Fall back to the tickets saved on this device so the
                        // boarding pass + QR still show. The service worker NEVER caches /api/ —
                        // this cache is app state, written only from a fresh authenticated fetch.
                        var cached = self._cachedRegs();
                        if (cached && cached.length) {
                            self._regs = cached;
                            self.renderRecognition(cached); self._renderWalletCards(cached, true); self.renderPurchases(cached);
                        } else {
                            self._regs = []; self.renderRecognition([]); self._renderWalletCards(null); self.renderPurchases(null);
                        }
                    })
                    .then(function(){ self._memberDataLoading = false; });
            },

            // Quiet recognition — real badges from real signals only (replaces the points/tier arcade)
            renderRecognition(regs) {
                var container = document.getElementById('mymedxTierCard');
                if (!container) return;
                regs = regs || [];
                var user = (typeof UserPortal !== 'undefined' && UserPortal.user) || {};
                var name = (user.name || ((user.first_name||'') + ' ' + (user.last_name||'')).trim() || 'Member');
                var badges = [];
                var attended = regs.filter(function(r){ return r.checked_in; }).length;
                var registered = regs.length;
                var years = {};
                regs.forEach(function(r){ var y=(r.start_date||'').slice(0,4); if(y) years[y]=1; });
                var yearCount = Object.keys(years).length;
                if (attended > 0) badges.push({icon:'fa-check-circle', label:t('mmx.bAttended'), color:'var(--success)'});
                if (registered > 0) badges.push({icon:'fa-ticket-alt', label: registered + ' ' + this._plural(registered,'registration','registrations','prijava','prijave','prijava'), color:'var(--crimson)'});
                if (yearCount > 1) badges.push({icon:'fa-star', label: this._isHR() ? (yearCount + ' ' + this._plural(yearCount,'godina','godina','godina','godine','godina') + ' sudjelovanja') : (yearCount + '-year participant'), color:'var(--gold-dim)'});
                try { if ((JSON.parse(localStorage.getItem('medx_accelerator_applications')||'[]')).length) badges.push({icon:'fa-rocket', label:t('mmx.bAccelApplicant'), color:'var(--cat-accelerator)'}); } catch(e){}
                try { if (localStorage.getItem('forum_member')==='1' || (JSON.parse(localStorage.getItem('forum_registered_events')||'[]')).length) badges.push({icon:'fa-landmark', label:t('mmx.bForumParticipant'), color:'var(--cat-forum)'}); } catch(e){}
                // Supporter chip — gamification, so quiet members never see it (fail-closed via the
                // sidecol CSS gate AND this allowPlayful() check).
                if (this._giving && this._giving.is_supporter && (typeof MedXQuiet === 'undefined' || MedXQuiet.allowPlayful())) badges.push({icon:'fa-hand-holding-heart', label:t('mmx.bSupporter'), color:'var(--gold-dim, var(--gold))'});

                var badgesHtml = badges.length
                    ? '<div class="mmx-badges">' + badges.map(function(b){
                        return '<span style="display:inline-flex;align-items:center;gap:6px;padding:6px 12px;border-radius:999px;font-size:12px;font-weight:600;color:'+b.color+';background:var(--paper-2);border:1px solid var(--line);"><i class="fas '+b.icon+'"></i>'+b.label+'</span>';
                      }).join('') + '</div>'
                    : '<div style="margin-top:12px;font-size:13px;color:var(--muted);">' + t('mmx.recogEmpty') + '</div>';

                container.innerHTML =
                    '<div class="mmx-recog-head"><i class="fas fa-medal"></i> ' + t('mmx.recogHead') + '</div>'
                    + '<div id="mymedxMembershipMeta"></div>'
                    + badgesHtml;
                this._renderMembershipMeta();
            },

            // Membership layer (menu 22) — member type / member-since / standing.
            // Bronze/Platinum tier language stays out of here (rewards only).
            _renderMembershipMeta() {
                var el = document.getElementById('mymedxMembershipMeta');
                if (!el || typeof MemberState === 'undefined') return;
                MemberState.loadMeta().then(function(m){
                    if (!m) { el.innerHTML = ''; return; }
                    var chip = function(icon, label){
                        return '<span style="display:inline-flex;align-items:center;gap:6px;padding:6px 12px;border-radius:999px;font-size:12px;font-weight:600;color:var(--ink-soft, var(--ink));background:var(--paper-2);border:1px solid var(--line);"><i class="fas '+icon+'" style="color:var(--gold-dim, var(--gold));"></i>'+label+'</span>';
                    };
                    var chips = [];
                    var typeLabel = MemberState.localType(m);
                    if (typeLabel) chips.push(chip('fa-user-md', typeLabel));
                    var sinceY = m.member_since ? String(m.member_since).slice(0,4) : '';
                    if (sinceY) chips.push(chip('fa-calendar-check', t('mmx.memberSince',{y:sinceY})));
                    chips.push(chip('fa-shield-halved', MemberState.localStanding(m) || t('mmx.standingDefault')));
                    el.innerHTML = '<div style="display:flex;flex-wrap:wrap;gap:8px;margin-top:12px;">' + chips.join('') + '</div>';
                });
            },

            // My Record — permanent wall of events, certificates, badges (menu 22).
            renderRecord() {
                var el = document.getElementById('mymedxRecord');
                if (!el) return;
                el.innerHTML = '<div style="text-align:center;padding:20px;color:var(--muted);font-size:13px;">' + t('mmx.loadingRecord') + '</div>';
                var tkn = (typeof UserPortal !== 'undefined' && UserPortal.token) || localStorage.getItem('medx_user_token');
                var base = (typeof API_BASE !== 'undefined' ? API_BASE : '');
                fetch(base + '/api/member/record', { headers: tkn ? { 'Authorization': 'Bearer ' + tkn } : {} })
                    .then(function(r){ return r.ok ? r.json() : Promise.reject('err'); })
                    .then(function(data){ MyMedXPortal._record = data; MyMedXPortal._renderRecordHtml(data); })
                    .catch(function(){ MyMedXPortal._renderRecordHtml(null); });
            },

            _fmtRecordDate(start, end) { return this._fmtDateRange(start, end); },

            _renderRecordHtml(data) {
                var el = document.getElementById('mymedxRecord');
                if (!el) return;
                if (!data) {
                    el.innerHTML = MedXState.render({ tone: 'error', icon: 'fa-cloud-arrow-down', body: t('mmx.recordLoadErr'), actionLabel: t('state.retry'), actionOnclick: 'MyMedXPortal.renderRecord()' });
                    return;
                }
                var card = function(inner){ return '<div style="background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:16px;margin-bottom:14px;box-shadow:var(--shadow-sm);">' + inner + '</div>'; };
                var sectionTitle = function(icon, label){ return '<div style="display:flex;align-items:center;gap:8px;font-size:13px;font-weight:700;color:var(--ink);margin-bottom:12px;"><i class="fas '+icon+'" style="color:var(--crimson);"></i>' + label + '</div>'; };

                // Events
                var events = (data.events || []);
                var eventsHtml;
                if (events.length) {
                    eventsHtml = events.map(function(ev){
                        var chipColor, chipLabel;
                        if (ev.attended) { chipColor = 'var(--success)'; chipLabel = t('mmx.stAttended'); }
                        else if (ev.paid) { chipColor = 'var(--success)'; chipLabel = t('tk.confirmed'); }
                        else { chipColor = 'var(--warning)'; chipLabel = t('mmx.stRegistered'); }
                        var dates = MyMedXPortal._fmtDateRange(ev.start_date, ev.end_date);
                        return '<div style="display:flex;align-items:center;gap:12px;padding:10px 0;border-top:1px solid var(--line);">'
                            + '<div style="width:34px;height:34px;border-radius:9px;background:var(--paper-2);display:flex;align-items:center;justify-content:center;flex-shrink:0;"><i class="fas fa-calendar-day" style="color:var(--crimson);font-size:14px;"></i></div>'
                            + '<div style="flex:1;min-width:0;"><div style="font-size:13px;font-weight:600;color:var(--ink);">' + escapeHtml(ev.title) + '</div>'
                            + '<div style="font-size:12px;color:var(--muted);">' + escapeHtml(ev.ticket_name || '') + (dates ? (' · ' + dates) : '') + '</div></div>'
                            + '<span style="white-space:nowrap;font-size:10px;font-weight:700;letter-spacing:.04em;text-transform:uppercase;color:' + chipColor + ';background:var(--paper-2);border:1px solid var(--line);padding:4px 9px;border-radius:999px;">' + chipLabel + '</span>'
                        + '</div>';
                    }).join('');
                    eventsHtml = eventsHtml.replace('border-top:1px solid var(--line);', ''); // first row flush
                } else {
                    eventsHtml = '<div style="font-size:13px;color:var(--muted);">' + t('mmx.eventsEmpty') + ' <a href="#" onclick="event.preventDefault();UserPortal.showSection(\'plexus\');" style="color:var(--crimson);font-weight:600;">' + t('tk.browseEvents') + '</a></div>';
                }

                // Certificates
                var certs = (data.certificates || []);
                var certsHtml;
                if (certs.length) {
                    certsHtml = certs.map(function(c){
                        var y = c.issue_date ? String(c.issue_date).slice(0,4) : '';
                        return '<div style="display:flex;align-items:center;gap:12px;padding:10px 0;">'
                            + '<div style="width:34px;height:34px;border-radius:9px;background:var(--paper-2);display:flex;align-items:center;justify-content:center;flex-shrink:0;"><i class="fas fa-certificate" style="color:var(--gold-dim, var(--gold));font-size:14px;"></i></div>'
                            + '<div style="flex:1;min-width:0;"><div style="font-size:13px;font-weight:600;color:var(--ink);">' + escapeHtml(c.title) + '</div>'
                            + '<div style="font-size:12px;color:var(--muted);">' + (c.number ? escapeHtml(c.number) : t('mmx.certificate')) + (y ? (' · ' + y) : '') + '</div></div>'
                            + '<button onclick="MyMedXPortal.downloadCertificate(\'' + escapeHtml(c.id) + '\')" style="white-space:nowrap;background:transparent;border:1px solid var(--line-strong, var(--line));color:var(--ink);border-radius:8px;padding:6px 10px;font-size:12px;font-weight:600;cursor:pointer;"><i class="fas fa-download" style="margin-right:5px;"></i>' + t('mmx.download') + '</button>'
                            + '<button onclick="MyMedXPortal.shareCertificate(\'' + escapeHtml(c.id) + '\')" style="white-space:nowrap;background:transparent;border:1px solid var(--line-strong, var(--line));color:var(--ink);border-radius:8px;padding:6px 10px;font-size:12px;font-weight:600;cursor:pointer;margin-left:6px;"><i class="fas fa-share-nodes" style="margin-right:5px;"></i>' + t('mmx.share') + '</button>'
                        + '</div>';
                    }).join('');
                } else {
                    certsHtml = '<div style="display:flex;align-items:center;gap:12px;padding:12px;border:1px dashed var(--line);border-radius:12px;">'
                        + '<div style="width:34px;height:34px;border-radius:9px;background:var(--paper-2);display:flex;align-items:center;justify-content:center;flex-shrink:0;"><i class="fas fa-certificate" style="color:var(--muted);font-size:14px;"></i></div>'
                        + '<div><div style="font-size:13px;font-weight:600;color:var(--ink-soft, var(--ink));">' + t('mmx.certOfAttendance') + ' <span style="font-size:10px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);border:1px solid var(--line);border-radius:999px;padding:2px 7px;margin-left:6px;">' + t('mmx.example') + '</span></div>'
                        + '<div style="font-size:12px;color:var(--muted);">' + t('mmx.certsEmpty') + '</div></div></div>';
                }

                // Badges (quiet recognition)
                var badges = (data.badges || []);
                var badgesHtml;
                if (badges.length) {
                    badgesHtml = '<div style="display:flex;flex-wrap:wrap;gap:8px;">' + badges.map(function(b){
                        return '<span style="display:inline-flex;align-items:center;gap:6px;padding:6px 12px;border-radius:999px;font-size:12px;font-weight:600;color:var(--ink-soft, var(--ink));background:var(--paper-2);border:1px solid var(--line);"><i class="fas ' + (b.icon || 'fa-award') + '" style="color:var(--gold-dim, var(--gold));"></i>' + escapeHtml(b.name || t('mmx.badge')) + '</span>';
                    }).join('') + '</div>';
                } else {
                    badgesHtml = '<div style="display:flex;flex-wrap:wrap;gap:8px;align-items:center;">'
                        + '<span style="display:inline-flex;align-items:center;gap:6px;padding:6px 12px;border-radius:999px;font-size:12px;font-weight:600;color:var(--muted);background:var(--paper-2);border:1px dashed var(--line);"><i class="fas fa-award"></i>' + t('mmx.bFirstConf') + '</span>'
                        + '<span style="display:inline-flex;align-items:center;gap:6px;padding:6px 12px;border-radius:999px;font-size:12px;font-weight:600;color:var(--muted);background:var(--paper-2);border:1px dashed var(--line);"><i class="fas fa-microphone"></i>' + t('mmx.bPresenter') + '</span>'
                        + '<span style="font-size:10px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:var(--muted);border:1px solid var(--line);border-radius:999px;padding:3px 8px;">' + t('mmx.example') + '</span>'
                        + '</div><div style="font-size:12px;color:var(--muted);margin-top:8px;">' + t('mmx.badgesEmpty') + '</div>';
                }

                el.innerHTML =
                    card(sectionTitle('fa-calendar-check', t('mmx.secEvents')) + eventsHtml)
                  + card(sectionTitle('fa-certificate', t('mmx.secCerts')) + certsHtml)
                  + card(sectionTitle('fa-medal', t('mmx.secBadges')) + badgesHtml);
            },

            // Channel-agnostic certificate sharing — LinkedIn add-to-profile (certification-URL pattern),
            // X / Facebook / WhatsApp share links, and copy-link. One surface, multiple destinations. The
            // shared target is the PUBLIC /verify-certificate page (proves the number is genuine).
            shareCertificate(certId) {
                var cert = ((this._record && this._record.certificates) || []).filter(function(c){ return c.id === certId; })[0];
                if (!cert) { if (typeof Toast !== 'undefined') Toast.error(t('toast.certNotFound')); return; }
                var number = cert.number || cert.certificate_number || '';
                var certName = cert.title || 'Med&X Certificate';
                var verifyUrl = location.origin + '/verify-certificate?n=' + encodeURIComponent(number);
                var dd = cert.issue_date ? new Date(cert.issue_date) : null;
                var y = dd ? dd.getFullYear() : '';
                var m = dd ? (dd.getMonth() + 1) : '';
                var shareText = t('mmx.shareText') + ' — ' + certName;
                var enc = encodeURIComponent;
                var links = {
                    linkedin: 'https://www.linkedin.com/profile/add?startTask=CERTIFICATION_NAME&name=' + enc(certName) + '&organizationName=' + enc('Med&X') + (y ? ('&issueYear=' + y) : '') + (m ? ('&issueMonth=' + m) : '') + (number ? ('&certId=' + enc(number)) : '') + '&certUrl=' + enc(verifyUrl),
                    x: 'https://twitter.com/intent/tweet?text=' + enc(shareText) + '&url=' + enc(verifyUrl),
                    facebook: 'https://www.facebook.com/sharer/sharer.php?u=' + enc(verifyUrl),
                    whatsapp: 'https://wa.me/?text=' + enc(shareText + ' ' + verifyUrl)
                };
                var ov = document.createElement('div');
                ov.style.cssText = 'position:fixed;inset:0;background:rgba(0,0,0,.5);z-index:10050;display:flex;align-items:center;justify-content:center;padding:16px;';
                var row = function(id, icon, label, color){ return '<button data-act="' + id + '" style="display:flex;align-items:center;gap:10px;width:100%;text-align:left;padding:12px 14px;border:1px solid var(--line, #e6e0d6);border-radius:10px;background:var(--paper, #fff);color:var(--ink, #15110f);font-size:14px;font-weight:600;cursor:pointer;margin-bottom:8px;"><i class="fab ' + icon + '" style="width:18px;color:' + color + ';"></i>' + label + '</button>'; };
                ov.innerHTML = '<div style="background:var(--paper, #fff);border-radius:16px;max-width:400px;width:100%;padding:22px;box-shadow:0 20px 60px rgba(0,0,0,.3);">'
                    + '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px;"><h3 style="margin:0;font-size:17px;color:var(--ink, #15110f);">' + t('mmx.shareCertTitle') + '</h3>'
                    + '<button data-act="close" aria-label="' + t('mmx.close') + '" style="background:none;border:none;font-size:22px;cursor:pointer;color:var(--muted, #6b6258);line-height:1;">&times;</button></div>'
                    + '<p style="margin:0 0 16px;font-size:13px;color:var(--muted, #6b6258);line-height:1.6;">' + t('mmx.shareCertLede') + '</p>'
                    + row('linkedin', 'fa-linkedin', t('mmx.shareLinkedIn'), '#0a66c2')
                    + row('x', 'fa-x-twitter', t('mmx.shareX'), '#111')
                    + row('facebook', 'fa-facebook', t('mmx.shareFacebook'), '#1877f2')
                    + row('whatsapp', 'fa-whatsapp', t('mmx.shareWhatsApp'), '#25d366')
                    + '<button data-act="copy" style="display:flex;align-items:center;gap:10px;width:100%;text-align:left;padding:12px 14px;border:1px solid var(--line, #e6e0d6);border-radius:10px;background:var(--paper-2, #f5f2ec);color:var(--ink, #15110f);font-size:14px;font-weight:600;cursor:pointer;"><i class="fas fa-link" style="width:18px;color:var(--gold-dim, #c9a962);"></i>' + t('mmx.copyLink') + '</button>'
                    + '</div>';
                var close = function(){ try { document.body.removeChild(ov); } catch(e){} };
                ov.addEventListener('click', function(e){
                    if (e.target === ov) return close();
                    var btn = e.target.closest('[data-act]'); if (!btn) return;
                    var act = btn.getAttribute('data-act');
                    if (act === 'close') return close();
                    if (act === 'copy') { try { navigator.clipboard.writeText(verifyUrl); if (typeof Toast !== 'undefined') Toast.success(t('mmx.linkCopied')); } catch(err){ mxPrompt({ title: t('mmx.copyLinkTitle'), message: t('mmx.copyLinkManual'), defaultValue: verifyUrl }); } return close(); }
                    if (links[act]) { window.open(links[act], '_blank', 'noopener,width=680,height=640'); return close(); }
                });
                document.body.appendChild(ov);
            },

            // Client-side certificate render — printable page from the stored cert data.
            // Attendance/participation certificate. Bilingual (EN + formal-Vi HR) print artifact. The ONE
            // org-level founder signature (org_settings, shared with the admin portal via GET
            // /api/org/signature) is rendered above the typed name; until one is uploaded the signature line
            // shows clean blank space above the typed name. Same-origin data:image/png URL — no taint.
            downloadCertificate(certId) {
                var cert = ((this._record && this._record.certificates) || []).filter(function(c){ return c.id === certId; })[0];
                if (!cert) { if (typeof Toast !== 'undefined') Toast.error(t('toast.certNotFound')); return; }
                var user = (typeof UserPortal !== 'undefined' && UserPortal.user) || {};
                var name = (user.name || ((user.first_name||'') + ' ' + (user.last_name||'')).trim() || 'Med&X Member');
                var win = window.open('', '_blank');
                if (!win) { if (typeof Toast !== 'undefined') Toast.error(t('toast.allowPopupsDl')); return; }
                var self = this;
                var render = function(sig){ self._writeCertificate(win, cert, name, sig); };
                // Fetch the shared org signature once, then cache it for subsequent downloads.
                if (self._orgSig !== undefined) { render(self._orgSig); }
                else {
                    var base = (typeof API_BASE !== 'undefined' ? API_BASE : '');
                    fetch(base + '/api/org/signature').then(function(r){ return r.ok ? r.json() : null; })
                        .then(function(d){ self._orgSig = (d && d.signature) || null; render(self._orgSig); })
                        .catch(function(){ self._orgSig = null; render(null); });
                }
            },
            _writeCertificate(win, cert, name, sig) {
                var dloc = (window.MedXI18n && MedXI18n.dateLocale) ? MedXI18n.dateLocale() : 'en-US';
                var issued = cert.issue_date ? new Date(cert.issue_date).toLocaleDateString(dloc,{year:'numeric',month:'long',day:'numeric'}) : '';
                var rawEvent = cert.title.replace(' — Certificate of Attendance','');
                var sigMark = sig ? ('<img src="' + sig + '" alt="Signature">') : '';
                var meta = (cert.number ? (escapeHtml(t('mmx.certNo')) + ' ' + escapeHtml(cert.number)) : '')
                    + (issued ? (' &nbsp;·&nbsp; ' + escapeHtml(t('mmx.certIssued')) + ' ' + escapeHtml(issued)) : '');
                win.document.write('<!DOCTYPE html><html><head><meta charset="UTF-8"><title>' + escapeHtml(cert.title) + '</title>'
                    + '<link href="https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,500;9..144,600&family=Inter:wght@400;500;600&display=swap" rel="stylesheet">'
                    + '<style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:Inter,sans-serif;color:#15110f;padding:0}'
                    + '.cert{width:100%;max-width:900px;margin:24px auto;border:2px solid #c9a962;padding:56px;text-align:center;background:#fbf9f6;position:relative}'
                    + '.cert:before{content:"";position:absolute;inset:12px;border:1px solid #c9a962;pointer-events:none}'
                    + '.brand{font-family:Fraunces,serif;font-size:26px;font-weight:600;color:#9b1b22;letter-spacing:.04em}'
                    + '.kicker{font-size:12px;letter-spacing:.28em;text-transform:uppercase;color:#6b6258;margin:28px 0 12px}'
                    + '.name{font-family:Fraunces,serif;font-size:40px;font-weight:600;margin:8px 0 18px}'
                    + '.body{font-size:15px;color:#403a36;line-height:1.7;max-width:560px;margin:0 auto}'
                    + '.sign{margin:44px auto 0;max-width:330px}'
                    + '.sign-mark{height:60px;display:flex;align-items:flex-end;justify-content:center;margin-bottom:6px}'
                    + '.sign-mark img{max-height:60px;max-width:280px;object-fit:contain}'
                    + '.sign-rule{width:230px;height:1px;background:#c9a962;margin:0 auto 8px}'
                    + '.sign-name{font-family:Fraunces,serif;font-size:17px;font-weight:600;color:#15110f}'
                    + '.sign-role{font-size:11px;letter-spacing:.14em;text-transform:uppercase;color:#6b6258;margin-top:3px}'
                    + '.meta{margin-top:30px;font-size:13px;color:#6b6258}@media print{body{padding:0}.cert{margin:0;border:2px solid #c9a962}}</style></head><body>'
                    + '<div class="cert"><div class="brand">Med&amp;X</div>'
                    + '<div class="kicker">' + escapeHtml(t('mmx.certOfAttendance')) + '</div>'
                    + '<div class="name">' + escapeHtml(name) + '</div>'
                    + '<div class="body">' + escapeHtml(t('mmx.certBody', { event: rawEvent })) + '</div>'
                    + '<div class="sign"><div class="sign-mark">' + sigMark + '</div><div class="sign-rule"></div>'
                    + '<div class="sign-name">' + escapeHtml(t('mmx.certSignName')) + '</div>'
                    + '<div class="sign-role">' + escapeHtml(t('mmx.certSignRole')) + '</div></div>'
                    + '<div class="meta">' + meta + '</div>'
                    + '</div><script>setTimeout(function(){window.print();},400);<\/script></body></html>');
                win.document.close();
            },

            // Copies the member's real, read-only Med&X record link (server page at /r/:token).
            // Falls back to a friendly error toast if the link cannot be prepared.
            shareRecord() {
                var copy = function(link){
                    var done = function(){ if (typeof Toast !== 'undefined' && Toast.success) Toast.success(t('toast.recordCopied')); };
                    try {
                        if (navigator.clipboard && navigator.clipboard.writeText) {
                            navigator.clipboard.writeText(link).then(done).catch(function(){ done(); });
                        } else {
                            var ta = document.createElement('textarea'); ta.value = link; document.body.appendChild(ta); ta.select();
                            try { document.execCommand('copy'); } catch (e) {}
                            document.body.removeChild(ta); done();
                        }
                    } catch (e) { done(); }
                };
                var tkn = (typeof UserPortal !== 'undefined' && UserPortal.token) || localStorage.getItem('medx_user_token');
                var base = (typeof API_BASE !== 'undefined' ? API_BASE : '');
                fetch(base + '/api/member/share-record-link', { headers: tkn ? { 'Authorization': 'Bearer ' + tkn } : {} })
                    .then(function(r){ return r.ok ? r.json() : null; })
                    .then(function(d){
                        if (d && d.path) { copy(window.location.origin + d.path); }
                        else if (typeof Toast !== 'undefined' && Toast.error) Toast.error(t('mmx.shareErr'));
                    })
                    .catch(function(){ if (typeof Toast !== 'undefined' && Toast.error) Toast.error(t('mmx.shareErr')); });
            },

            // ===== Share your membership: public verify link + LinkedIn credential =====
            // Available to EVERY member, including quiet / senior profiles — a professional
            // credential, not gamification. Link + LinkedIn params come from /api/member/verify-link.
            _verifyLinkData: null,
            _fetchVerifyLink() {
                if (this._verifyLinkData) return Promise.resolve(this._verifyLinkData);
                var self = this;
                var tok = (typeof UserPortal !== 'undefined' && UserPortal.token) || localStorage.getItem('medx_user_token');
                var base = (typeof API_BASE !== 'undefined' ? API_BASE : '');
                return fetch(base + '/api/member/verify-link', { headers: tok ? { 'Authorization': 'Bearer ' + tok } : {} })
                    .then(function(r){ return r.ok ? r.json() : null; })
                    .then(function(d){ if (d && d.token) self._verifyLinkData = d; return self._verifyLinkData; })
                    .catch(function(){ return null; });
            },
            _verifyUrl(d) { return window.location.origin + '/verify/' + d.token; },
            _linkedInUrl(d) {
                var p = new URLSearchParams();
                p.set('startTask', 'CERTIFICATION_NAME');
                p.set('name', d.cert_name || 'Med&X Membership');
                p.set('organizationName', d.organization || 'Med&X');
                if (d.issue_year) p.set('issueYear', d.issue_year);
                p.set('certUrl', this._verifyUrl(d));
                return 'https://www.linkedin.com/profile/add?' + p.toString();
            },
            copyVerifyLink() {
                var self = this;
                this._fetchVerifyLink().then(function(d){
                    if (!d) { if (typeof Toast !== 'undefined' && Toast.error) Toast.error(t('mmx.shareErr')); return; }
                    var url = self._verifyUrl(d);
                    var done = function(){ if (typeof Toast !== 'undefined' && Toast.success) Toast.success(t('mmx.shareCopied')); };
                    try {
                        if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(url).then(done).catch(function(){ done(); });
                        else { var ta = document.createElement('textarea'); ta.value = url; document.body.appendChild(ta); ta.select(); try { document.execCommand('copy'); } catch (e) {} document.body.removeChild(ta); done(); }
                    } catch (e) { done(); }
                });
            },
            addToLinkedIn() {
                var self = this;
                this._fetchVerifyLink().then(function(d){
                    if (!d) { if (typeof Toast !== 'undefined' && Toast.error) Toast.error(t('mmx.shareErr')); return; }
                    window.open(self._linkedInUrl(d), '_blank', 'noopener');
                });
            },

            renderPrograms() {
                const container = document.getElementById('mymedxPrograms');
                if (!container) return;

                // Dynamic status from localStorage
                const plexusRegistered = !!localStorage.getItem('plexus_registered');
                const acceleratorApps = JSON.parse(localStorage.getItem('medx_accelerator_applications') || '[]');
                const forumEvents = JSON.parse(localStorage.getItem('forum_registered_events') || '[]');

                const programs = [
                    { name: t('mmx.progPlexus'), statusKey: plexusRegistered ? 'registered' : 'open', icon: 'fa-atom', color: '#c2484e', section: 'plexus' },
                    { name: t('mmx.progAccel'), statusKey: acceleratorApps.length > 0 ? 'applied' : 'appsOpen', icon: 'fa-rocket', color: '#b06a1f', section: 'accelerator' },
                    { name: t('mmx.progForum'), statusKey: forumEvents.length > 0 ? 'events' : 'byInvite', icon: 'fa-landmark', color: '#fb923c', section: 'forum' }
                ];

                const statusColors = { registered: '#2f6b3a', applied: '#b8801f', byInvite: '#6b6258', open: '#6b6258', appsOpen: '#6b6258', events: '#9b1b22' };
                const statusLabels = { open: t('mmx.progOpen'), registered: t('mmx.progRegistered'), applied: t('mmx.progApplied'), appsOpen: t('mmx.progAppsOpen'), byInvite: t('mmx.progByInvite'), events: t('mmx.progEvents', { n: forumEvents.length }) };
                // Event count uses brand crimson
                if (forumEvents.length > 0) void 0;

                container.innerHTML = programs.map(function(p) {
                    return '<div onclick="UserPortal.showSection(\'' + p.section + '\')" style="background: var(--up-bg, #ffffff); border: 1px solid var(--up-border, #d2d2d7); border-radius: 12px; padding: 14px 16px; display: flex; align-items: center; gap: 12px; cursor: pointer; transition: transform 0.15s ease;" onmouseover="this.style.transform=\'scale(1.01)\'" onmouseout="this.style.transform=\'scale(1)\'">' +
                        '<div style="width: 40px; height: 40px; border-radius: 10px; background: var(--paper-2); display: flex; align-items: center; justify-content: center;">' +
                            '<i class="fas ' + p.icon + '" style="color: var(--crimson); font-size: 16px;"></i>' +
                        '</div>' +
                        '<div style="flex: 1;">' +
                            '<div style="font-size: 14px; font-weight: 600; color: var(--up-text, #1d1d1f);">' + p.name + '</div>' +
                        '</div>' +
                        '<span style="font-size: 11px; font-weight: 600; color: ' + (statusColors[p.statusKey] || '#94a3b8') + '; background: ' + (statusColors[p.statusKey] || '#94a3b8') + '18; padding: 3px 10px; border-radius: 14px;">' + statusLabels[p.statusKey] + '</span>' +
                        '<i class="fas fa-chevron-right" style="color: var(--up-text-muted, var(--muted)); font-size: 12px;"></i>' +
                    '</div>';
                }).join('');
            },

            renderQRCodes() { this._loadMemberData(); },

            _fmtDateRange(start, end) {
                if (!start) return '';
                try {
                    var s = new Date(start + 'T00:00:00');
                    if (end && end !== start) {
                        var e = new Date(end + 'T00:00:00');
                        return s.toLocaleDateString('en-US',{month:'short',day:'numeric'}) + ' – ' + e.toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});
                    }
                    return s.toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});
                } catch(e){ return start; }
            },

            // Real wallet: tickets from /api/registrations/my, QR rendered from the actual ticket_qr_code (same value the scanner reads).
            // R3-3: `offline` marks a render from the on-device ticket cache (medx_ticket_cache) when
            // the API is unreachable — the boarding pass must still show at the venue door.
            _renderWalletCards(regs, offline) {
                var container = document.getElementById('mymedxQRCodes');
                if (!container) return;
                if (regs === null) {
                    container.innerHTML = MedXState.render({ gridSpan: true, tone: 'error', icon: 'fa-cloud-arrow-down', body: t('tk.loadError'), actionLabel: t('state.retry'), actionOnclick: 'MyMedXPortal.renderQRCodes()' });
                    return;
                }
                if (!regs.length) {
                    container.innerHTML = '<div style="grid-column:1/-1;text-align:center;padding:28px 20px;border:1px dashed var(--line);border-radius:12px;">'
                        + '<div style="font-size:26px;margin-bottom:8px;">🎟️</div>'
                        + '<div style="font-weight:700;color:var(--ink);margin-bottom:4px;font-family:var(--serif);">' + t('tk.noTickets') + '</div>'
                        + '<div style="font-size:13px;color:var(--muted);margin-bottom:14px;">' + t('tk.noTicketsSub') + '</div>'
                        + '<button onclick="UserPortal.showSection(\'plexus\')" style="background:var(--crimson);color:#fff;border:none;border-radius:10px;padding:9px 16px;font-weight:600;font-size:13px;cursor:pointer;">' + t('tk.browseEvents') + '</button>'
                        + '</div>';
                    return;
                }
                var jobs = [];
                var offlineNote = offline
                    ? '<div style="grid-column:1/-1;display:flex;align-items:center;gap:9px;background:var(--paper-2);border:1px solid var(--line);border-radius:10px;padding:10px 14px;font-size:12.5px;color:var(--ink-soft);"><i class="fas fa-wifi" style="color:var(--warning);"></i> ' + t('tk.offlineTickets') + '</div>'
                    : '';
                container.innerHTML = offlineNote + regs.map(function(r, i){
                    var paid = (r.payment_status === 'paid');
                    var free = (!r.amount_paid || Number(r.amount_paid) === 0);
                    var statusLabel = paid ? t('tk.paid') : (free ? t('tk.confirmed') : t('tk.paymentPending'));
                    var statusColor = (paid || free) ? 'var(--success)' : 'var(--warning)';
                    var dates = MyMedXPortal._fmtDateRange(r.start_date, r.end_date);
                    var venue = [r.venue_name, r.venue_city].filter(Boolean).join(', ');
                    var amount = (r.amount_paid != null && Number(r.amount_paid) > 0) ? ('€' + Number(r.amount_paid).toFixed(2)) : (free ? t('tk.free') : '');
                    var qrId = 'walletQR_' + i;
                    var qrData = r.ticket_qr_code || ('MEDX:' + (r.id || ''));
                    jobs.push({ id: qrId, data: qrData });
                    var checkedIn = !!r.checked_in;
                    return '<div style="background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:16px;display:flex;flex-direction:column;gap:12px;box-shadow:var(--shadow-sm);">'
                        + '<div style="display:flex;justify-content:space-between;align-items:flex-start;gap:10px;">'
                            + '<div style="min-width:0;"><div style="font-size:15px;font-weight:700;color:var(--ink);font-family:var(--serif);line-height:1.2;">' + (r.conference_name || t('tk.medxEvent')) + '</div>'
                            + '<div style="font-size:12px;color:var(--muted);margin-top:2px;">' + (r.ticket_name || r.registration_type || t('tk.ticket')) + '</div></div>'
                            + '<span style="white-space:nowrap;font-size:10px;font-weight:700;letter-spacing:.04em;text-transform:uppercase;color:' + statusColor + ';background:var(--paper-2);border:1px solid var(--line);padding:4px 9px;border-radius:999px;">' + statusLabel + '</span>'
                        + '</div>'
                        + (dates ? '<div style="font-size:12px;color:var(--ink-soft);"><i class="fas fa-calendar" style="width:16px;color:var(--muted);"></i> ' + dates + '</div>' : '')
                        + (venue ? '<div style="font-size:12px;color:var(--ink-soft);"><i class="fas fa-location-dot" style="width:16px;color:var(--muted);"></i> ' + venue + '</div>' : '')
                        + '<div style="background:#ffffff;border:1px solid var(--line);border-radius:10px;padding:12px;display:flex;flex-direction:column;align-items:center;gap:6px;">'
                            + '<div id="' + qrId + '" style="width:148px;height:148px;display:flex;align-items:center;justify-content:center;"></div>'
                            + '<div style="font-size:11px;color:var(--muted);">' + (checkedIn ? '<span style="color:var(--success);font-weight:700;"><i class="fas fa-check-circle"></i> ' + t('tk.checkedIn') + '</span>' : t('tk.showAtCheckin')) + '</div>'
                        + '</div>'
                        + '<div style="display:flex;justify-content:space-between;align-items:center;gap:8px;">'
                            + '<div style="font-size:12px;color:var(--muted);">' + (amount ? ('<strong style="color:var(--ink);">' + amount + '</strong>') : '') + (r.invoice_number ? (' · #' + r.invoice_number) : '') + '</div>'
                            + (r.start_date ? '<button onclick="MyMedXPortal.addToCalendar(' + i + ')" style="background:transparent;border:1px solid var(--line-strong);color:var(--ink);border-radius:10px;padding:6px 10px;font-size:12px;font-weight:600;cursor:pointer;"><i class="fas fa-calendar-plus"></i> ' + t('tk.addToCalendar') + '</button>' : '')
                        + '</div>'
                        + '<div style="display:flex;gap:8px;margin-top:2px;">'
                            + '<button onclick="MyMedXPortal.downloadTicket(' + i + ')" style="flex:1;display:inline-flex;align-items:center;justify-content:center;gap:7px;background:var(--crimson);color:#fff;border:none;border-radius:10px;padding:10px 12px;font-size:13px;font-weight:700;cursor:pointer;"><i class="fas fa-download"></i> ' + t('tk.downloadTicket') + '</button>'
                            + '<button onclick="MyMedXPortal.saveTicketPdf(' + i + ')" style="display:inline-flex;align-items:center;justify-content:center;gap:7px;background:transparent;color:var(--ink);border:1px solid var(--line-strong);border-radius:10px;padding:10px 14px;font-size:13px;font-weight:600;cursor:pointer;"><i class="fas fa-file-pdf"></i> PDF</button>'
                        + '</div>'
                        + '<button onclick="MyMedXPortal.openPresentMode(' + i + ')" style="display:inline-flex;align-items:center;justify-content:center;gap:8px;background:#14110f;color:#e8d5a8;border:1px solid #14110f;border-radius:10px;padding:11px 12px;font-size:13px;font-weight:700;cursor:pointer;margin-top:2px;"><i class="fas fa-qrcode"></i> ' + t('tk.present') + '</button>'
                        + '<div style="display:flex;gap:8px;">'
                            + '<button onclick="MyMedXPortal.addTicketToGoogleWallet(' + i + ')" style="flex:1;display:inline-flex;align-items:center;justify-content:center;gap:7px;background:transparent;color:var(--ink);border:1px solid var(--line-strong);border-radius:10px;padding:9px 10px;font-size:12px;font-weight:600;cursor:pointer;"><i class="fab fa-google"></i> Google Wallet</button>'
                            + '<button onclick="MyMedXPortal.addTicketToAppleWallet(' + i + ')" style="flex:1;display:inline-flex;align-items:center;justify-content:center;gap:7px;background:transparent;color:var(--ink);border:1px solid var(--line-strong);border-radius:10px;padding:9px 10px;font-size:12px;font-weight:600;cursor:pointer;opacity:.55;"><i class="fab fa-apple"></i> Apple Wallet</button>'
                        + '</div>'
                        + '<div style="text-align:center;font-size:11px;color:var(--muted);margin-top:2px;"><i class="fas fa-circle-check" style="color:var(--success);"></i> ' + t('tk.offlineReady') + '</div>'
                    + '</div>';
                }).join('');
                // Render REAL QR codes from the ticket_qr_code value
                if (typeof QRCode !== 'undefined') {
                    jobs.forEach(function(job){
                        var el = document.getElementById(job.id);
                        if (!el) return;
                        QRCode.toCanvas(document.createElement('canvas'), job.data, { width: 148, margin: 1, color: { dark:'#15110f', light:'#ffffff' } }, function(err, canvas){
                            if (err || !canvas) { el.textContent = 'QR unavailable'; el.style.fontSize='11px'; el.style.color='var(--muted)'; return; }
                            canvas.style.width='148px'; canvas.style.height='148px'; el.appendChild(canvas);
                        });
                    });
                } else {
                    jobs.forEach(function(job){ var el=document.getElementById(job.id); if(el){ el.textContent='QR unavailable'; el.style.fontSize='11px'; el.style.color='var(--muted)'; } });
                }
                // Manifest shortcut ("My Ticket" → /?app=1&view=ticket): once the wallet has real
                // tickets, open Present mode on the most relevant one (first not-yet-finished event,
                // else the newest registration).
                if (this._autoPresent && regs.length) {
                    this._autoPresent = false;
                    var pick = 0;
                    try {
                        var today = new Date().toISOString().slice(0, 10);
                        for (var k = 0; k < regs.length; k++) {
                            if (((regs[k].end_date || regs[k].start_date) || '') >= today) { pick = k; break; }
                        }
                    } catch (e) {}
                    var selfP = this;
                    setTimeout(function(){ selfP.openPresentMode(pick); }, 120);
                }
            },

            // Download an .ics for this registration's event (all-day; DTEND exclusive)
            addToCalendar(idx) {
                var r = (this._regs || [])[idx];
                if (!r || !r.start_date) return;
                var dtStart = (r.start_date || '').replace(/-/g,'');
                var endBase = r.end_date || r.start_date;
                var endDate = new Date(endBase + 'T00:00:00'); endDate.setDate(endDate.getDate()+1);
                var dtEnd = '' + endDate.getFullYear() + String(endDate.getMonth()+1).padStart(2,'0') + String(endDate.getDate()).padStart(2,'0');
                var loc = [r.venue_name, r.venue_city].filter(Boolean).join(', ');
                var uid = 'medx-' + (r.id || Math.random().toString(36).slice(2)) + '@medx.hr';
                var ics = ['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Med&X//Portal//EN','CALSCALE:GREGORIAN','BEGIN:VEVENT',
                    'UID:' + uid, 'DTSTART;VALUE=DATE:' + dtStart, 'DTEND;VALUE=DATE:' + dtEnd,
                    'SUMMARY:' + (r.conference_name || t('tk.medxEvent')), 'LOCATION:' + loc,
                    'DESCRIPTION:' + ((r.ticket_name || 'Ticket') + ' — Med&X'), 'END:VEVENT','END:VCALENDAR'].join('\r\n');
                var blob = new Blob([ics], { type: 'text/calendar;charset=utf-8' });
                var url = URL.createObjectURL(blob);
                var a = document.createElement('a');
                a.href = url; a.download = (r.conference_name || 'medx-event').replace(/[^a-z0-9]+/gi,'-').toLowerCase() + '.ics';
                document.body.appendChild(a); a.click(); document.body.removeChild(a);
                setTimeout(function(){ URL.revokeObjectURL(url); }, 1000);
                if (typeof Toast !== 'undefined' && Toast.success) Toast.success(t('toast.calDownloaded'));
            },

            // ===== Premium downloadable ticket + membership card (menu 22) =====
            // Client-side render: offscreen styled DOM -> html2canvas -> canvas -> PNG blob.
            // QR parity: the ticket QR encodes the EXACT same value the live wallet card
            // renders (r.ticket_qr_code || 'MEDX:'+id), and the membership QR reuses the
            // canonical profile-synced payload ({type:'PLEXUS2026', userId, regId, name}).
            // Apple Wallet .pkpass needs an Apple Developer signing cert (none yet) and Google
            // Wallet needs a Google Wallet API issuer account — both are a later upgrade path.
            _saveBlob(blob, filename) {
                var url = URL.createObjectURL(blob);
                var a = document.createElement('a');
                a.href = url; a.download = filename;
                document.body.appendChild(a); a.click(); document.body.removeChild(a);
                setTimeout(function(){ URL.revokeObjectURL(url); }, 1500);
            },

            // Resolve the signed-in member even if UserPortal.user has not finished loading,
            // so the membership QR always carries the real userId the scanner keys on.
            _currentUser() {
                var u = (typeof UserPortal !== 'undefined' && UserPortal.user) || null;
                if (u && (u.id || u.email)) return u;
                try { var d = JSON.parse(localStorage.getItem('medx_user_data') || 'null'); if (d && (d.id || d.email)) return d; } catch (e) {}
                return u || {};
            },

            _qrDataUrl(text, size, dark) {
                return new Promise(function(resolve){
                    if (typeof QRCode === 'undefined' || !QRCode.toDataURL) { resolve(null); return; }
                    QRCode.toDataURL(text, { width: size || 360, margin: 2, errorCorrectionLevel: 'M', color: { dark: dark || '#15110f', light: '#ffffff' } }, function(err, dataUrl){
                        resolve(err ? null : dataUrl);
                    });
                });
            },

            // Rasterize an offscreen node at 2x then downscale to the exact target size for
            // supersampled, phone-wallpaper-crisp output.
            async _rasterize(node, outW, outH) {
                if (typeof html2canvas === 'undefined') throw new Error('html2canvas not loaded');
                document.body.appendChild(node);
                try {
                    try { await document.fonts.load("600 96px 'Fraunces'"); await document.fonts.load("600 40px 'Inter'"); if (document.fonts && document.fonts.ready) await document.fonts.ready; } catch (e) {}
                    await new Promise(function(res){ setTimeout(res, 80); });
                    var big = await html2canvas(node, { scale: 2, backgroundColor: null, useCORS: true, allowTaint: true, logging: false, width: outW, height: outH, windowWidth: outW, windowHeight: outH, scrollX: 0, scrollY: 0 });
                    var out = document.createElement('canvas'); out.width = outW; out.height = outH;
                    var ctx = out.getContext('2d'); ctx.imageSmoothingEnabled = true; ctx.imageSmoothingQuality = 'high';
                    ctx.drawImage(big, 0, 0, outW, outH);
                    return out;
                } finally {
                    if (node.parentNode) node.parentNode.removeChild(node);
                }
            },

            _guestName(r) {
                var fromReg = [r && r.first_name, r && r.last_name].filter(Boolean).join(' ').trim();
                if (fromReg) return fromReg;
                var u = this._currentUser();
                var un = (u.name || ((u.first_name || '') + ' ' + (u.last_name || '')).trim());
                return un || 'Guest';
            },

            _composeTicket(r, qrUrl) {
                var name = this._guestName(r);
                var confName = r.conference_name || 'Med&X Event';
                var ticketName = r.ticket_name || r.registration_type || t('tk.ticket');
                var dates = this._fmtDateRange(r.start_date, r.end_date) || 'Dates to be announced';
                var venue = [r.venue_name, r.venue_city].filter(Boolean).join(', ') || 'Venue to be announced';
                var inv = r.invoice_number ? ('#' + r.invoice_number) : '';
                var el = document.createElement('div');
                el.style.cssText = "position:fixed;left:-10000px;top:0;z-index:-1;pointer-events:none;width:1080px;height:1920px;box-sizing:border-box;overflow:hidden;display:flex;flex-direction:column;background:linear-gradient(165deg,#1d1813,#14100d 55%,#0e0a08);font-family:'Inter',-apple-system,sans-serif;color:#ffffff;";
                el.innerHTML =
                    '<div style="height:12px;flex:0 0 auto;background:linear-gradient(90deg,#a38a4f,#c9a962,#e8d5a8,#c9a962,#a38a4f);"></div>'
                  + '<div style="position:relative;flex:0 0 640px;overflow:hidden;">'
                    + '<img src="/assets/gala/lord-smith-chancellor.jpg" crossorigin="anonymous" style="position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:50% 0%;">'
                    + '<div style="position:absolute;inset:0;background:linear-gradient(180deg,rgba(16,12,10,.78),rgba(16,12,10,.90) 60%,#14100d);"></div>'
                    + '<div style="position:absolute;inset:0;background:radial-gradient(115% 75% at 24% 26%,rgba(201,169,98,.13),transparent 58%);"></div>'
                    + '<div style="position:absolute;inset:0;box-sizing:border-box;padding:60px 64px;display:flex;flex-direction:column;justify-content:space-between;">'
                      + '<div style="display:flex;justify-content:space-between;align-items:flex-start;">'
                        + '<div style="display:inline-flex;align-items:center;background:#fbf9f6;border-radius:16px;padding:16px 24px;box-shadow:0 10px 28px rgba(0,0,0,.38);">'
                          + '<img src="/assets/images/medx-logo.png" crossorigin="anonymous" style="height:48px;display:block;">'
                        + '</div>'
                        + '<div style="text-align:right;padding-top:6px;">'
                          + '<div style="font-size:20px;letter-spacing:5px;text-transform:uppercase;color:#e8d5a8;font-weight:700;">Admit One</div>'
                          + '<div style="font-size:15px;letter-spacing:3px;text-transform:uppercase;color:rgba(255,255,255,.62);margin-top:6px;">Official Ticket</div>'
                        + '</div>'
                      + '</div>'
                      + '<div>'
                        + '<div style="font-size:22px;letter-spacing:6px;text-transform:uppercase;color:#c9a962;font-weight:700;margin-bottom:14px;">International Medical Conference</div>'
                        + '<div style="font-family:\'Fraunces\',Georgia,serif;font-size:100px;font-weight:600;line-height:.92;color:#ffffff;letter-spacing:-1px;">' + escapeHtml(confName) + '</div>'
                      + '</div>'
                    + '</div>'
                  + '</div>'
                  + '<div style="flex:1 1 auto;display:flex;flex-direction:column;justify-content:space-between;padding:58px 64px 0;box-sizing:border-box;">'
                    + '<div>'
                      + '<div style="font-size:20px;letter-spacing:5px;text-transform:uppercase;color:#c9a962;font-weight:700;">Guest</div>'
                      + '<div style="font-family:\'Fraunces\',Georgia,serif;font-size:76px;font-weight:600;line-height:1.02;color:#ffffff;margin:12px 0 26px;">' + escapeHtml(name) + '</div>'
                      + '<div style="display:inline-block;border:1.5px solid rgba(201,169,98,.55);color:#e8d5a8;border-radius:999px;padding:13px 28px;font-size:23px;letter-spacing:2px;text-transform:uppercase;font-weight:600;">' + escapeHtml(ticketName) + '</div>'
                      + '<div style="height:1px;background:linear-gradient(90deg,transparent,rgba(201,169,98,.5),transparent);margin:50px 0;"></div>'
                      + '<div style="display:flex;gap:48px;">'
                        + '<div style="flex:1;">'
                          + '<div style="font-size:18px;letter-spacing:3px;text-transform:uppercase;color:#c9a962;font-weight:700;margin-bottom:12px;">Dates</div>'
                          + '<div style="font-family:\'Fraunces\',Georgia,serif;font-size:40px;color:#ffffff;line-height:1.1;">' + escapeHtml(dates) + '</div>'
                        + '</div>'
                        + '<div style="flex:1;">'
                          + '<div style="font-size:18px;letter-spacing:3px;text-transform:uppercase;color:#c9a962;font-weight:700;margin-bottom:12px;">Venue</div>'
                          + '<div style="font-family:\'Fraunces\',Georgia,serif;font-size:40px;color:#ffffff;line-height:1.1;">' + escapeHtml(venue) + '</div>'
                        + '</div>'
                      + '</div>'
                    + '</div>'
                    + '<div>'
                      + '<div style="position:relative;height:2px;">'
                        + '<div style="border-top:3px dashed rgba(201,169,98,.42);"></div>'
                        + '<div style="position:absolute;left:-96px;top:-31px;width:64px;height:64px;border-radius:50%;background:#0e0a08;"></div>'
                        + '<div style="position:absolute;right:-96px;top:-31px;width:64px;height:64px;border-radius:50%;background:#0e0a08;"></div>'
                      + '</div>'
                      + '<div style="display:flex;flex-direction:column;align-items:center;padding:46px 0 42px;">'
                        + '<div style="background:#ffffff;border-radius:32px;padding:46px 46px 36px;display:flex;flex-direction:column;align-items:center;box-shadow:0 16px 44px rgba(0,0,0,.42);">'
                          + (qrUrl ? '<img src="' + qrUrl + '" style="width:400px;height:400px;display:block;">' : '<div style="width:400px;height:400px;display:flex;align-items:center;justify-content:center;color:#6b6258;font-size:18px;">QR unavailable</div>')
                          + '<div style="font-size:23px;letter-spacing:4px;text-transform:uppercase;color:#15110f;font-weight:700;margin-top:24px;">Show at check-in</div>'
                          + (inv ? '<div style="font-size:20px;color:#6b6258;margin-top:10px;font-variant-numeric:tabular-nums;">' + escapeHtml(inv) + '</div>' : '')
                        + '</div>'
                        + '<div style="font-size:20px;color:rgba(255,255,255,.55);letter-spacing:1px;margin-top:34px;">Med&amp;X &middot; medx.hr &middot; Zagreb, Croatia</div>'
                      + '</div>'
                    + '</div>'
                  + '</div>'
                  + '<div style="height:10px;flex:0 0 auto;background:linear-gradient(90deg,#a38a4f,#c9a962,#e8d5a8,#c9a962,#a38a4f);"></div>';
                return el;
            },

            // Downloadable membership card (PNG) — the NEW living-card artwork rendered static at card
            // ratio (1600x1000). Reuses the existing _rasterize path; only the artwork changed. The QR
            // is the exact frozen membership payload (built in downloadMembershipCard()).
            _composeMembership(name, meta, qrUrl, memberId) {
                var memberType = (meta && meta.member_type_label) || 'Med&X Member';
                var sinceYear = (meta && meta.member_since) ? String(meta.member_since).slice(0, 4) : '';
                var standing = (meta && meta.standing_label) || 'Member in good standing';
                var sinceLine = memberType + (sinceYear ? (' &middot; Member since ' + sinceYear) : '');
                var el = document.createElement('div');
                el.style.cssText = "position:fixed;left:-10000px;top:0;z-index:-1;pointer-events:none;width:1600px;height:1000px;box-sizing:border-box;overflow:hidden;border-radius:40px;background:radial-gradient(135% 120% at 16% 6%,#16223f,#0f1830 46%,#0a0f1e 100%);font-family:'Inter',-apple-system,sans-serif;color:#ffffff;";
                el.innerHTML =
                    '<div style="position:absolute;top:0;left:0;right:0;height:12px;background:linear-gradient(90deg,#7d161c,#9b1b22,#c2484e,#9b1b22,#7d161c);"></div>'
                  + '<div style="position:absolute;inset:0;mix-blend-mode:screen;opacity:.85;background:radial-gradient(560px 560px at 30% 16%,rgba(230,201,135,.35),rgba(230,201,135,.08) 45%,transparent 63%),linear-gradient(115deg,transparent 34%,rgba(255,247,220,.08) 48%,rgba(230,201,135,.16) 50%,rgba(255,247,220,.08) 52%,transparent 66%);"></div>'
                  + '<div style="position:absolute;inset:34px;border:1.5px solid rgba(201,169,98,.32);border-radius:26px;pointer-events:none;"></div>'
                  + '<img src="/assets/images/medx-logo.png" crossorigin="anonymous" style="position:absolute;right:-90px;bottom:-120px;width:720px;opacity:.06;transform:rotate(-8deg);">'
                  + '<div style="position:relative;display:flex;height:100%;box-sizing:border-box;z-index:2;">'
                    + '<div style="flex:1;padding:96px 80px;box-sizing:border-box;display:flex;flex-direction:column;">'
                      + '<div style="display:inline-flex;align-items:center;background:#fbf9f6;border-radius:16px;padding:16px 22px;align-self:flex-start;box-shadow:0 12px 30px rgba(0,0,0,.35);"><img src="/assets/images/medx-logo.png" crossorigin="anonymous" style="height:52px;width:auto;display:block;"></div>'
                      + '<div style="flex:1;"></div>'
                      + '<div style="font-size:20px;letter-spacing:6px;text-transform:uppercase;color:#e6c987;font-weight:700;margin-bottom:16px;">Member</div>'
                      + '<div style="font-family:\'Fraunces\',Georgia,serif;font-size:80px;font-weight:600;line-height:1.0;color:#ffffff;letter-spacing:-1px;">' + escapeHtml(name) + '</div>'
                      + '<div style="font-size:28px;color:rgba(255,255,255,.66);margin-top:18px;">' + sinceLine + '</div>'
                      + '<div style="margin-top:28px;display:inline-flex;align-items:center;gap:12px;align-self:flex-start;background:rgba(201,169,98,.12);border:1px solid rgba(201,169,98,.42);border-radius:999px;padding:13px 24px;">'
                        + '<span style="display:inline-flex;width:26px;height:26px;border-radius:50%;background:#e6c987;color:#0f1830;align-items:center;justify-content:center;font-size:16px;font-weight:700;">&#10003;</span>'
                        + '<span style="font-size:22px;font-weight:600;color:#f2e3c0;">' + escapeHtml(standing) + '</span>'
                      + '</div>'
                      + '<div style="margin-top:44px;font-size:19px;color:rgba(230,201,135,.7);letter-spacing:1px;">medx.hr &middot; Member ID ' + escapeHtml(memberId || '') + '</div>'
                    + '</div>'
                    + '<div style="width:540px;display:flex;align-items:center;justify-content:center;padding:80px 80px 80px 0;box-sizing:border-box;">'
                      + '<div style="background:#ffffff;border-radius:32px;padding:50px;display:flex;flex-direction:column;align-items:center;box-shadow:0 18px 48px rgba(0,0,0,.4);">'
                        + (qrUrl ? '<img src="' + qrUrl + '" style="width:380px;height:380px;display:block;">' : '<div style="width:380px;height:380px;display:flex;align-items:center;justify-content:center;color:#6b6258;font-size:18px;">QR unavailable</div>')
                        + '<div style="font-size:21px;letter-spacing:3px;text-transform:uppercase;color:#15110f;font-weight:700;margin-top:28px;">Scan to verify</div>'
                        + '<div style="font-size:18px;color:#6b6258;margin-top:8px;">Med&amp;X Membership</div>'
                        + '<div style="font-size:16px;color:#a38a4f;margin-top:16px;max-width:300px;text-align:center;line-height:1.45;">This QR carries your key info for check-in at Med&amp;X events.</div>'
                      + '</div>'
                    + '</div>'
                  + '</div>';
                return el;
            },

            async _ticketCanvas(r) {
                var qrData = r.ticket_qr_code || ('MEDX:' + (r.id || '')); // EXACT same value the live wallet card encodes
                var qrUrl = await this._qrDataUrl(qrData, 380, '#15110f');
                var node = this._composeTicket(r, qrUrl);
                return await this._rasterize(node, 1080, 1920);
            },

            async downloadTicket(idx) {
                var r = (this._regs || [])[idx];
                if (!r) return;
                try {
                    if (typeof Toast !== 'undefined' && Toast.info) Toast.info(t('toast.preparingTicket'));
                    var canvas = await this._ticketCanvas(r);
                    var self = this;
                    canvas.toBlob(function(blob){
                        if (!blob) { if (typeof Toast !== 'undefined' && Toast.error) Toast.error(t('toast.ticketGenFail')); return; }
                        var fname = ((r.conference_name || 'plexus') + '').replace(/[^a-z0-9]+/gi, '-').toLowerCase().replace(/^-+|-+$/g, '') + '-ticket.png';
                        self._saveBlob(blob, fname);
                        if (typeof Toast !== 'undefined' && Toast.success) Toast.success(t('tk.downloaded'));
                    }, 'image/png');
                } catch (e) {
                    console.error('Ticket download failed:', e);
                    if (typeof Toast !== 'undefined' && Toast.error) Toast.error(t('toast.ticketGenFail'));
                }
            },

            async saveTicketPdf(idx) {
                var r = (this._regs || [])[idx];
                if (!r) return;
                try {
                    if (typeof Toast !== 'undefined' && Toast.info) Toast.info(t('toast.preparingPrintTicket'));
                    var canvas = await this._ticketCanvas(r);
                    var dataUrl = canvas.toDataURL('image/png');
                    this._openPrintImage(dataUrl, escapeHtml(this._guestName(r)) + ' — Plexus 2026 Ticket', 'portrait');
                } catch (e) {
                    console.error('Ticket PDF failed:', e);
                    if (typeof Toast !== 'undefined' && Toast.error) Toast.error(t('toast.printTicketFail'));
                }
            },

            _openPrintImage(dataUrl, title, orientation) {
                var w = window.open('', '_blank');
                if (!w) { if (typeof Toast !== 'undefined' && Toast.warning) Toast.warning(t('toast.allowPopupsPdf')); return; }
                var size = orientation === 'landscape' ? 'A4 landscape' : 'A4 portrait';
                w.document.write('<!DOCTYPE html><html><head><meta charset="utf-8"><title>' + title + '</title>'
                    + '<style>@page{size:' + size + ';margin:0;}html,body{margin:0;padding:0;background:#0e0a08;}'
                    + '.wrap{min-height:100vh;display:flex;align-items:center;justify-content:center;}'
                    + 'img{max-width:100%;max-height:100vh;display:block;}'
                    + '.bar{position:fixed;top:0;left:0;right:0;padding:12px;text-align:center;background:#15110f;color:#fff;font-family:Arial,sans-serif;font-size:13px;z-index:2;}'
                    + '.bar button{margin-left:10px;padding:8px 16px;border:none;border-radius:8px;background:#c9a962;color:#15110f;font-weight:700;cursor:pointer;}'
                    + '@media print{.bar{display:none;}}</style></head><body>'
                    + '<div class="bar">Open your browser Print dialog and choose Save as PDF.<button onclick="window.print()">Print / Save as PDF</button></div>'
                    + '<div class="wrap"><img src="' + dataUrl + '"></div>'
                    + '<scr' + 'ipt>window.onload=function(){setTimeout(function(){try{window.print();}catch(e){}},400);};</scr' + 'ipt>'
                    + '</body></html>');
                w.document.close();
            },

            async downloadMembershipCard() {
                try {
                    await this._ensureLibs();
                    var user = this._currentUser();
                    var name = (user.name || ((user.first_name || '') + ' ' + (user.last_name || '')).trim()) || 'Med&X Member';
                    var regId = (function(){ try { return localStorage.getItem('plexus_registration_id') || 'MX-2026'; } catch (e) { return 'MX-2026'; } })();
                    // Canonical profile-synced membership QR — same shape the scanner reads (top-level userId).
                    var qrPayload = JSON.stringify({ type: 'PLEXUS2026', userId: user.id || '', regId: regId, name: name });
                    if (typeof Toast !== 'undefined' && Toast.info) Toast.info(t('tk.preparingCard'));
                    var meta = null;
                    try { if (typeof MemberState !== 'undefined') meta = await MemberState.loadMeta(); } catch (e) {}
                    var qrUrl = await this._qrDataUrl(qrPayload, 380, '#15110f');
                    var memberId = (user.id ? String(user.id).slice(0, 8).toUpperCase() : '');
                    var node = this._composeMembership(name, meta, qrUrl, memberId);
                    var canvas = await this._rasterize(node, 1600, 1000);
                    var self = this;
                    canvas.toBlob(function(blob){
                        if (!blob) { if (typeof Toast !== 'undefined' && Toast.error) Toast.error(t('toast.cardGenFail')); return; }
                        self._saveBlob(blob, 'medx-membership-card.png');
                        if (typeof Toast !== 'undefined' && Toast.success) Toast.success(t('toast.cardDownloaded'));
                    }, 'image/png');
                } catch (e) {
                    console.error('Membership card failed:', e);
                    var _m = (e && /load|offline|network|connection/i.test(e.message || '')) ? e.message : t('toast.cardGenFailRetry');
                    if (typeof Toast !== 'undefined' && Toast.error) Toast.error(_m);
                }
            },

            // Make the client-side card/ticket renderers resilient. The QR + html2canvas libs load via
            // <script defer> from a CDN, so a fast click (or a slow/blocked CDN) can reach the download
            // before they exist. Wait briefly, then re-inject from the CDN, and only fail with a clear
            // message so the card download never silently dead-ends.
            _ensureLibs() {
                var ready = function(){ return typeof html2canvas !== 'undefined' && typeof QRCode !== 'undefined' && QRCode.toDataURL; };
                if (ready()) return Promise.resolve();
                var inject = function(src){ return new Promise(function(res){ var t = document.createElement('script'); t.src = src; t.async = true; t.onload = function(){ res(true); }; t.onerror = function(){ res(false); }; document.head.appendChild(t); }); };
                return new Promise(function(resolve, reject){
                    var waited = 0;
                    (function poll(){
                        if (ready()) return resolve();
                        waited += 120;
                        if (waited < 2600) return setTimeout(poll, 120);
                        var jobs = [];
                        if (typeof QRCode === 'undefined') jobs.push(inject('https://cdn.jsdelivr.net/npm/qrcode@1.5.1/build/qrcode.min.js'));
                        if (typeof html2canvas === 'undefined') jobs.push(inject('https://cdn.jsdelivr.net/npm/html2canvas@1.4.1/dist/html2canvas.min.js'));
                        Promise.all(jobs).then(function(){
                            var extra = 0;
                            (function poll2(){
                                if (ready()) return resolve();
                                extra += 150;
                                if (extra < 2500) return setTimeout(poll2, 150);
                                reject(new Error("We couldn't load the card designer (you may be offline). Please check your connection and try again."));
                            })();
                        });
                    })();
                });
            },

            // ===== Living membership card (queue 5a5l) =====
            // The on-screen keepsake: pointer-tracked gold foil + subtle tilt on a navy/gold brand
            // face, flipping to a passport of real gold seals. The card face itself renders for every
            // member; the flip + passport are playful, so they are FAIL-CLOSED hidden for quiet
            // (gala/forum-only) profiles. The QR carries the SAME frozen membership payload as before.
            _APPLE_WALLET_ENABLED: false, // Apple Wallet needs Apple Developer certs (owner action)

            renderMembershipCardVisual() {
                var el = document.getElementById('mymedxCardVisual');
                if (!el) return;
                var user = this._currentUser();
                var name = (user.name || ((user.first_name || '') + ' ' + (user.last_name || '')).trim()) || 'Med&X Member';
                var memberId = user.id ? String(user.id).slice(0, 8).toUpperCase() : '';
                var self = this;
                var playful = (typeof MedXQuiet === 'undefined') ? true : MedXQuiet.allowPlayful();
                var reduced = !!(window.matchMedia && window.matchMedia('(prefers-reduced-motion:reduce)').matches);
                el.classList.toggle('mlc-reduced', reduced);
                el.innerHTML = self._livingCardHtml(name, null, memberId, playful);
                self._paintCardQr(user, name);
                self._applyPortraits();
                self._wireLivingCard(playful, reduced);
                if (playful) self.loadPassport();
                if (typeof MemberState !== 'undefined') {
                    MemberState.loadMeta().then(function(m){
                        el.innerHTML = self._livingCardHtml(name, m, memberId, playful);
                        self._paintCardQr(user, name);
                        self._applyPortraits();
                        self._wireLivingCard(playful, reduced);
                        if (playful) self._paintPassport();
                    }).catch(function(){});
                }
            },

            _livingCardHtml(name, meta, memberId, playful) {
                var memberType = (typeof MemberState !== 'undefined' ? MemberState.localType(meta) : '') || t('mmx.cardMemberFallback');
                var sinceY = (meta && meta.member_since) ? String(meta.member_since).slice(0, 4) : '';
                var standing = (typeof MemberState !== 'undefined' ? MemberState.localStanding(meta) : '') || t('mmx.cardStanding');
                var sinceLine = memberType + (sinceY ? (' · ' + t('mmx.memberSince', { y: sinceY })) : '');
                var check = '<span class="dot"><svg viewBox="0 0 12 12" fill="none"><path d="M2.6 6.2l2.1 2.1 4.7-4.7" stroke="#0f1830" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg></span>';
                var flipFront = playful
                    ? '<button type="button" class="mlc-flip" aria-label="' + escapeHtml(t('mmx.lcFlipToPassport')) + '"><i class="fas fa-passport"></i>' + escapeHtml(t('mmx.lcPassport')) + '</button>'
                    : '';
                var front = '<div class="mlc-face front">'
                    + '<div class="mlc-foil" aria-hidden="true"></div>'
                    + flipFront
                    + '<div class="mlc-inner">'
                        + '<div class="mlc-top">'
                            + '<span class="mlc-logochip"><img src="/assets/images/medx-logo.png" alt="Med&X" crossorigin="anonymous"></span>'
                            + '<span class="mlc-eyebrow">' + escapeHtml(t('mmx.lcMemberCard')) + '</span>'
                        + '</div>'
                        + '<div class="mlc-mid">'
                            + '<div class="mlc-portrait" id="mymedxCardPortrait">' + this._portraitInnerHtml(name) + '</div>'
                            + '<div class="mlc-idblock"><div class="mlc-label">' + escapeHtml(t('mmx.cardMember')) + '</div><div class="mlc-name">' + escapeHtml(name) + '</div></div>'
                        + '</div>'
                        + '<div class="mlc-bot">'
                            + '<div class="mlc-meta">'
                                + (sinceLine ? '<div class="mlc-since">' + escapeHtml(sinceLine) + '</div>' : '')
                                + '<div class="mlc-standing">' + check + escapeHtml(standing) + '</div>'
                            + '</div>'
                            + '<div id="mymedxCardQr" class="mlc-qr"><i class="fas fa-qrcode"></i></div>'
                        + '</div>'
                    + '</div>'
                + '</div>';
                var back = '';
                if (playful) {
                    back = '<div class="mlc-face back">'
                        + '<div class="mlc-foil" aria-hidden="true"></div>'
                        + '<button type="button" class="mlc-flip" aria-label="' + escapeHtml(t('mmx.lcFlipToCard')) + '"><i class="fas fa-id-card"></i>' + escapeHtml(t('mmx.lcCardSide')) + '</button>'
                        + '<div class="mlc-inner">'
                            + '<div class="mlc-back-head"><div class="mlc-back-title">' + t('mmx.lcPassportTitle') + '</div><div class="mlc-back-sub">' + escapeHtml(t('mmx.lcPassportSub')) + '</div></div>'
                            + '<div class="mlc-stamps" id="mymedxPassportStamps"></div>'
                            + '<div class="mlc-foot"><div class="cnt"><b id="mymedxStampCount">0</b> <span id="mymedxStampCountLabel"></span></div><div class="num">medx.hr</div></div>'
                        + '</div>'
                    + '</div>';
                }
                return '<div class="mlc" role="button" tabindex="0" aria-label="' + escapeHtml(t('mmx.lcCardAria')) + '">' + front + back + '</div>';
            },

            // Pointer-tracked foil + subtle tilt (desktop pointer; on touch the sheen follows the
            // finger and a tap flips — no gyroscope permission is requested, so mobile degrades
            // gracefully). Fresh listeners each render because innerHTML is replaced.
            _wireLivingCard(playful, reduced) {
                var scene = document.getElementById('mymedxCardVisual');
                if (!scene) return;
                var card = scene.querySelector('.mlc');
                if (!card) return;
                var self = this;
                var foils = card.querySelectorAll('.mlc-foil');
                var flipped = false, rX = 0, rY = 0, tX = 0, tY = 0, raf = null;
                function apply() { var base = flipped ? 180 : 0; card.style.transform = 'rotateX(' + rY.toFixed(2) + 'deg) rotateY(' + (base + rX).toFixed(2) + 'deg)'; raf = null; }
                function queue() { if (!raf) raf = requestAnimationFrame(apply); }
                function ease() { rX += (tX - rX) * 0.12; rY += (tY - rY) * 0.12; queue(); if (Math.abs(tX - rX) > 0.05 || Math.abs(tY - rY) > 0.05) requestAnimationFrame(ease); }
                if (!reduced) {
                    card.addEventListener('pointermove', function(e){
                        var r = card.getBoundingClientRect(); if (!r.width) return;
                        var cx = (e.clientX - r.left) / r.width, cy = (e.clientY - r.top) / r.height;
                        tX = (cx - 0.5) * 14; tY = -(cy - 0.5) * 10;
                        foils.forEach(function(f){ f.style.setProperty('--mx', (cx * 100).toFixed(1) + '%'); f.style.setProperty('--my', (cy * 100).toFixed(1) + '%'); });
                        ease();
                    });
                    card.addEventListener('pointerleave', function(){ tX = 0; tY = 0; foils.forEach(function(f){ f.style.setProperty('--mx', '62%'); f.style.setProperty('--my', '24%'); }); ease(); });
                }
                function flip() {
                    if (!playful) return;
                    flipped = !flipped;
                    card.classList.toggle('flipped', flipped);
                    apply();
                    if (flipped) self.loadPassport();
                }
                if (playful) {
                    card.addEventListener('click', function(e){ if (e.target.closest('button,a')) return; flip(); });
                    card.addEventListener('keydown', function(e){ if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); flip(); } });
                    scene.querySelectorAll('.mlc-flip').forEach(function(b){ b.addEventListener('click', function(e){ e.stopPropagation(); flip(); }); });
                }
            },

            // Passport stamps from REAL data (event registrations + check-ins + Building Bridges city
            // participation) via GET /api/member/passport. The server fail-closes for quiet profiles
            // (returns no stamps), and the client only ever renders the passport for playful members.
            loadPassport(force) {
                var self = this;
                if (!force && this._passportStamps !== undefined) { this._paintPassport(); return; }
                var tkn = (typeof UserPortal !== 'undefined' && UserPortal.token) || localStorage.getItem('medx_user_token');
                var base = (typeof API_BASE !== 'undefined' ? API_BASE : '');
                fetch(base + '/api/member/passport', { headers: tkn ? { 'Authorization': 'Bearer ' + tkn } : {} })
                    .then(function(r){ return r.ok ? r.json() : null; })
                    .then(function(d){ self._passportStamps = (d && !d.quiet && Array.isArray(d.stamps)) ? d.stamps : []; self._paintPassport(); })
                    .catch(function(){ if (self._passportStamps === undefined) self._passportStamps = []; self._paintPassport(); });
            },

            _paintPassport() {
                var grid = document.getElementById('mymedxPassportStamps');
                if (!grid) return;
                var stamps = this._passportStamps || [];
                var n = stamps.length;
                var slots = Math.max(8, Math.ceil(n / 4) * 4);
                var html = '';
                for (var i = 0; i < slots; i++) {
                    if (i < n) {
                        var s = stamps[i];
                        var title = (s.name || '') + (s.year ? (' · ' + s.year) : '') + (s.attended ? (' · ' + t('mmx.stAttended')) : '');
                        html += '<div class="mlc-stamp filled" title="' + escapeHtml(title) + '">' + this._stampSvg(s, i) + '</div>';
                    } else {
                        html += '<div class="mlc-stamp"><svg viewBox="0 0 100 100"><circle cx="50" cy="50" r="38" fill="none" stroke="rgba(255,255,255,.14)" stroke-dasharray="3 4"/><path d="M50 40v20M40 50h20" stroke="rgba(255,255,255,.22)" stroke-width="1" stroke-linecap="round"/></svg></div>';
                    }
                }
                grid.innerHTML = html;
                var cnt = document.getElementById('mymedxStampCount'); if (cnt) cnt.textContent = n;
                var lbl = document.getElementById('mymedxStampCountLabel');
                if (lbl) lbl.textContent = this._plural(n, 'seal collected', 'seals collected', 'pečat skupljen', 'pečata skupljena', 'pečata skupljeno');
            },

            _stampSvg(s, uid) {
                var label = String(s.label || 'MEDX');
                var yr = String(s.year || '');
                var arc = String(s.city || '').toUpperCase();
                var ringO = s.attended ? 'rgba(230,201,135,.95)' : 'rgba(201,169,98,.85)';
                return '<svg viewBox="0 0 100 100">'
                    + '<defs><path id="mlcArcT' + uid + '" d="M20 50a30 30 0 0 1 60 0" fill="none"/><path id="mlcArcB' + uid + '" d="M22 58a28 28 0 0 0 56 0" fill="none"/></defs>'
                    + '<circle cx="50" cy="50" r="38" fill="none" stroke="' + ringO + '" stroke-width="1.5"/>'
                    + '<circle cx="50" cy="50" r="32" fill="none" stroke="rgba(201,169,98,.5)" stroke-width=".8"/>'
                    + (s.attended ? '<circle cx="50" cy="50" r="35" fill="none" stroke="rgba(230,201,135,.35)" stroke-width=".6" stroke-dasharray="1.5 2.5"/>' : '')
                    + '<text font-family="Inter,sans-serif" font-weight="700" font-size="8" letter-spacing=".4" fill="#e6c987" text-anchor="middle"><textPath href="#mlcArcT' + uid + '" startOffset="50%">' + escapeHtml(label) + '</textPath></text>'
                    + '<text x="50" y="56" font-family="Fraunces,Georgia,serif" font-size="17" fill="#fff" text-anchor="middle">' + escapeHtml(yr) + '</text>'
                    + (arc ? '<text font-family="Inter,sans-serif" font-weight="600" font-size="6" letter-spacing="1" fill="rgba(230,201,135,.85)" text-anchor="middle"><textPath href="#mlcArcB' + uid + '" startOffset="50%">' + escapeHtml(arc) + '</textPath></text>' : '')
                    + '</svg>';
            },

            // Google Wallet — server builds a signed generic-pass "Save to Wallet" JWT link. In dev (no
            // issuer secrets) the route returns a clean unconfigured gate naming the owner action.
            addToGoogleWallet() {
                var self = this;
                var tkn = (typeof UserPortal !== 'undefined' && UserPortal.token) || localStorage.getItem('medx_user_token');
                var base = (typeof API_BASE !== 'undefined' ? API_BASE : '');
                if (typeof Toast !== 'undefined' && Toast.info) Toast.info(t('mmx.lcGooglePrep'));
                fetch(base + '/api/member/wallet/google', { headers: tkn ? { 'Authorization': 'Bearer ' + tkn } : {} })
                    .then(function(r){ return r.ok ? r.json() : Promise.reject('err'); })
                    .then(function(d){
                        if (d && d.configured && d.save_url) { window.open(d.save_url, '_blank', 'noopener'); }
                        else if (d && d.configured === false) {
                            var msg = (self._isHR() ? d.message_hr : d.message_en) || t('mmx.lcGoogleSoon');
                            if (typeof Toast !== 'undefined' && Toast.info) Toast.info(msg);
                        } else { if (typeof Toast !== 'undefined' && Toast.error) Toast.error(t('mmx.lcWalletErr')); }
                    })
                    .catch(function(){ if (typeof Toast !== 'undefined' && Toast.error) Toast.error(t('mmx.lcWalletErr')); });
            },

            // Apple Wallet — behind a default-off feature flag (a real .pkpass needs Apple Developer
            // certs, an owner action). Until then the button shows a clean "coming soon" state.
            addToAppleWallet() {
                if (this._APPLE_WALLET_ENABLED) return;
                if (typeof Toast !== 'undefined' && Toast.info) Toast.info(t('mmx.lcAppleSoon'));
            },

            // ===== R3-3 EVENT-DAY TICKET SUITE =====
            // On-device ticket cache: a slim copy of the member's own registrations, written ONLY
            // after a fresh authenticated /api/registrations/my fetch, read ONLY when that fetch
            // fails (offline). Same device-trust level as medx_user_data. The service worker never
            // caches /api/ responses — this is deliberate app state, not a transparent cache.
            _TICKET_CACHE_KEY: 'medx_ticket_cache',
            _saveTicketCache(regs) {
                try {
                    var slim = (regs || []).map(function(r){
                        return {
                            id: r.id, conference_name: r.conference_name, ticket_name: r.ticket_name,
                            registration_type: r.registration_type, first_name: r.first_name, last_name: r.last_name,
                            ticket_qr_code: r.ticket_qr_code, start_date: r.start_date, end_date: r.end_date,
                            venue_name: r.venue_name, venue_city: r.venue_city, payment_status: r.payment_status,
                            amount_paid: r.amount_paid, invoice_number: r.invoice_number, checked_in: r.checked_in,
                            seat_number: r.seat_number
                        };
                    });
                    localStorage.setItem(this._TICKET_CACHE_KEY, JSON.stringify(slim));
                } catch (e) { /* storage full/blocked — the online path is unaffected */ }
            },
            _cachedRegs() {
                try {
                    var raw = localStorage.getItem(this._TICKET_CACHE_KEY);
                    var arr = raw ? JSON.parse(raw) : null;
                    return Array.isArray(arr) ? arr : null;
                } catch (e) { return null; }
            },

            // Present mode — a full-screen boarding pass for the venue door: guest name, event,
            // seat/type, and the EXISTING frozen QR payload re-rendered large (>=148px). The QR
            // value is byte-identical to the wallet card + scanner value; only the pixel size of
            // the rendered image differs (exactly like the existing PNG ticket download).
            _presentWakeLock: null,
            _presentEscHandler: null,
            openPresentMode(idx) {
                var regs = (this._regs && this._regs.length) ? this._regs : (this._cachedRegs() || []);
                var r = regs[idx || 0];
                if (!r) { if (typeof Toast !== 'undefined' && Toast.info) Toast.info(t('tk.noTicketToPresent')); return; }
                this.closePresentMode();
                var name = this._guestName(r);
                var qrData = r.ticket_qr_code || ('MEDX:' + (r.id || '')); // EXACT same value the wallet card + scanner use
                var dates = this._fmtDateRange(r.start_date, r.end_date);
                var venue = [r.venue_name, r.venue_city].filter(Boolean).join(', ');
                var paid = (r.payment_status === 'paid');
                var free = (!r.amount_paid || Number(r.amount_paid) === 0);
                var statusLabel = paid ? t('tk.paid') : (free ? t('tk.confirmed') : t('tk.paymentPending'));
                var statusColor = (paid || free) ? '#2f6b3a' : '#9a6b1f';
                var ov = document.createElement('div');
                ov.id = 'mxPresentOverlay';
                ov.setAttribute('role', 'dialog');
                ov.setAttribute('aria-modal', 'true');
                ov.setAttribute('aria-label', t('tk.presentAria'));
                ov.style.cssText = 'position:fixed;inset:0;z-index:100000;display:flex;align-items:center;justify-content:center;padding:18px;box-sizing:border-box;background:linear-gradient(165deg,#1d1813,#14100d 55%,#0e0a08);overflow:auto;';
                ov.innerHTML =
                    '<button type="button" onclick="MyMedXPortal.closePresentMode()" aria-label="' + t('mmx.close') + '" style="position:fixed;top:16px;right:16px;z-index:2;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.28);color:#fff;border-radius:999px;width:42px;height:42px;font-size:17px;cursor:pointer;line-height:1;">&#10005;</button>'
                  + '<div style="width:min(92vw,400px);background:#fbf9f6;border-radius:22px;overflow:hidden;box-shadow:0 24px 70px rgba(0,0,0,.55);margin:auto;">'
                    + '<div style="height:8px;background:linear-gradient(90deg,#a38a4f,#c9a962,#e8d5a8,#c9a962,#a38a4f);"></div>'
                    + '<div style="padding:22px 24px 16px;background:linear-gradient(165deg,#1d1813,#14100d);color:#fff;">'
                      + '<div style="font-size:11px;letter-spacing:3px;text-transform:uppercase;color:#c9a962;font-weight:700;margin-bottom:7px;">Med&amp;X</div>'
                      + '<div style="font-family:var(--serif,\'Fraunces\',Georgia,serif);font-size:25px;font-weight:600;line-height:1.08;">' + escapeHtml(r.conference_name || t('tk.medxEvent')) + '</div>'
                      + (dates || venue
                          ? '<div style="font-size:12.5px;color:rgba(255,255,255,.72);margin-top:9px;line-height:1.5;">'
                            + (dates ? '<div><i class="fas fa-calendar" style="width:17px;color:#c9a962;"></i> ' + escapeHtml(dates) + '</div>' : '')
                            + (venue ? '<div><i class="fas fa-location-dot" style="width:17px;color:#c9a962;"></i> ' + escapeHtml(venue) + '</div>' : '')
                          + '</div>'
                          : '')
                    + '</div>'
                    + '<div style="padding:16px 24px 6px;display:flex;justify-content:space-between;align-items:center;gap:10px;">'
                      + '<div style="min-width:0;">'
                        + '<div style="font-size:10px;letter-spacing:2.5px;text-transform:uppercase;color:#a38a4f;font-weight:700;">' + t('tk.guest') + '</div>'
                        + '<div style="font-family:var(--serif,\'Fraunces\',Georgia,serif);font-size:21px;font-weight:600;color:#15110f;line-height:1.12;">' + escapeHtml(name) + '</div>'
                        + '<div style="font-size:12px;color:#6b6258;margin-top:3px;">' + escapeHtml(r.ticket_name || r.registration_type || t('tk.ticket')) + (r.seat_number ? ' &middot; ' + t('tk.seat') + ' ' + escapeHtml(String(r.seat_number)) : '') + '</div>'
                      + '</div>'
                      + '<span style="white-space:nowrap;flex:none;font-size:10px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;color:' + statusColor + ';border:1px solid currentColor;padding:5px 10px;border-radius:999px;">' + statusLabel + '</span>'
                    + '</div>'
                    + '<div style="position:relative;margin:12px 0 0;"><div style="border-top:2px dashed #d9d2c5;"></div>'
                      + '<div style="position:absolute;left:-13px;top:-13px;width:26px;height:26px;border-radius:50%;background:#14100d;"></div>'
                      + '<div style="position:absolute;right:-13px;top:-13px;width:26px;height:26px;border-radius:50%;background:#14100d;"></div>'
                    + '</div>'
                    + '<div style="padding:20px 24px 22px;display:flex;flex-direction:column;align-items:center;">'
                      + '<div style="background:#ffffff;border:1px solid #e6e0d4;border-radius:16px;padding:14px;">'
                        + '<div id="mxPresentQR" style="width:min(64vw,232px);height:min(64vw,232px);min-width:148px;min-height:148px;display:flex;align-items:center;justify-content:center;"></div>'
                      + '</div>'
                      + '<div style="font-size:12px;letter-spacing:.06em;text-transform:uppercase;color:#15110f;font-weight:700;margin-top:14px;">' + t('tk.presentHint') + '</div>'
                      + (r.invoice_number ? '<div style="font-size:12px;color:#6b6258;margin-top:5px;font-variant-numeric:tabular-nums;">#' + escapeHtml(r.invoice_number) + '</div>' : '')
                    + '</div>'
                  + '</div>';
                document.body.appendChild(ov);
                this._presentPrevOverflow = document.body.style.overflow;
                document.body.style.overflow = 'hidden';
                // The QR pixels: rendered from the SAME frozen payload, sized for across-the-desk scans.
                var host = document.getElementById('mxPresentQR');
                if (host && typeof QRCode !== 'undefined') {
                    QRCode.toCanvas(document.createElement('canvas'), qrData, { width: 464, margin: 1, errorCorrectionLevel: 'M', color: { dark: '#15110f', light: '#ffffff' } }, function(err, canvas){
                        if (err || !canvas) { host.textContent = 'QR unavailable'; host.style.fontSize = '12px'; host.style.color = '#6b6258'; return; }
                        canvas.style.width = '100%'; canvas.style.height = '100%'; host.appendChild(canvas);
                    });
                } else if (host) { host.textContent = 'QR unavailable'; host.style.fontSize = '12px'; host.style.color = '#6b6258'; }
                // Keep the screen awake at the door (best effort — not all browsers expose it).
                var self = this;
                try { if (navigator.wakeLock && navigator.wakeLock.request) navigator.wakeLock.request('screen').then(function(l){ self._presentWakeLock = l; }).catch(function(){}); } catch (e) {}
                this._presentEscHandler = function(ev){ if (ev.key === 'Escape') MyMedXPortal.closePresentMode(); };
                document.addEventListener('keydown', this._presentEscHandler);
            },
            closePresentMode() {
                var ov = document.getElementById('mxPresentOverlay');
                if (ov && ov.parentNode) ov.parentNode.removeChild(ov);
                if (this._presentEscHandler) { document.removeEventListener('keydown', this._presentEscHandler); this._presentEscHandler = null; }
                try { if (this._presentWakeLock) { this._presentWakeLock.release().catch(function(){}); this._presentWakeLock = null; } } catch (e) {}
                if (ov) document.body.style.overflow = this._presentPrevOverflow || '';
            },

            // Google Wallet for ONE event ticket — the server signs a generic-pass JWT whose barcode
            // carries the frozen ticket payload. Same clean key-gate as the membership pass in dev.
            addTicketToGoogleWallet(idx) {
                var r = (this._regs || [])[idx];
                if (!r || !r.id) { if (typeof Toast !== 'undefined' && Toast.info) Toast.info(t('tk.noTicketToPresent')); return; }
                var self = this;
                var tkn = (typeof UserPortal !== 'undefined' && UserPortal.token) || localStorage.getItem('medx_user_token');
                var base = (typeof API_BASE !== 'undefined' ? API_BASE : '');
                if (typeof Toast !== 'undefined' && Toast.info) Toast.info(t('mmx.lcGooglePrep'));
                fetch(base + '/api/member/wallet/google/ticket/' + encodeURIComponent(r.id), { headers: tkn ? { 'Authorization': 'Bearer ' + tkn } : {} })
                    .then(function(res){ return res.ok ? res.json() : Promise.reject('err'); })
                    .then(function(d){
                        if (d && d.configured && d.save_url) { window.open(d.save_url, '_blank', 'noopener'); }
                        else if (d && d.configured === false) {
                            var msg = (self._isHR() ? d.message_hr : d.message_en) || t('mmx.lcGoogleSoon');
                            if (typeof Toast !== 'undefined' && Toast.info) Toast.info(msg);
                        } else { if (typeof Toast !== 'undefined' && Toast.error) Toast.error(t('mmx.lcWalletErr')); }
                    })
                    .catch(function(){ if (typeof Toast !== 'undefined' && Toast.error) Toast.error(t('mmx.lcWalletErr')); });
            },

            // Apple Wallet ticket — WIRED BUT DORMANT (a signed .pkpass needs the $99/yr Apple
            // Developer cert, an owner action). Flag off: plain "coming soon". Flag on: calls the
            // server route, which stays gated until the certificate env vars exist.
            _APPLE_TICKET_WALLET_ENABLED: false,
            addTicketToAppleWallet(idx) {
                if (!this._APPLE_TICKET_WALLET_ENABLED) {
                    if (typeof Toast !== 'undefined' && Toast.info) Toast.info(t('mmx.lcAppleSoon'));
                    return;
                }
                var r = (this._regs || [])[idx];
                if (!r || !r.id) { if (typeof Toast !== 'undefined' && Toast.info) Toast.info(t('tk.noTicketToPresent')); return; }
                var self = this;
                var tkn = (typeof UserPortal !== 'undefined' && UserPortal.token) || localStorage.getItem('medx_user_token');
                var base = (typeof API_BASE !== 'undefined' ? API_BASE : '');
                fetch(base + '/api/member/wallet/apple/ticket/' + encodeURIComponent(r.id), { headers: tkn ? { 'Authorization': 'Bearer ' + tkn } : {} })
                    .then(function(res){ return res.ok ? res.json() : Promise.reject('err'); })
                    .then(function(d){
                        if (d && d.configured && d.pass_url) { window.open(d.pass_url, '_blank', 'noopener'); }
                        else {
                            var msg = (d && (self._isHR() ? d.message_hr : d.message_en)) || t('mmx.lcAppleSoon');
                            if (typeof Toast !== 'undefined' && Toast.info) Toast.info(msg);
                        }
                    })
                    .catch(function(){ if (typeof Toast !== 'undefined' && Toast.error) Toast.error(t('mmx.lcWalletErr')); });
            },

            // ===== Member photo (users.photo_url) with an initials monogram fallback =====
            // The hero avatar and the membership card portrait always carry a personal mark:
            // the member's photo when one is on file, otherwise their initials. The photo is
            // preloaded before it is shown so a dead URL can never render as a broken image.
            _initialsFor(name) {
                var parts = String(name || '').trim().split(/\s+/).filter(Boolean);
                if (!parts.length) return 'MX';
                var ini = parts[0].charAt(0) + (parts.length > 1 ? parts[parts.length - 1].charAt(0) : '');
                return ini.toUpperCase();
            },

            _portraitInnerHtml(nameOverride) {
                var user = this._currentUser();
                var name = nameOverride || (user.name || ((user.first_name || '') + ' ' + (user.last_name || '')).trim()) || 'Med&X Member';
                if (this._photoUrl) return '<img src="' + escapeHtml(this._photoUrl) + '" alt="' + escapeHtml(name) + '">';
                return '<span>' + escapeHtml(this._initialsFor(name)) + '</span>';
            },

            _applyPortraits() {
                var hero = document.getElementById('mymedxHeroAvatar');
                if (hero) hero.innerHTML = this._portraitInnerHtml();
                var card = document.getElementById('mymedxCardPortrait');
                if (card) card.innerHTML = this._portraitInnerHtml();
            },

            loadPhoto() {
                var self = this;
                this._applyPortraits();
                var t = (typeof UserPortal !== 'undefined' && UserPortal.token) || localStorage.getItem('medx_user_token');
                var base = (typeof API_BASE !== 'undefined' ? API_BASE : '');
                fetch(base + '/api/auth/me', { headers: t ? { 'Authorization': 'Bearer ' + t } : {} })
                    .then(function(r){ return r.ok ? r.json() : null; })
                    .then(function(d){
                        if (!d || !d.photo_url) return;
                        var img = new Image();
                        img.onload = function(){ self._photoUrl = d.photo_url; self._applyPortraits(); };
                        img.src = d.photo_url;
                    })
                    .catch(function(){});
            },

            _paintCardQr(user, name) {
                var el = document.getElementById('mymedxCardQr');
                if (!el) return;
                var regId = (function(){ try { return localStorage.getItem('plexus_registration_id') || 'MX-2026'; } catch (e) { return 'MX-2026'; } })();
                var payload = JSON.stringify({ type: 'PLEXUS2026', userId: (user && user.id) || '', regId: regId, name: name });
                if (typeof QRCode !== 'undefined' && QRCode.toCanvas) {
                    QRCode.toCanvas(document.createElement('canvas'), payload, { width: 100, margin: 1, color: { dark: '#15110f', light: '#ffffff' } }, function(err, canvas){
                        if (err || !canvas) return;
                        canvas.style.width = '100px'; canvas.style.height = '100px';
                        el.innerHTML = ''; el.appendChild(canvas);
                    });
                }
            },

            // Rewards points panel — pull the live balance/lifetime so MyMedX shows real numbers even
            // if the Rewards section has not been opened yet this session.
            loadPoints() {
                var apply = function(bal, life){
                    var _loc = (window.MedXI18n && MedXI18n.dateLocale) ? MedXI18n.dateLocale() : 'en-US';
                    var b = document.getElementById('mymedxRewardsBalance'); if (b) b.textContent = (bal || 0).toLocaleString(_loc);
                    var l = document.getElementById('mymedxPointsLifetime'); if (l) l.textContent = (life || 0).toLocaleString(_loc);
                };
                if (typeof RewardsPortal !== 'undefined' && RewardsPortal.data) apply(RewardsPortal.data.balance, RewardsPortal.data.lifetime_points);
                var t = (typeof UserPortal !== 'undefined' && UserPortal.token) || localStorage.getItem('medx_user_token');
                var base = (typeof API_BASE !== 'undefined' ? API_BASE : '');
                fetch(base + '/api/rewards/summary', { headers: t ? { 'Authorization': 'Bearer ' + t } : {} })
                    .then(function(r){ return r.ok ? r.json() : null; })
                    .then(function(d){ if (d) apply(d.balance, d.lifetime_points); })
                    .catch(function(){});
            },

            // Past purchases — read-only list of the member's registrations/tickets, each with a warm
            // "ask about this" + "request a refund" action that FILES a support inquiry through the
            // existing messages inbox (POST /api/purchases/inquiry). No Stripe refund is ever called.
            renderPurchases(regs) {
                var el = document.getElementById('mymedxPurchases');
                if (!el) return;
                if (regs === null) {
                    el.innerHTML = MedXState.render({ tone: 'error', icon: 'fa-cloud-arrow-down', body: t('mmx.purchasesErr'), actionLabel: t('state.retry'), actionOnclick: 'MyMedXPortal.renderQRCodes()' });
                    return;
                }
                regs = regs || [];
                if (!regs.length) {
                    el.innerHTML = '<div class="mmx-purchase-empty">' + t('mmx.purchasesEmpty') + ' <a href="#" onclick="event.preventDefault();UserPortal.showSection(\'plexus\');" style="color:var(--crimson);font-weight:600;">' + t('tk.browseEvents') + '</a></div>';
                    return;
                }
                el.innerHTML = regs.map(function(r, i){
                    var paid = (r.payment_status === 'paid');
                    var free = (!r.amount_paid || Number(r.amount_paid) === 0);
                    var statusLabel = paid ? t('tk.paid') : (free ? t('tk.confirmed') : t('tk.paymentPending'));
                    var statusColor = (paid || free) ? 'var(--success)' : 'var(--warning)';
                    var amount = (r.amount_paid != null && Number(r.amount_paid) > 0) ? ('€' + Number(r.amount_paid).toFixed(2)) : (free ? t('tk.free') : '');
                    var dates = MyMedXPortal._fmtDateRange(r.start_date, r.end_date);
                    var when = r.created_at ? new Date(String(r.created_at).replace(' ', 'T')).toLocaleDateString('en-US', { day: 'numeric', month: 'short', year: 'numeric' }) : '';
                    var metaBits = [];
                    if (amount) metaBits.push('<strong>' + amount + '</strong>');
                    if (r.invoice_number) metaBits.push(t('mmx.invoiceNo') + escapeHtml(String(r.invoice_number)));
                    if (when && when !== 'Invalid Date') metaBits.push(when);
                    return '<div class="mmx-purchase">'
                        + '<div class="mmx-purchase-main">'
                            + '<div class="mmx-purchase-title">' + escapeHtml(r.conference_name || t('tk.medxEvent')) + '</div>'
                            + '<div class="mmx-purchase-sub">' + escapeHtml(r.ticket_name || r.registration_type || t('tk.ticket')) + (dates ? (' · ' + dates) : '') + '</div>'
                            + (metaBits.length ? '<div class="mmx-purchase-meta">' + metaBits.join(' · ') + '</div>' : '')
                        + '</div>'
                        + '<div class="mmx-purchase-side">'
                            + '<span class="mmx-purchase-status" style="color:' + statusColor + ';">' + statusLabel + '</span>'
                            + '<div class="mmx-purchase-actions">'
                                + '<button class="mmx-purchase-btn" onclick="MyMedXPortal.openPurchaseInquiry(' + i + ',\'question\')"><i class="fas fa-comment-dots"></i> ' + t('mmx.askAbout') + '</button>'
                                + '<button class="mmx-purchase-btn refund" onclick="MyMedXPortal.openPurchaseInquiry(' + i + ',\'refund\')"><i class="fas fa-hand-holding-heart"></i> ' + t('mmx.requestRefund') + '</button>'
                            + '</div>'
                        + '</div>'
                    + '</div>';
                }).join('');
            },

            openPurchaseInquiry(idx, kind) {
                var r = (this._regs || [])[idx];
                if (!r) return;
                var isRefund = (kind === 'refund');
                var evt = (r.conference_name || t('tk.medxEvent')) + (r.ticket_name ? (' — ' + r.ticket_name) : '');
                var self = this;
                var ov = document.getElementById('mmxInquiryOverlay');
                if (!ov) {
                    ov = document.createElement('div');
                    ov.id = 'mmxInquiryOverlay';
                    ov.className = 'mmx-inq-overlay';
                    document.body.appendChild(ov);
                    ov.addEventListener('click', function(e){ if (e.target === ov) self.closePurchaseInquiry(); });
                }
                ov.innerHTML = '<div class="mmx-inq-card">'
                    + '<button class="mmx-inq-x" onclick="MyMedXPortal.closePurchaseInquiry()" aria-label="Close">&times;</button>'
                    + '<div class="mmx-inq-eyebrow">' + (isRefund ? t('mmx.inqRefundEyebrow') : t('mmx.inqAskEyebrow')) + '</div>'
                    + '<div class="mmx-inq-title">' + escapeHtml(evt) + '</div>'
                    + '<p class="mmx-inq-lede">' + (isRefund
                        ? t('mmx.inqRefundLede')
                        : t('mmx.inqAskLede')) + '</p>'
                    + '<textarea id="mmxInquiryText" class="mmx-inq-text" rows="4" placeholder="' + (isRefund ? t('mmx.inqRefundPh') : t('mmx.inqAskPh')) + '"></textarea>'
                    + '<div class="mmx-inq-actions">'
                        + '<button class="mmx-inq-cancel" onclick="MyMedXPortal.closePurchaseInquiry()">' + t('mmx.inqCancel') + '</button>'
                        + '<button class="mmx-inq-send" id="mmxInquirySend" onclick="MyMedXPortal.submitPurchaseInquiry(' + idx + ',\'' + kind + '\')">' + t('mmx.inqSend') + '</button>'
                    + '</div>'
                    + '<div class="mmx-inq-foot"><i class="fas fa-shield-heart"></i><span>' + t('mmx.inqFoot') + '</span></div>'
                + '</div>';
                ov.classList.add('open');
                setTimeout(function(){ var t = document.getElementById('mmxInquiryText'); if (t) t.focus(); }, 60);
            },

            closePurchaseInquiry() {
                var ov = document.getElementById('mmxInquiryOverlay');
                if (ov) ov.classList.remove('open');
            },

            async submitPurchaseInquiry(idx, kind) {
                var r = (this._regs || [])[idx];
                if (!r) return;
                var txt = document.getElementById('mmxInquiryText');
                var msg = txt ? txt.value.trim() : '';
                if (kind === 'refund' && !msg) {
                    if (typeof Toast !== 'undefined' && Toast.warning) Toast.warning(t('mmx.tAddNote'));
                    return;
                }
                var btn = document.getElementById('mmxInquirySend');
                if (btn) { btn.disabled = true; btn.textContent = t('mmx.inqSending'); }
                try {
                    var tkn = (typeof UserPortal !== 'undefined' && UserPortal.token) || localStorage.getItem('medx_user_token');
                    var base = (typeof API_BASE !== 'undefined' ? API_BASE : '');
                    var headers = { 'Content-Type': 'application/json' };
                    if (tkn) headers['Authorization'] = 'Bearer ' + tkn;
                    var res = await fetch(base + '/api/purchases/inquiry', {
                        method: 'POST', headers: headers,
                        body: JSON.stringify({ registration_id: r.id, kind: kind, message: msg })
                    });
                    var data = await res.json().catch(function(){ return {}; });
                    if (res.ok && data.success) {
                        this.closePurchaseInquiry();
                        if (typeof Toast !== 'undefined' && Toast.success) Toast.success(kind === 'refund' ? t('mmx.tRefundSent') : t('mmx.tMsgSent'));
                    } else {
                        if (btn) { btn.disabled = false; btn.textContent = t('mmx.inqSend'); }
                        if (typeof Toast !== 'undefined' && Toast.error) Toast.error((data && data.error) || t('mmx.tSendFail'));
                    }
                } catch (e) {
                    if (btn) { btn.disabled = false; btn.textContent = t('mmx.inqSend'); }
                    if (typeof Toast !== 'undefined' && Toast.error) Toast.error(t('mmx.tSendFail'));
                }
            },

            renderInterests() {
                const container = document.getElementById('mymedxInterests');
                if (!container) return;

                const defaultInterests = ['Neuroscience', 'Sleep Medicine', 'Oncology', 'Public Health', 'Biotech', 'AI in Medicine', 'Mental Health', 'Genetics'];
                let interests = JSON.parse(localStorage.getItem('mymedx_interests') || 'null');
                if (!interests) {
                    interests = defaultInterests;
                    localStorage.setItem('mymedx_interests', JSON.stringify(interests));
                }

                container.innerHTML = interests.map(function(tag) {
                    return '<span style="display: inline-flex; align-items: center; gap: 6px; padding: 6px 10px 6px 14px; border-radius: 14px; font-size: 13px; font-weight: 500; background: var(--up-bg-subtle, #f5f5f7); color: var(--up-text-secondary, #6e6e73); border: 1px solid var(--up-border, #d2d2d7);">' +
                        tag +
                        '<button onclick="MyMedXPortal.removeInterest(\'' + tag.replace(/'/g, "\\'") + '\')" style="background: none; border: none; color: var(--up-text-muted, var(--muted)); cursor: pointer; font-size: 14px; line-height: 1; padding: 0 2px; font-weight: 700;" title="Remove">&times;</button>' +
                    '</span>';
                }).join('') +
                '<button onclick="MyMedXPortal.addInterest()" style="display: inline-flex; align-items: center; gap: 4px; padding: 6px 14px; border-radius: 14px; font-size: 13px; font-weight: 500; background: transparent; color: var(--up-text-muted, var(--muted)); border: 1px dashed var(--up-border, #d2d2d7); cursor: pointer;">+ ' + t('mmx.add') + '</button>';
            },

            removeInterest(tag) {
                let interests = JSON.parse(localStorage.getItem('mymedx_interests') || '[]');
                interests = interests.filter(function(t) { return t !== tag; });
                localStorage.setItem('mymedx_interests', JSON.stringify(interests));
                this.renderInterests();
            },

            async addInterest() {
                const tag = await mxPrompt({ title: t('mmx.addInterestTitle'), message: t('mmx.addInterestPrompt'), confirmText: t('dlg.confirm') });
                if (!tag || !tag.trim()) return;
                const trimmed = tag.trim();
                let interests = JSON.parse(localStorage.getItem('mymedx_interests') || '[]');
                if (interests.indexOf(trimmed) !== -1) {
                    Toast.error(t('mmx.interestExists'));
                    return;
                }
                interests.push(trimmed);
                localStorage.setItem('mymedx_interests', JSON.stringify(interests));
                this.renderInterests();
            },

            renderNetworkStats() {
                const container = document.getElementById('mymedxNetworkStats');
                if (!container) return;

                const connectionCount = (typeof UserPortal !== 'undefined' && typeof UserPortal.getConnectionCount === 'function')
                    ? UserPortal.getConnectionCount() : 6;
                const demo = (typeof UserPortal !== 'undefined' && typeof UserPortal.isDemoPersona === 'function' && UserPortal.isDemoPersona());
                const stats = [
                    { label: t('mmx.statConnections'), value: connectionCount, icon: 'fa-users', color: '#9b1b22' },
                    { label: t('mmx.statPending'), value: demo ? 3 : 0, icon: 'fa-user-clock', color: '#f59e0b' },
                    { label: t('mmx.statFavorites'), value: demo ? 8 : 0, icon: 'fa-star', color: '#9b1b22' }
                ];

                container.innerHTML = stats.map(function(s) {
                    return '<div style="background: var(--up-bg, #ffffff); border: 1px solid var(--up-border, #d2d2d7); border-radius: 12px; padding: 16px; text-align: center;">' +
                        '<i class="fas ' + s.icon + '" style="font-size: 18px; color: ' + s.color + '; margin-bottom: 8px; display: block;"></i>' +
                        '<div style="font-size: 22px; font-weight: 700; color: var(--up-text, #1d1d1f);">' + s.value + '</div>' +
                        '<div style="font-size: 12px; color: var(--up-text-secondary, #6e6e73); margin-top: 2px;">' + s.label + '</div>' +
                    '</div>';
                }).join('');
            },

            _isHR(){ try{ return !!(window.MedXI18n && MedXI18n.get && MedXI18n.get()==='hr'); }catch(e){ return false; } },
            _plural(n, en1, enN, hr1, hr234, hr5){ if(this._isHR()){ var mm=n%100, dd=n%10; if(dd===1&&mm!==11) return hr1; if(dd>=2&&dd<=4&&!(mm>=12&&mm<=14)) return hr234; return hr5; } return n===1?en1:enN; },

            // ===== "Your Plexus 2026" recap (R3-6) =====
            // A shareable per-member wrapped card built from REAL data (GET /api/member/wrapped):
            // gatherings joined + attended, accepted connections, certificates. Playful members get
            // a gamified card; quiet gala/forum profiles are FAIL-CLOSED to a plain, dignified variant
            // (no gamification framing). We treat quiet when EITHER the server flag or the client
            // MedXQuiet gate says so — so a stray gamified card can never leak to a quiet member. The
            // PNG is produced + downloaded/shared through the existing card-download path (_rasterize,
            // _saveBlob), the same one the membership card uses.
            async openWrapped() {
                try {
                    await this._ensureLibs();
                    if (typeof Toast !== 'undefined' && Toast.info) Toast.info(t('wrap.preparing'));
                    var tkn = (typeof UserPortal !== 'undefined' && UserPortal.token) || localStorage.getItem('medx_user_token');
                    var base = (typeof API_BASE !== 'undefined' ? API_BASE : '');
                    var data = null;
                    try {
                        var r = await fetch(base + '/api/member/wrapped', { headers: tkn ? { 'Authorization': 'Bearer ' + tkn } : {} });
                        data = r.ok ? await r.json() : null;
                    } catch (e) { data = null; }
                    // Degrade gracefully with no data, and FAIL-CLOSED to plain if anything is unsure.
                    data = data || { has_data: false, events_attended: 0, events_registered: 0, connections: 0, certificates: 0, quiet: true };
                    var plain = (data.quiet === true) || (typeof MedXQuiet !== 'undefined' && MedXQuiet.isQuiet());
                    var node = this._composeWrapped(data, plain);
                    var canvas = await this._rasterize(node, 1080, 1350);
                    var self = this;
                    canvas.toBlob(function(blob){
                        if (!blob) { if (typeof Toast !== 'undefined' && Toast.error) Toast.error(t('wrap.genFail')); return; }
                        self._showWrappedModal(blob, plain);
                    }, 'image/png');
                } catch (e) {
                    console.error('Wrapped card failed:', e);
                    if (typeof Toast !== 'undefined' && Toast.error) Toast.error(t('wrap.genFail'));
                }
            },

            _composeWrapped(data, plain) {
                var user = this._currentUser();
                var first = (data && data.first_name) || (user.first_name || (user.name || '').split(' ')[0] || '');
                var attended = (data && +data.events_attended) || 0;
                var joined = (data && +data.events_registered) || 0;
                var conn = (data && +data.connections) || 0;
                var certs = (data && +data.certificates) || 0;
                var talks = (data && +data.talks) || 0;
                var hasData = !!(data && data.has_data);
                var el = document.createElement('div');
                if (plain) {
                    // Plain, dignified variant — no big achievement numbers, no gamified language.
                    var body;
                    if (joined > 0) {
                        var gath = (joined === 1) ? t('wrap.plainGath1') : t('wrap.plainGath', { c: joined });
                        body = t('wrap.plainBody', { n: gath });
                    } else {
                        body = t('wrap.plainBodyNew');
                    }
                    el.style.cssText = "position:fixed;left:-10000px;top:0;z-index:-1;pointer-events:none;width:1080px;height:1350px;box-sizing:border-box;overflow:hidden;display:flex;flex-direction:column;background:radial-gradient(130% 120% at 18% 8%,#16223f,#0f1830 48%,#0a0f1e 100%);font-family:'Inter',-apple-system,sans-serif;color:#ffffff;";
                    el.innerHTML =
                        '<div style="height:10px;flex:0 0 auto;background:linear-gradient(90deg,#a38a4f,#c9a962,#e8d5a8,#c9a962,#a38a4f);"></div>'
                      + '<div style="flex:1 1 auto;display:flex;flex-direction:column;justify-content:center;padding:120px 96px;box-sizing:border-box;">'
                        + '<div style="display:inline-flex;align-items:center;background:#fbf9f6;border-radius:16px;padding:16px 22px;align-self:flex-start;box-shadow:0 12px 30px rgba(0,0,0,.35);margin-bottom:64px;"><img src="/assets/images/medx-logo.png" crossorigin="anonymous" style="height:50px;width:auto;display:block;"></div>'
                        + '<div style="font-size:22px;letter-spacing:8px;text-transform:uppercase;color:#e6c987;font-weight:700;margin-bottom:26px;">' + escapeHtml(t('wrap.plainEyebrow')) + '</div>'
                        + '<div style="font-family:\'Fraunces\',Georgia,serif;font-size:88px;font-weight:600;line-height:1.02;color:#ffffff;letter-spacing:-1px;margin-bottom:40px;">' + escapeHtml(t('wrap.plainTitle')) + '</div>'
                        + (first ? '<div style="font-size:30px;color:rgba(255,255,255,.62);margin-bottom:26px;">' + escapeHtml(first) + '</div>' : '')
                        + '<div style="font-size:36px;line-height:1.5;color:rgba(255,255,255,.9);max-width:820px;">' + escapeHtml(body) + '</div>'
                      + '</div>'
                      + '<div style="padding:0 96px 96px;box-sizing:border-box;font-size:24px;color:rgba(230,201,135,.72);letter-spacing:1px;">medx.hr</div>';
                    return el;
                }
                // Playful (gamified) variant.
                var tiles = [];
                var gCount = attended > 0 ? attended : joined;
                var gLabel = attended > 0
                    ? (attended === 1 ? t('wrap.statAttended1') : t('wrap.statAttended'))
                    : (joined === 1 ? t('wrap.statJoined1') : t('wrap.statJoined'));
                if (gCount > 0) tiles.push({ n: gCount, label: gLabel });
                if (talks > 0) tiles.push({ n: talks, label: talks === 1 ? t('wrap.statTalks1') : t('wrap.statTalks') });
                if (conn > 0) tiles.push({ n: conn, label: conn === 1 ? t('wrap.statConn1') : t('wrap.statConn') });
                if (certs > 0) tiles.push({ n: certs, label: certs === 1 ? t('wrap.statCerts1') : t('wrap.statCerts') });
                var tilesHtml = tiles.map(function(x){
                    return '<div style="flex:1;min-width:0;text-align:center;padding:14px 8px;">'
                        + '<div style="font-family:\'Fraunces\',Georgia,serif;font-size:104px;font-weight:600;line-height:1;color:#e6c987;">' + escapeHtml(String(x.n)) + '</div>'
                        + '<div style="font-size:24px;letter-spacing:.5px;color:rgba(255,255,255,.78);margin-top:14px;line-height:1.3;">' + escapeHtml(x.label) + '</div>'
                      + '</div>';
                }).join('<div style="width:1px;align-self:stretch;background:linear-gradient(180deg,transparent,rgba(201,169,98,.35),transparent);margin:0 6px;"></div>');
                var warm = hasData ? t('wrap.warm') : t('wrap.warmNew');
                el.style.cssText = "position:fixed;left:-10000px;top:0;z-index:-1;pointer-events:none;width:1080px;height:1350px;box-sizing:border-box;overflow:hidden;display:flex;flex-direction:column;background:radial-gradient(130% 120% at 16% 6%,#16223f,#0f1830 46%,#0a0f1e 100%);font-family:'Inter',-apple-system,sans-serif;color:#ffffff;";
                el.innerHTML =
                    '<div style="height:12px;flex:0 0 auto;background:linear-gradient(90deg,#7d161c,#9b1b22,#c2484e,#9b1b22,#7d161c);"></div>'
                  + '<div style="position:absolute;inset:0;mix-blend-mode:screen;opacity:.8;background:radial-gradient(620px 620px at 30% 14%,rgba(230,201,135,.32),rgba(230,201,135,.06) 46%,transparent 64%);"></div>'
                  + '<img src="/assets/images/medx-logo.png" crossorigin="anonymous" style="position:absolute;right:-120px;bottom:-160px;width:760px;opacity:.06;transform:rotate(-8deg);">'
                  + '<div style="position:relative;z-index:2;flex:1 1 auto;display:flex;flex-direction:column;padding:96px 88px 0;box-sizing:border-box;">'
                    + '<div style="display:flex;align-items:center;justify-content:space-between;">'
                      + '<div style="display:inline-flex;align-items:center;background:#fbf9f6;border-radius:16px;padding:16px 22px;box-shadow:0 12px 30px rgba(0,0,0,.35);"><img src="/assets/images/medx-logo.png" crossorigin="anonymous" style="height:50px;width:auto;display:block;"></div>'
                    + '</div>'
                    + '<div style="margin-top:70px;">'
                      + '<div style="font-size:24px;letter-spacing:8px;text-transform:uppercase;color:#e6c987;font-weight:700;margin-bottom:22px;">' + escapeHtml(t('wrap.eyebrow')) + '</div>'
                      + '<div style="font-family:\'Fraunces\',Georgia,serif;font-size:112px;font-weight:600;line-height:.96;color:#ffffff;letter-spacing:-2px;">' + escapeHtml(first || t('wrap.headline')) + '</div>'
                      + (first ? '<div style="font-size:34px;color:rgba(230,201,135,.85);margin-top:14px;letter-spacing:.5px;">' + escapeHtml(t('wrap.headline')) + '</div>' : '')
                    + '</div>'
                    + (tiles.length
                        ? '<div style="margin-top:auto;display:flex;align-items:flex-end;gap:0;padding:40px 0 44px;">' + tilesHtml + '</div>'
                        : '<div style="margin-top:auto;height:40px;"></div>')
                    + '<div style="border-top:1px solid rgba(201,169,98,.28);padding:44px 0 40px;font-size:34px;line-height:1.5;color:rgba(255,255,255,.9);max-width:900px;">' + escapeHtml(warm) + '</div>'
                  + '</div>'
                  + '<div style="position:relative;z-index:2;padding:0 88px 84px;box-sizing:border-box;display:flex;align-items:center;justify-content:space-between;">'
                    + '<div style="font-size:24px;color:rgba(230,201,135,.72);letter-spacing:1px;">medx.hr</div>'
                    + '<div style="font-size:22px;color:rgba(255,255,255,.45);letter-spacing:2px;text-transform:uppercase;">Plexus 2026</div>'
                  + '</div>';
                return el;
            },

            _showWrappedModal(blob, plain) {
                var self = this;
                var url = URL.createObjectURL(blob);
                var fname = plain ? 'medx-2026-recap.png' : 'plexus-2026-wrapped.png';
                var prev = document.getElementById('mxWrappedOverlay');
                if (prev && prev.parentNode) prev.parentNode.removeChild(prev);
                var overlay = document.createElement('div');
                overlay.id = 'mxWrappedOverlay';
                overlay.style.cssText = 'position:fixed;inset:0;z-index:100000;background:rgba(10,12,18,.82);-webkit-backdrop-filter:blur(6px);backdrop-filter:blur(6px);display:flex;align-items:center;justify-content:center;padding:24px;box-sizing:border-box;';
                var box = document.createElement('div');
                box.style.cssText = 'max-width:420px;width:100%;display:flex;flex-direction:column;align-items:center;gap:16px;';
                var img = document.createElement('img');
                img.src = url; img.alt = t('wrap.modalTitle');
                img.style.cssText = 'width:100%;height:auto;border-radius:18px;box-shadow:0 24px 60px rgba(0,0,0,.5);display:block;';
                var actions = document.createElement('div');
                actions.style.cssText = 'display:flex;gap:10px;flex-wrap:wrap;justify-content:center;';
                var mkBtn = function(label, primary){
                    var b = document.createElement('button');
                    b.type = 'button'; b.textContent = label;
                    b.style.cssText = 'border-radius:12px;padding:12px 20px;font-size:14px;font-weight:700;cursor:pointer;font-family:inherit;border:1px solid ' + (primary ? '#9b1b22' : 'rgba(255,255,255,.35)') + ';background:' + (primary ? '#9b1b22' : 'transparent') + ';color:#fff;';
                    return b;
                };
                var dlBtn = mkBtn(t('wrap.download'), true);
                dlBtn.addEventListener('click', function(){
                    self._saveBlob(blob, fname);
                    if (typeof Toast !== 'undefined' && Toast.success) Toast.success(t('wrap.downloaded'));
                });
                actions.appendChild(dlBtn);
                // Native share (Web Share API with files) when the platform supports it.
                try {
                    var file = new File([blob], fname, { type: 'image/png' });
                    if (navigator.canShare && navigator.canShare({ files: [file] })) {
                        var shBtn = mkBtn(t('wrap.share'), false);
                        shBtn.addEventListener('click', function(){
                            navigator.share({ files: [file], title: t('wrap.modalTitle'), text: t('wrap.shareText') }).catch(function(){});
                        });
                        actions.appendChild(shBtn);
                    }
                } catch (e) { /* Web Share unavailable — download still works */ }
                var closeBtn = mkBtn(t('wrap.close'), false);
                var close = function(){ if (overlay.parentNode) overlay.parentNode.removeChild(overlay); setTimeout(function(){ URL.revokeObjectURL(url); }, 500); };
                closeBtn.addEventListener('click', close);
                actions.appendChild(closeBtn);
                overlay.addEventListener('click', function(e){ if (e.target === overlay) close(); });
                box.appendChild(img); box.appendChild(actions);
                overlay.appendChild(box);
                document.body.appendChild(overlay);
                if (typeof Toast !== 'undefined' && Toast.success) Toast.success(t('wrap.ready'));
            },

            relocalize(){ try{ this.renderPrograms(); this.renderInterests(); this.renderNetworkStats(); if(this._regs){ this.renderRecognition(this._regs); this._renderWalletCards(this._regs); this.renderPurchases(this._regs); } if(this._record!==undefined){ this._renderRecordHtml(this._record); } if(this._giving!==undefined){ this._paintGiving(); } this.loadPoints(); this.renderMembershipCardVisual(); this.renderGuestPasses(); }catch(e){} }
        };

        // ============================================================================
        // "I'M ATTENDING" CARD ENGINE (the owner's growth feature).
        // A shareable MARKETING asset — NOT a credential, carries NO QR (never touches the frozen
        // ticket QR). Rendered entirely on the member's device with a dependency-free Canvas2D
        // renderer (also reused by the admin batch generator), so it works on prod with no headless
        // Chrome. Navy/gold heritage system, the Croatian pleter accent, and the "Golden Line"
        // campaign device. Photos stay on-device (consent flag only is recorded server-side).
        // ============================================================================
        window.MedxCard = (function(){
            var PAL = { navy:'#0E2140', navyDeep:'#0A1730', navy2:'#12305A', gold:'#C9A227', goldLight:'#E6C878', goldPale:'#F0DDA8', goldDeep:'#9C7C1A', paper:'#FBF6EA', cream:'#F4EAD2', crimson:'#9B1B22', ink:'#1C1A14', white:'#FFFFFF', muted:'#8A7F6B' };
            var DISPLAY = "'Fraunces', Georgia, 'Times New Roman', serif";
            var LABEL = "'Inter', -apple-system, 'Helvetica Neue', Arial, sans-serif";
            var FRAMES = [
                { id:'heritage', name:'Heritage', nameHr:'Baština' },
                { id:'pleter',   name:'Pleter',   nameHr:'Pleter' },
                { id:'gala',     name:'Gala',     nameHr:'Gala' }
            ];
            function size(orient){ return orient === 'landscape' ? { w:1200, h:630 } : { w:1080, h:1350 }; }
            function roundRect(ctx,x,y,w,h,r){ if(w<2*r)r=w/2; if(h<2*r)r=h/2; ctx.beginPath(); ctx.moveTo(x+r,y); ctx.arcTo(x+w,y,x+w,y+h,r); ctx.arcTo(x+w,y+h,x,y+h,r); ctx.arcTo(x,y+h,x,y,r); ctx.arcTo(x,y,x+w,y,r); ctx.closePath(); }
            function goldGrad(ctx,x0,y0,x1,y1){ var g=ctx.createLinearGradient(x0,y0,x1,y1); g.addColorStop(0,'#9C7C1A'); g.addColorStop(.28,PAL.gold); g.addColorStop(.5,PAL.goldLight); g.addColorStop(.72,PAL.gold); g.addColorStop(1,'#9C7C1A'); return g; }
            function drawCover(ctx,img,x,y,w,h){ try{ var ir=img.width/img.height, r=w/h, sw,sh,sx,sy; if(ir>r){ sh=img.height; sw=sh*r; sx=(img.width-sw)/2; sy=0; } else { sw=img.width; sh=sw/r; sx=0; sy=(img.height-sh)/2; } ctx.drawImage(img,sx,sy,sw,sh,x,y,w,h); }catch(e){} }
            function initials(name){ var p=String(name||'').trim().split(/\s+/).filter(Boolean); if(!p.length) return 'MX'; return (p[0].charAt(0)+(p.length>1?p[p.length-1].charAt(0):'')).toUpperCase(); }
            // Golden monogram fallback — a gold-ringed roundel with the member's initials in serif.
            function drawMonogram(ctx,cx,cy,rad,ini,onDark){
                ctx.save();
                ctx.beginPath(); ctx.arc(cx,cy,rad,0,Math.PI*2);
                ctx.fillStyle = onDark ? PAL.navy2 : PAL.navy; ctx.fill();
                ctx.lineWidth = Math.max(3, rad*0.05); ctx.strokeStyle = goldGrad(ctx,cx-rad,cy-rad,cx+rad,cy+rad); ctx.stroke();
                ctx.beginPath(); ctx.arc(cx,cy,rad*0.86,0,Math.PI*2); ctx.lineWidth = Math.max(1, rad*0.012); ctx.strokeStyle='rgba(230,201,135,.45)'; ctx.stroke();
                ctx.fillStyle = PAL.goldLight; ctx.textAlign='center'; ctx.textBaseline='middle';
                ctx.font = '600 ' + Math.round(rad*0.9) + "px " + DISPLAY;
                ctx.fillText(ini, cx, cy+rad*0.04);
                ctx.restore();
            }
            // A braided gold cord — a warm nod to the Croatian pleter (troplet) interlace.
            function drawPleter(ctx,x,y,w,h,vertical){
                ctx.save();
                var strands=3, amp=(vertical?w:h)*0.30, lam=(vertical?w:h)*2.1, mid=(vertical?x+w/2:y+h/2);
                ctx.lineCap='round';
                for(var s=0;s<strands;s++){
                    var ph=(Math.PI*2/strands)*s;
                    ctx.beginPath();
                    if(vertical){ for(var t=0;t<=h;t+=6){ var xx=mid+amp*Math.sin((Math.PI*2*t/lam)+ph); if(t===0)ctx.moveTo(xx,y+t); else ctx.lineTo(xx,y+t); } }
                    else { for(var u=0;u<=w;u+=6){ var yy=mid+amp*Math.sin((Math.PI*2*u/lam)+ph); if(u===0)ctx.moveTo(x+u,yy); else ctx.lineTo(x+u,yy); } }
                    ctx.lineWidth = (vertical?w:h)*0.12; ctx.strokeStyle = goldGrad(ctx,x,y,x+ (vertical?w:0), y+(vertical?0:h)); ctx.globalAlpha = 0.9 - s*0.16; ctx.stroke();
                }
                ctx.restore();
            }
            function goldLine(ctx,x,y,w){ ctx.save(); var g=goldGrad(ctx,x,y,x+w,y); ctx.fillStyle=g; ctx.fillRect(x,y,w,3); ctx.restore(); }
            // Largest size from list that fits maxW on one line; else wrap to 2 lines at the smallest.
            function fitName(ctx,name,maxW,sizes){
                for(var i=0;i<sizes.length;i++){ ctx.font='600 '+sizes[i]+'px '+DISPLAY; if(ctx.measureText(name).width<=maxW) return { size:sizes[i], lines:[name] }; }
                var sz=sizes[sizes.length-1]; ctx.font='600 '+sz+'px '+DISPLAY;
                var words=String(name).split(/\s+/), lines=[], cur='';
                for(var w=0;w<words.length;w++){ var test=cur?cur+' '+words[w]:words[w]; if(ctx.measureText(test).width>maxW && cur){ lines.push(cur); cur=words[w]; } else cur=test; if(lines.length>=1 && w<words.length-1){ /* allow 2nd line to keep filling */ } }
                if(cur) lines.push(cur);
                if(lines.length>2){ lines=[lines[0], lines.slice(1).join(' ')]; }
                return { size:sz, lines:lines };
            }
            function label(ctx,text,x,y,spacing,size,color,align){
                ctx.save(); ctx.fillStyle=color; ctx.textAlign=align||'left'; ctx.textBaseline='alphabetic'; ctx.font='700 '+size+'px '+LABEL;
                var s=String(text||''); if(!spacing){ ctx.fillText(s,x,y); ctx.restore(); return; }
                // manual letter-spacing for even kerning across browsers
                var total=0,i; for(i=0;i<s.length;i++){ total+=ctx.measureText(s[i]).width+spacing; } total-=spacing;
                var cx = align==='center' ? x-total/2 : (align==='right' ? x-total : x);
                ctx.textAlign='left';
                for(i=0;i<s.length;i++){ ctx.fillText(s[i],cx,y); cx+=ctx.measureText(s[i]).width+spacing; }
                ctx.restore();
            }

            function render(opts){
                opts = opts || {};
                var orient = opts.orientation === 'landscape' ? 'landscape' : 'portrait';
                var d = size(orient);
                var cv = document.createElement('canvas'); cv.width=d.w; cv.height=d.h;
                var ctx = cv.getContext('2d');
                var frame = opts.frame || 'heritage';
                var name = String(opts.name||'Med&X').trim();
                var ini = initials(name);
                if(frame==='pleter') drawPleterFrame(ctx,d,orient,opts,name,ini);
                else if(frame==='gala') drawGalaFrame(ctx,d,orient,opts,name,ini);
                else drawHeritageFrame(ctx,d,orient,opts,name,ini);
                return cv;
            }

            // ---- Frame 1: Heritage (navy) ---------------------------------------------------------
            function drawHeritageFrame(ctx,d,orient,o,name,ini){
                var g=ctx.createLinearGradient(0,0,0,d.h); g.addColorStop(0,PAL.navy); g.addColorStop(1,PAL.navyDeep);
                ctx.fillStyle=g; ctx.fillRect(0,0,d.w,d.h);
                var glow=ctx.createRadialGradient(d.w*0.22,d.h*0.16,0,d.w*0.22,d.h*0.16,d.w*0.7);
                glow.addColorStop(0,'rgba(230,201,135,.16)'); glow.addColorStop(.5,'rgba(230,201,135,.04)'); glow.addColorStop(1,'rgba(230,201,135,0)');
                ctx.fillStyle=glow; ctx.fillRect(0,0,d.w,d.h);
                ctx.fillStyle=goldGrad(ctx,0,0,d.w,0); ctx.fillRect(0,0,d.w,10);
                if(orient==='landscape'){
                    var pr=200, pcx=250, pcy=d.h/2;
                    photoRoundel(ctx,o.photo,pcx,pcy,pr,ini,true);
                    var tx=500;
                    label(ctx,o.eyebrow||'',tx,pcy-160,7,26,PAL.goldLight,'left');
                    var fn=fitName(ctx,name,d.w-tx-70,[62,54,46,40]); ctx.fillStyle=PAL.white; ctx.textAlign='left';
                    var ny=pcy-160+58; fn.lines.forEach(function(ln){ ctx.font='600 '+fn.size+'px '+DISPLAY; ctx.fillText(ln,tx,ny); ny+=fn.size*1.05; });
                    if(o.sub){ ctx.fillStyle='rgba(230,201,135,.85)'; ctx.font='400 24px '+LABEL; ctx.fillText(clip(ctx,o.sub,d.w-tx-70,'400 24px '+LABEL),tx,ny+8); ny+=40; }
                    goldLine(ctx,tx,ny+18,150);
                    ctx.fillStyle=PAL.goldLight; ctx.font='600 22px '+DISPLAY; ctx.fillText(o.lockup||'',tx,ny+64);
                    if(o.dateline){ ctx.fillStyle='rgba(255,255,255,.66)'; ctx.font='400 17px '+LABEL; ctx.fillText(o.dateline,tx,ny+92); }
                    return;
                }
                var cx=d.w/2;
                photoRoundel(ctx,o.photo,cx,430,230,ini,true);
                label(ctx,o.eyebrow||'',cx,760,9,30,PAL.goldLight,'center');
                var fn2=fitName(ctx,name,d.w-160,[92,78,66,56]); ctx.fillStyle=PAL.white; ctx.textAlign='center';
                var y=760+118; fn2.lines.forEach(function(ln){ ctx.font='600 '+fn2.size+'px '+DISPLAY; ctx.fillText(ln,cx,y); y+=fn2.size*1.02; });
                if(o.sub){ ctx.fillStyle='rgba(230,201,135,.85)'; ctx.font='400 30px '+LABEL; ctx.textAlign='center'; ctx.fillText(clip(ctx,o.sub,d.w-200,'400 30px '+LABEL),cx,y+14); y+=52; }
                ctx.save(); goldLine(ctx,cx-90,y+40,180); ctx.restore();
                ctx.fillStyle=PAL.goldLight; ctx.font='600 34px '+DISPLAY; ctx.textAlign='center'; ctx.fillText(o.lockup||'',cx,y+112);
                if(o.dateline){ ctx.fillStyle='rgba(255,255,255,.66)'; ctx.font='400 22px '+LABEL; ctx.textAlign='center'; ctx.fillText(o.dateline,cx,y+150); }
                ctx.fillStyle='rgba(230,201,135,.6)'; ctx.font='400 20px '+LABEL; ctx.textAlign='center'; ctx.fillText(o.footer||'medx.hr',cx,d.h-48);
            }

            // ---- Frame 2: Pleter (paper) ----------------------------------------------------------
            function drawPleterFrame(ctx,d,orient,o,name,ini){
                ctx.fillStyle=PAL.paper; ctx.fillRect(0,0,d.w,d.h);
                var vign=ctx.createRadialGradient(d.w/2,d.h*0.4,d.w*0.2,d.w/2,d.h*0.5,d.w*0.8);
                vign.addColorStop(0,'rgba(0,0,0,0)'); vign.addColorStop(1,'rgba(120,95,30,.07)'); ctx.fillStyle=vign; ctx.fillRect(0,0,d.w,d.h);
                if(orient==='landscape'){
                    ctx.fillStyle=PAL.cream; ctx.fillRect(0,0,96,d.h); drawPleter(ctx,20,20,56,d.h-40,true);
                    ctx.fillStyle=goldGrad(ctx,0,0,d.w,0); ctx.fillRect(96,0,d.w-96,6);
                    var pr=190, pcx=330, pcy=d.h/2; photoRoundel(ctx,o.photo,pcx,pcy,pr,ini,false,true);
                    var tx=560;
                    label(ctx,o.eyebrow||'',tx,pcy-150,6,24,PAL.crimson,'left');
                    var fn=fitName(ctx,name,d.w-tx-60,[60,52,44,38]); ctx.fillStyle=PAL.navy; ctx.textAlign='left';
                    var ny=pcy-150+56; fn.lines.forEach(function(ln){ ctx.font='600 '+fn.size+'px '+DISPLAY; ctx.fillText(ln,tx,ny); ny+=fn.size*1.05; });
                    if(o.sub){ ctx.fillStyle=PAL.muted; ctx.font='400 23px '+LABEL; ctx.fillText(clip(ctx,o.sub,d.w-tx-60,'400 23px '+LABEL),tx,ny+6); ny+=38; }
                    goldLine(ctx,tx,ny+16,140);
                    ctx.fillStyle=PAL.navy; ctx.font='600 22px '+DISPLAY; ctx.fillText(o.lockup||'',tx,ny+62);
                    if(o.dateline){ ctx.fillStyle=PAL.muted; ctx.font='400 17px '+LABEL; ctx.fillText(o.dateline,tx,ny+90); }
                    return;
                }
                ctx.fillStyle=PAL.cream; ctx.fillRect(0,0,110,d.h); drawPleter(ctx,26,40,58,d.h-80,true);
                ctx.fillStyle=goldGrad(ctx,110,0,d.w,0); ctx.fillRect(110,0,d.w-110,7);
                var cx=(d.w+110)/2;
                photoRoundel(ctx,o.photo,cx,410,220,ini,false,true);
                label(ctx,o.eyebrow||'',cx,720,8,28,PAL.crimson,'center');
                var fn2=fitName(ctx,name,d.w-260,[86,74,62,52]); ctx.fillStyle=PAL.navy; ctx.textAlign='center';
                var y=720+112; fn2.lines.forEach(function(ln){ ctx.font='600 '+fn2.size+'px '+DISPLAY; ctx.fillText(ln,cx,y); y+=fn2.size*1.02; });
                if(o.sub){ ctx.fillStyle=PAL.muted; ctx.font='400 29px '+LABEL; ctx.textAlign='center'; ctx.fillText(clip(ctx,o.sub,d.w-320,'400 29px '+LABEL),cx,y+12); y+=50; }
                goldLine(ctx,cx-85,y+38,170);
                ctx.fillStyle=PAL.navy; ctx.font='600 34px '+DISPLAY; ctx.textAlign='center'; ctx.fillText(o.lockup||'',cx,y+108);
                if(o.dateline){ ctx.fillStyle=PAL.muted; ctx.font='400 22px '+LABEL; ctx.textAlign='center'; ctx.fillText(o.dateline,cx,y+146); }
                ctx.fillStyle=PAL.goldDeep; ctx.font='400 20px '+LABEL; ctx.textAlign='center'; ctx.fillText(o.footer||'medx.hr',cx,d.h-48);
            }

            // ---- Frame 3: Gala (dramatic navy, photo-forward) -------------------------------------
            function drawGalaFrame(ctx,d,orient,o,name,ini){
                ctx.fillStyle=PAL.navyDeep; ctx.fillRect(0,0,d.w,d.h);
                if(orient==='landscape'){
                    var pw=d.w*0.44;
                    ctx.save(); ctx.beginPath(); ctx.rect(0,0,pw,d.h); ctx.clip();
                    if(o.photo){ drawCover(ctx,o.photo,0,0,pw,d.h); } else { ctx.fillStyle=PAL.navy2; ctx.fillRect(0,0,pw,d.h); drawMonogram(ctx,pw/2,d.h/2,150,ini,true); }
                    var sc=ctx.createLinearGradient(pw-160,0,pw,0); sc.addColorStop(0,'rgba(10,23,48,0)'); sc.addColorStop(1,'rgba(10,23,48,1)'); ctx.fillStyle=sc; ctx.fillRect(pw-160,0,160,d.h);
                    ctx.restore();
                    ctx.fillStyle=goldGrad(ctx,pw,0,d.w,0); ctx.fillRect(pw,0,d.w-pw,5);
                    var tx=pw+56;
                    label(ctx,o.eyebrow||'',tx,d.h/2-140,7,25,PAL.goldLight,'left');
                    var fn=fitName(ctx,name,d.w-tx-56,[64,54,46,40]); ctx.fillStyle=PAL.white; ctx.textAlign='left';
                    var ny=d.h/2-140+58; fn.lines.forEach(function(ln){ ctx.font='600 '+fn.size+'px '+DISPLAY; ctx.fillText(ln,tx,ny); ny+=fn.size*1.05; });
                    if(o.sub){ ctx.fillStyle='rgba(230,201,135,.85)'; ctx.font='400 23px '+LABEL; ctx.fillText(clip(ctx,o.sub,d.w-tx-56,'400 23px '+LABEL),tx,ny+6); ny+=38; }
                    goldLine(ctx,tx,ny+16,140);
                    ctx.fillStyle=PAL.goldLight; ctx.font='600 22px '+DISPLAY; ctx.fillText(o.lockup||'',tx,ny+62);
                    if(o.dateline){ ctx.fillStyle='rgba(255,255,255,.66)'; ctx.font='400 16px '+LABEL; ctx.fillText(o.dateline,tx,ny+90); }
                    return;
                }
                var ph=800;
                ctx.save(); ctx.beginPath(); ctx.rect(0,0,d.w,ph); ctx.clip();
                if(o.photo){ drawCover(ctx,o.photo,0,0,d.w,ph); } else { ctx.fillStyle=PAL.navy2; ctx.fillRect(0,0,d.w,ph); drawMonogram(ctx,d.w/2,ph/2-40,180,ini,true); }
                var scr=ctx.createLinearGradient(0,ph-360,0,ph); scr.addColorStop(0,'rgba(10,23,48,0)'); scr.addColorStop(1,'rgba(10,23,48,1)'); ctx.fillStyle=scr; ctx.fillRect(0,ph-360,d.w,360);
                ctx.restore();
                ctx.fillStyle=goldGrad(ctx,0,0,d.w,0); ctx.fillRect(0,0,d.w,10);
                // gold "golden line" arc rising from the seam
                ctx.save(); ctx.beginPath(); ctx.arc(d.w/2, ph+520, 640, Math.PI*1.16, Math.PI*1.84); ctx.lineWidth=2.5; ctx.strokeStyle='rgba(201,162,39,.5)'; ctx.stroke(); ctx.restore();
                var cx=d.w/2, y=ph+18;
                label(ctx,o.eyebrow||'',cx,y+20,9,30,PAL.goldLight,'center');
                var fn2=fitName(ctx,name,d.w-160,[90,76,64,54]); ctx.fillStyle=PAL.white; ctx.textAlign='center';
                var ny2=y+96; fn2.lines.forEach(function(ln){ ctx.font='600 '+fn2.size+'px '+DISPLAY; ctx.fillText(ln,cx,ny2); ny2+=fn2.size*1.02; });
                if(o.sub){ ctx.fillStyle='rgba(230,201,135,.85)'; ctx.font='400 29px '+LABEL; ctx.textAlign='center'; ctx.fillText(clip(ctx,o.sub,d.w-200,'400 29px '+LABEL),cx,ny2+10); ny2+=48; }
                goldLine(ctx,cx-85,ny2+34,170);
                ctx.fillStyle=PAL.goldLight; ctx.font='600 33px '+DISPLAY; ctx.textAlign='center'; ctx.fillText(o.lockup||'',cx,ny2+100);
                if(o.dateline){ ctx.fillStyle='rgba(255,255,255,.68)'; ctx.font='400 22px '+LABEL; ctx.textAlign='center'; ctx.fillText(o.dateline,cx,ny2+138); }
                ctx.fillStyle='rgba(230,201,135,.6)'; ctx.font='400 20px '+LABEL; ctx.textAlign='center'; ctx.fillText(o.footer||'medx.hr',cx,d.h-46);
            }

            // A circular portrait window with a gold ring, or the monogram fallback.
            function photoRoundel(ctx,img,cx,cy,rad,ini,onDark,paperRing){
                ctx.save();
                if(img){
                    ctx.beginPath(); ctx.arc(cx,cy,rad,0,Math.PI*2); ctx.closePath(); ctx.save(); ctx.clip();
                    drawCover(ctx,img,cx-rad,cy-rad,rad*2,rad*2); ctx.restore();
                    ctx.beginPath(); ctx.arc(cx,cy,rad,0,Math.PI*2); ctx.lineWidth=Math.max(4,rad*0.045); ctx.strokeStyle=goldGrad(ctx,cx-rad,cy-rad,cx+rad,cy+rad); ctx.stroke();
                    ctx.beginPath(); ctx.arc(cx,cy,rad*0.9,0,Math.PI*2); ctx.lineWidth=1.4; ctx.strokeStyle=(paperRing?'rgba(120,95,30,.3)':'rgba(230,201,135,.4)'); ctx.stroke();
                } else {
                    drawMonogram(ctx,cx,cy,rad,ini,onDark);
                }
                ctx.restore();
            }
            function clip(ctx,text,maxW,font){ ctx.save(); ctx.font=font; var s=String(text||''); if(ctx.measureText(s).width<=maxW){ ctx.restore(); return s; } while(s.length>1 && ctx.measureText(s+'…').width>maxW){ s=s.slice(0,-1); } ctx.restore(); return s+'…'; }

            return { render:render, FRAMES:FRAMES, PAL:PAL, initials:initials };
        })();

        // ---- Member studio: choose a frame, add a photo (consent), preview, download, copy caption.
        const ImAttendingCard = {
            _built:false, _overlay:null,
            state:{ frame:'heritage', event:'conference', photo:null, photoSource:'none', consent:false },
            EVENTS:{
                conference:{ lockupEn:'Plexus Conference · by Med&X', lockupHr:'Plexus konferencija · Med&X', dateEn:'Zagreb · December 2026', dateHr:'Zagreb · prosinac 2026.' },
                gala:{ lockupEn:'Plexus Gala · by Med&X', lockupHr:'Plexus Gala · Med&X', dateEn:'5 December 2026 · Hotel Esplanade, Zagreb', dateHr:'5. prosinca 2026. · Hotel Esplanade, Zagreb' }
            },
            _lang(){ return (window.MedXI18n && MedXI18n.get) ? MedXI18n.get() : 'en'; },
            _T(k){ return (typeof t==='function') ? t(k) : k; },
            _member(){ try{ return (typeof MyMedXPortal!=='undefined' && MyMedXPortal._currentUser) ? MyMedXPortal._currentUser() : ((typeof UserPortal!=='undefined' && UserPortal.user)||{}); }catch(e){ return {}; } },
            _name(){ var u=this._member(); return (u.name || ((u.first_name||'')+' '+(u.last_name||'')).trim()) || 'Med&X Member'; },
            _sub(){ var u=this._member(); return u.institution || u.affiliation || ''; },

            open(){
                this.ensureBuilt();
                this._overlay.classList.add('active');
                document.body.style.overflow='hidden';
                // default: if the member has a loaded profile photo, offer it pre-selected (still consent-gated)
                this._profilePhoto = (typeof MyMedXPortal!=='undefined' && MyMedXPortal._photoUrl) ? MyMedXPortal._photoUrl : null;
                this.renderControls();
                this.renderPreview();
            },
            close(){ if(this._overlay) this._overlay.classList.remove('active'); document.body.style.overflow=''; },

            ensureStyle(){
                if(document.getElementById('imcStyle')) return;
                var css = ''
                + '.imc-overlay{position:fixed;inset:0;z-index:100001;display:none;align-items:center;justify-content:center;padding:20px;box-sizing:border-box;background:radial-gradient(120% 120% at 20% 0%,rgba(18,33,64,.92),rgba(8,14,26,.94));-webkit-backdrop-filter:blur(8px);backdrop-filter:blur(8px);}'
                + '.imc-overlay.active{display:flex;}'
                + '.imc-shell{width:100%;max-width:940px;max-height:92vh;overflow:auto;background:#fbf9f6;border-radius:20px;box-shadow:0 40px 100px rgba(0,0,0,.5);border:1px solid rgba(201,162,39,.35);}'
                + '.imc-top{display:flex;align-items:flex-start;justify-content:space-between;gap:12px;padding:22px 26px 6px;}'
                + '.imc-title{font-family:\'Fraunces\',Georgia,serif;font-size:23px;font-weight:700;color:#0E2140;line-height:1.15;}'
                + '.imc-sub{font-size:13.5px;color:#6b6455;margin-top:4px;max-width:560px;line-height:1.5;}'
                + '.imc-x{background:none;border:none;font-size:28px;line-height:1;color:#9a917f;cursor:pointer;padding:0 4px;}'
                + '.imc-body{display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:22px;padding:14px 26px 26px;}'
                + '.imc-stage{display:flex;flex-direction:column;align-items:center;justify-content:flex-start;gap:14px;}'
                + '.imc-canvaswrap{width:100%;max-width:340px;border-radius:16px;overflow:hidden;box-shadow:0 20px 50px rgba(14,33,64,.28);background:#0E2140;}'
                + '.imc-canvaswrap canvas{width:100%;height:auto;display:block;}'
                + '.imc-orient{display:flex;gap:8px;}'
                + '.imc-orient button{border:1px solid #e3dccb;background:#fff;color:#6b6455;border-radius:9px;padding:7px 14px;font-size:12.5px;font-weight:700;cursor:pointer;font-family:inherit;}'
                + '.imc-orient button.on{background:#0E2140;color:#fff;border-color:#0E2140;}'
                + '.imc-rail{display:flex;flex-direction:column;gap:16px;}'
                + '.imc-sec>label{display:block;font-size:11px;font-weight:800;letter-spacing:.06em;text-transform:uppercase;color:#8a8272;margin-bottom:8px;}'
                + '.imc-frames{display:flex;gap:8px;}'
                + '.imc-frame{flex:1;border:2px solid #e3dccb;border-radius:12px;padding:6px 6px 8px;background:#fff;cursor:pointer;text-align:center;}'
                + '.imc-frame.on{border-color:#C9A227;box-shadow:0 4px 14px rgba(201,162,39,.25);}'
                + '.imc-frame canvas{width:100%;height:auto;border-radius:7px;display:block;}'
                + '.imc-frame span{display:block;font-size:11px;font-weight:700;color:#5c5646;margin-top:5px;}'
                + '.imc-seg{display:flex;gap:6px;flex-wrap:wrap;}'
                + '.imc-seg button{flex:1;min-width:80px;border:1px solid #e3dccb;background:#fff;color:#6b6455;border-radius:9px;padding:9px 8px;font-size:12.5px;font-weight:700;cursor:pointer;font-family:inherit;}'
                + '.imc-seg button.on{background:#9B1B22;color:#fff;border-color:#9B1B22;}'
                + '.imc-consent{display:flex;gap:10px;align-items:flex-start;background:#f6f1e6;border:1px solid #e6ddc7;border-radius:12px;padding:12px 13px;font-size:12.5px;color:#5c5646;line-height:1.5;}'
                + '.imc-consent input{width:18px;height:18px;margin-top:1px;accent-color:#9B1B22;flex-shrink:0;}'
                + '.imc-hint{font-size:11.5px;color:#9a917f;line-height:1.5;}'
                + '.imc-actions{display:flex;flex-direction:column;gap:9px;}'
                + '.imc-btn{border:none;border-radius:11px;padding:13px;font-size:13.5px;font-weight:800;cursor:pointer;font-family:inherit;display:flex;align-items:center;justify-content:center;gap:8px;}'
                + '.imc-btn.primary{background:#0E2140;color:#fff;}'
                + '.imc-btn.gold{background:linear-gradient(120deg,#9C7C1A,#C9A227,#E6C878,#C9A227);color:#1c1a14;}'
                + '.imc-btn.ghost{background:#fff;border:1px solid #d9d2c1;color:#5c5646;}'
                + '.imc-btn2{display:flex;gap:9px;}.imc-btn2 .imc-btn{flex:1;}'
                + '.imc-file{display:none;}'
                + '@media(max-width:760px){.imc-body{grid-template-columns:1fr;}.imc-canvaswrap{max-width:260px;}}';
                var st=document.createElement('style'); st.id='imcStyle'; st.textContent=css; document.head.appendChild(st);
            },
            ensureBuilt(){
                if(this._built) return; this.ensureStyle();
                var ov=document.createElement('div'); ov.className='imc-overlay'; ov.id='imcOverlay';
                ov.innerHTML = ''
                + '<div class="imc-shell" role="dialog" aria-modal="true">'
                + '  <div class="imc-top"><div><div class="imc-title" id="imcTitle"></div><div class="imc-sub" id="imcSubtitle"></div></div><button class="imc-x" id="imcClose" aria-label="Close">&times;</button></div>'
                + '  <div class="imc-body">'
                + '    <div class="imc-stage">'
                + '      <div class="imc-orient" id="imcOrient"></div>'
                + '      <div class="imc-canvaswrap" id="imcCanvasWrap"></div>'
                + '    </div>'
                + '    <div class="imc-rail" id="imcRail"></div>'
                + '  </div>'
                + '  <input type="file" accept="image/*" class="imc-file" id="imcFile">'
                + '</div>';
                document.body.appendChild(ov); this._overlay=ov; this._built=true; this._orient='portrait';
                var self=this;
                ov.addEventListener('click', function(e){ if(e.target===ov) self.close(); });
                ov.querySelector('#imcClose').addEventListener('click', function(){ self.close(); });
                ov.querySelector('#imcFile').addEventListener('change', function(e){ self._onFile(e); });
                document.addEventListener('keydown', function(e){ if(e.key==='Escape' && self._overlay && self._overlay.classList.contains('active')) self.close(); });
            },

            renderControls(){
                var self=this, lang=this._lang();
                var ov=this._overlay;
                ov.querySelector('#imcTitle').textContent=this._T('imc.studioTitle');
                ov.querySelector('#imcSubtitle').textContent=this._T('imc.studioSub');
                // orientation toggle
                var orient=ov.querySelector('#imcOrient');
                orient.innerHTML='';
                [['portrait','imc.orientPortrait'],['landscape','imc.orientLandscape']].forEach(function(p){
                    var b=document.createElement('button'); b.textContent=self._T(p[1]); if(self._orient===p[0])b.className='on';
                    b.addEventListener('click', function(){ self._orient=p[0]; self.renderControls(); self.renderPreview(); }); orient.appendChild(b);
                });
                // frames
                var framesHtml = MedxCard.FRAMES.map(function(f){
                    var nm = lang==='hr' ? f.nameHr : f.name;
                    return '<div class="imc-frame'+(self.state.frame===f.id?' on':'')+'" data-frame="'+f.id+'"><div class="imc-fcv" data-fcv="'+f.id+'"></div><span>'+nm+'</span></div>';
                }).join('');
                var rail=ov.querySelector('#imcRail');
                rail.innerHTML = ''
                + '<div class="imc-sec"><label>'+this._T('imc.frame')+'</label><div class="imc-frames" id="imcFrames">'+framesHtml+'</div></div>'
                + '<div class="imc-sec"><label>'+this._T('imc.event')+'</label><div class="imc-seg" id="imcEvent">'
                +   '<button data-evt="conference" class="'+(this.state.event==='conference'?'on':'')+'">'+this._T('imc.evtConference')+'</button>'
                +   '<button data-evt="gala" class="'+(this.state.event==='gala'?'on':'')+'">'+this._T('imc.evtGala')+'</button>'
                + '</div></div>'
                + '<div class="imc-sec"><label>'+this._T('imc.photo')+'</label><div class="imc-seg" id="imcPhoto">'
                +   '<button data-ph="upload" class="'+(this.state.photoSource==='upload'?'on':'')+'">'+this._T('imc.usePhoto')+'</button>'
                +   (this._profilePhoto?'<button data-ph="profile" class="'+(this.state.photoSource==='profile'?'on':'')+'">'+this._T('imc.useProfile')+'</button>':'')
                +   '<button data-ph="none" class="'+(this.state.photoSource==='none'?'on':'')+'">'+this._T('imc.noPhoto')+'</button>'
                + '</div><div class="imc-hint">'+this._T('imc.photoHint')+'</div></div>'
                + '<label class="imc-consent"><input type="checkbox" id="imcConsent" '+(this.state.consent?'checked':'')+'><span>'+this._T('imc.consentLabel')+'</span></label>'
                + '<div class="imc-actions">'
                +   '<div class="imc-btn2"><button class="imc-btn primary" data-dl="portrait"><i class="fas fa-download"></i> '+this._T('imc.dlPortrait')+'</button>'
                +   '<button class="imc-btn primary" data-dl="landscape"><i class="fas fa-download"></i> '+this._T('imc.dlLandscape')+'</button></div>'
                +   '<div class="imc-btn2"><button class="imc-btn ghost" data-cap="en"><i class="fas fa-copy"></i> '+this._T('imc.copyEn')+'</button>'
                +   '<button class="imc-btn ghost" data-cap="hr"><i class="fas fa-copy"></i> '+this._T('imc.copyHr')+'</button></div>'
                + '</div>';
                // wire (delegated within rail — no inline handlers)
                rail.querySelectorAll('#imcFrames .imc-frame').forEach(function(el){ el.addEventListener('click', function(){ self.state.frame=el.getAttribute('data-frame'); self.renderControls(); self.renderPreview(); }); });
                rail.querySelectorAll('#imcEvent button').forEach(function(b){ b.addEventListener('click', function(){ self.state.event=b.getAttribute('data-evt'); self.renderControls(); self.renderPreview(); }); });
                rail.querySelectorAll('#imcPhoto button').forEach(function(b){ b.addEventListener('click', function(){ self._pickPhotoSource(b.getAttribute('data-ph')); }); });
                rail.querySelector('#imcConsent').addEventListener('change', function(e){ self.state.consent=!!e.target.checked; if(!self.state.consent){/*keep photo obj but preview will drop it*/} self.renderPreview(); self._syncConsent(); });
                rail.querySelectorAll('[data-dl]').forEach(function(b){ b.addEventListener('click', function(){ self.download(b.getAttribute('data-dl')); }); });
                rail.querySelectorAll('[data-cap]').forEach(function(b){ b.addEventListener('click', function(){ self.copyCaption(b.getAttribute('data-cap')); }); });
                this._renderFrameThumbs();
            },

            _pickPhotoSource(src){
                var self=this;
                if(src==='upload'){ this._overlay.querySelector('#imcFile').click(); return; }
                if(src==='profile' && this._profilePhoto){
                    var img=new Image(); img.crossOrigin='anonymous';
                    img.onload=function(){ self.state.photo=img; self.state.photoSource='profile'; self.renderControls(); self.renderPreview(); };
                    img.onerror=function(){ if(typeof Toast!=='undefined'&&Toast.error) Toast.error(self._T('imc.photoErr')); };
                    img.src=this._profilePhoto; return;
                }
                this.state.photo=null; this.state.photoSource='none'; this.renderControls(); this.renderPreview();
            },
            _onFile(e){
                var self=this, file=e.target.files && e.target.files[0]; if(!file) return;
                if(!/^image\//.test(file.type)){ if(typeof Toast!=='undefined'&&Toast.error) Toast.error(self._T('imc.photoErr')); return; }
                var rd=new FileReader();
                rd.onload=function(ev){ var img=new Image(); img.onload=function(){ self.state.photo=img; self.state.photoSource='upload'; self.renderControls(); self.renderPreview(); }; img.onerror=function(){ if(typeof Toast!=='undefined'&&Toast.error) Toast.error(self._T('imc.photoErr')); }; img.src=ev.target.result; };
                rd.readAsDataURL(file);
                e.target.value='';
            },

            _opts(orient){
                var lang=this._lang(), ev=this.EVENTS[this.state.event]||this.EVENTS.conference;
                var usePhoto = this.state.photo && this.state.consent;
                return {
                    frame:this.state.frame, orientation:orient||this._orient,
                    eyebrow:this._T('imc.eyebrow').toUpperCase(),
                    name:this._name(), sub:this._sub(),
                    lockup: lang==='hr'?ev.lockupHr:ev.lockupEn,
                    dateline: lang==='hr'?ev.dateHr:ev.dateEn,
                    footer:'medx.hr',
                    photo: usePhoto ? this.state.photo : null
                };
            },
            renderPreview(){
                var wrap=this._overlay.querySelector('#imcCanvasWrap'); if(!wrap) return;
                var self=this;
                var draw=function(){ try{ var cv=MedxCard.render(self._opts(self._orient)); wrap.innerHTML=''; wrap.appendChild(cv); }catch(e){ console.error('card preview failed',e); } };
                if(document.fonts && document.fonts.ready){ document.fonts.ready.then(draw); setTimeout(draw,60); } else draw();
            },
            _renderFrameThumbs(){
                var self=this;
                var run=function(){ MedxCard.FRAMES.forEach(function(f){ var host=self._overlay.querySelector('[data-fcv="'+f.id+'"]'); if(!host)return; try{ var o=self._opts('portrait'); o.frame=f.id; var cv=MedxCard.render(o); cv.style.width='100%'; host.innerHTML=''; host.appendChild(cv); }catch(e){} }); };
                if(document.fonts && document.fonts.ready){ document.fonts.ready.then(run); setTimeout(run,60); } else run();
            },

            download(orient){
                var self=this;
                if(this.state.photo && !this.state.consent){ if(typeof Toast!=='undefined'&&Toast.warning) Toast.warning(this._T('imc.consentNeeded')); return; }
                var run=function(){
                    try{
                        var cv=MedxCard.render(self._opts(orient));
                        cv.toBlob(function(blob){
                            if(!blob){ if(typeof Toast!=='undefined'&&Toast.error) Toast.error(self._T('imc.dlErr')); return; }
                            var fname='plexus-attending-'+(orient==='landscape'?'wide':'portrait')+'.png';
                            var url=URL.createObjectURL(blob); var a=document.createElement('a'); a.href=url; a.download=fname; document.body.appendChild(a); a.click(); document.body.removeChild(a); setTimeout(function(){ URL.revokeObjectURL(url); },1500);
                            if(typeof Toast!=='undefined'&&Toast.success) Toast.success(self._T('imc.downloaded'));
                            if(self.state.photo && self.state.consent) self._syncConsent();
                        }, 'image/png');
                    }catch(e){ console.error('card download failed',e); if(typeof Toast!=='undefined'&&Toast.error) Toast.error(self._T('imc.dlErr')); }
                };
                if(document.fonts && document.fonts.ready){ document.fonts.ready.then(run); } else run();
            },

            // Assembled captions from the brand blueprint social framework (four beats: hook, story,
            // belonging, invite). Formal Vi in the Croatian invite.
            _caption(lang){
                var gala=this.state.event==='gala';
                if(lang==='hr'){
                    return gala
                    ? 'Godine 1377. hrvatski je grad donio prvi zakon o karanteni na svijetu. Petog prosinca bit ću u dvorani u kojoj se ta priča nastavlja.\n\nPetog prosinca bit ću na Plexus Gali u hotelu Esplanade u Zagrebu, među ljudima koji oblikuju medicinu u ovoj zemlji, ne napuštajući je.\n\nOvo je tradicija koju Med&X nosi dalje, i ove godine ja sam njezin dio. Ako radite u medicini u Hrvatskoj, nađimo se ondje.\n\n@Med&X #PlexusGala #CroatianMedicine'
                    : 'Hrvatska medicina svijetu je dala dva nobelovca i jednog od utemeljitelja SZO-a. Ove godine stajat ću unutar te tradicije.\n\nBit ću na Plexus konferenciji u Zagrebu, među ljudima koji oblikuju medicinu u ovoj zemlji, ne napuštajući je.\n\nOvo je tradicija koju Med&X nosi dalje, i ove godine ja sam njezin dio. Ako radite u medicini u Hrvatskoj, nađimo se ondje.\n\n@Med&X #Plexus2026 #CroatianMedicine';
                }
                return gala
                ? "In 1377, a Croatian city wrote the world's first quarantine law. On 5 December, I will be in the room where that story keeps going.\n\nOn 5 December I will be at the Plexus Gala at Hotel Esplanade in Zagreb, among the people shaping medicine in this country, without leaving it.\n\nThis is the tradition Med&X was built to carry forward, and this year I am part of it. If you work in medicine in Croatia, come find me there.\n\n@Med&X #PlexusGala #CroatianMedicine"
                : "Croatian medicine gave the world two Nobel laureates and a founder of the WHO. This year I get to stand inside that tradition.\n\nI will be at the Plexus Conference in Zagreb, among the people shaping medicine in this country, without leaving it.\n\nThis is the tradition Med&X was built to carry forward, and this year I am part of it. If you work in medicine in Croatia, come find me there.\n\n@Med&X #Plexus2026 #CroatianMedicine";
            },
            copyCaption(lang){
                var self=this, text=this._caption(lang);
                var done=function(){ if(typeof Toast!=='undefined'&&Toast.success) Toast.success(self._T('imc.copied')); };
                if(navigator.clipboard && navigator.clipboard.writeText){ navigator.clipboard.writeText(text).then(done).catch(function(){ self._fallbackCopy(text); done(); }); }
                else { this._fallbackCopy(text); done(); }
            },
            _fallbackCopy(text){ try{ var ta=document.createElement('textarea'); ta.value=text; ta.style.position='fixed'; ta.style.left='-9999px'; document.body.appendChild(ta); ta.select(); document.execCommand('copy'); document.body.removeChild(ta); }catch(e){} },

            _syncConsent(){
                try{
                    var tkn=(typeof UserPortal!=='undefined'&&UserPortal.token)||localStorage.getItem('medx_user_token');
                    var base=(typeof API_BASE!=='undefined'?API_BASE:'');
                    fetch(base+'/api/member/card-consent',{ method:'POST', headers:Object.assign({'Content-Type':'application/json'}, tkn?{'Authorization':'Bearer '+tkn}:{}), body:JSON.stringify({ consent:!!this.state.consent }) }).catch(function(){});
                }catch(e){}
            },
            relocalize(){ if(this._overlay && this._overlay.classList.contains('active')){ this.renderControls(); this.renderPreview(); } }
        };
        // Single delegated trigger (CSP-clean — no inline on* handler on the button).
        document.addEventListener('click', function(e){ var el=e.target.closest && e.target.closest('[data-imc-open]'); if(el){ e.preventDefault(); try{ ImAttendingCard.open(); }catch(err){ console.error(err); } } });
        document.addEventListener('medx:localechange', function(){ try{ ImAttendingCard.relocalize(); }catch(e){} });

        document.addEventListener('medx:localechange', function(){ try{ if(typeof MyMedXPortal!=='undefined' && MyMedXPortal.relocalize) MyMedXPortal.relocalize(); }catch(e){} });
        document.addEventListener('medx:localechange', function(){ try{ if(typeof RewardsPortal!=='undefined' && RewardsPortal.data) RewardsPortal.render(); }catch(e){} });
        document.addEventListener('medx:localechange', function(){ try{ if(typeof SettingsPortal!=='undefined' && SettingsPortal.renderMembership) SettingsPortal.renderMembership(); }catch(e){} });
        document.addEventListener('medx:localechange', function(){ try{ var pnl=document.getElementById('hubNotificationsDropdown'); if(pnl && pnl.classList.contains('active') && typeof Dashboard!=='undefined' && Dashboard.toggleNotifications){ pnl.classList.remove('active'); Dashboard.toggleNotifications(); } }catch(e){} });
        document.addEventListener('medx:localechange', function(){ try{ if(typeof NotificationSystem!=='undefined'){ if(NotificationSystem.render) NotificationSystem.render(); if(NotificationSystem.renderAdminMessages) NotificationSystem.renderAdminMessages(); } }catch(e){} });
        document.addEventListener('medx:localechange', function(){ try{ if(window.MedXPush){ MedXPush.reflectSettingsToggle(); var _pb=document.getElementById('pushPermissionBanner'); if(_pb&&_pb.classList.contains('active')) MedXPush._applyBannerCopy(); } }catch(e){} });
        document.addEventListener('medx:localechange', function(){ try{ if(typeof Dashboard!=='undefined'){ if(Dashboard.updateAccountBadge) Dashboard.updateAccountBadge(); if(Dashboard.updateAccountDropdown) Dashboard.updateAccountDropdown(); } }catch(e){} });


