                'wrap.genFail':      { en: 'We could not create your card right now. Please try again in a moment.', hr: 'Trenutačno ne možemo izraditi vašu karticu. Pokušajte ponovno za koji trenutak.' },
                'wrap.modalTitle':   { en: 'Your Plexus 2026', hr: 'Vaš Plexus 2026' },
                'wrap.download':     { en: 'Download', hr: 'Preuzmite' },
                'wrap.share':        { en: 'Share', hr: 'Podijelite' },
                'wrap.close':        { en: 'Close', hr: 'Zatvorite' },
                'wrap.downloaded':   { en: 'Card saved', hr: 'Kartica je spremljena' },
                'wrap.shareText':    { en: 'My year with Med&X, Plexus 2026', hr: 'Moja godina s Med&X-om, Plexus 2026' },
                // Card face — playful (gamified) variant
                'wrap.eyebrow':      { en: 'YOUR YEAR WITH MED&X', hr: 'VAŠA GODINA S MED&X-OM' },
