                'wrap.statAttended1':{ en: 'gathering attended', hr: 'okupljanje posjećeno' },
                'wrap.statJoined':   { en: 'gatherings joined', hr: 'okupljanja upisano' },
                'wrap.statJoined1':  { en: 'gathering joined', hr: 'okupljanje upisano' },
                'wrap.statConn':     { en: 'connections made', hr: 'povezivanja ostvareno' },
                'wrap.statConn1':    { en: 'connection made', hr: 'povezivanje ostvareno' },
                'wrap.statCerts':    { en: 'certificates earned', hr: 'potvrda stečeno' },
                'wrap.statCerts1':   { en: 'certificate earned', hr: 'potvrda stečena' },
