                        const name = user.name || `${user.first_name || ''} ${user.last_name || ''}`.trim() || 'User';
                        const initials = name.split(' ').map(n => n[0]).join('').toUpperCase().substring(0, 2);

                        const avatarEl = document.getElementById('profileQuickAvatar');
                        const floatingAvatarEl = document.getElementById('floatingProfileAvatar');
                        const nameEl = document.getElementById('profileQuickName');
                        const roleEl = document.getElementById('profileQuickRole');

                        if (avatarEl) avatarEl.textContent = initials;
                        if (floatingAvatarEl) floatingAvatarEl.textContent = initials;
                        if (nameEl) nameEl.textContent = name;
                        if (roleEl) roleEl.textContent = user.role || 'Member';
