            toggleQuickOrb() {
                const orb = document.getElementById('quickActionsOrb');
                const expanded = document.getElementById('quickActionsExpanded');
                if (!orb || !expanded) return;

                // Close events orb if open
                const eventsExpanded = document.getElementById('quickEventsExpanded');
                if (eventsExpanded && eventsExpanded.classList.contains('active')) {
                    this.toggleEventsOrb();
                }

                if (expanded.classList.contains('active')) {
                    // Closing - add closing class for animation
                    expanded.classList.add('closing');
                    setTimeout(() => {
                        expanded.classList.remove('active');
                        expanded.classList.remove('closing');
                        orb.classList.remove('expanded');
                    }, 600);
                } else {
                    // Opening
                    orb.classList.add('expanded');
                    expanded.classList.add('active');
                }
            },

            toggleEventsOrb() {
                const orb = document.getElementById('quickEventsOrb');
                const expanded = document.getElementById('quickEventsExpanded');
                if (!orb || !expanded) return;

                // Close programs orb if open
                const programsExpanded = document.getElementById('quickActionsExpanded');
                if (programsExpanded && programsExpanded.classList.contains('active')) {
                    this.toggleQuickOrb();
                }

                if (expanded.classList.contains('active')) {
                    // Closing - add closing class for animation
                    expanded.classList.add('closing');
                    setTimeout(() => {
                        expanded.classList.remove('active');
                        expanded.classList.remove('closing');
                        orb.classList.remove('expanded');
                    }, 600);
                } else {
                    // Opening
                    orb.classList.add('expanded');
                    expanded.classList.add('active');
                }
            },

