            // Event countdown
            updateEventCountdowns() {
                const now = new Date();

                // Plexus countdown
                const plexusDate = new Date(window.MEDX_DATES.plexus.start);
                const plexusDiff = Math.ceil((plexusDate - now) / (1000 * 60 * 60 * 24));
                const plexusEl = document.getElementById('plexusCountdown');
                if (plexusEl) plexusEl.textContent = plexusDiff + ' days';

                // AF26 (Annual Biomedical Forum) countdown — starts in Split on 25 May 2026
                const af26Date = new Date(window.MEDX_DATES.af26.start);
                const af26Diff = Math.ceil((af26Date - now) / (1000 * 60 * 60 * 24));
                const af26El = document.getElementById('af26Countdown');
                if (af26El) af26El.textContent = af26Diff + ' days';
            },

