            handleNotificationClick(notifId, actionUrl) {
                // Mark as read
                if (notifId) {
                    var token = UserPortal.token;
                    var apiBase = typeof API_BASE !== 'undefined' ? API_BASE : '';
                    fetch(apiBase + '/api/user-notifications/' + notifId + '/read', {
                        method: 'PUT',
                        headers: token ? { 'Authorization': 'Bearer ' + token } : {}
                    }).catch(function() {});
                }
                // Navigate if action URL
                if (actionUrl) {
                    if (actionUrl.startsWith('#') || actionUrl.startsWith('/')) {
                        var section = actionUrl.replace('#', '').replace('/', '');
                        UserPortal.showSection(section);
                    }
                }
                // Close notifications panel
                var panel = document.getElementById('hubNotificationsDropdown');
                if (panel) panel.classList.remove('active');
            },

            timeAgo(date) {
                var hr = !!(window.MedXI18n && MedXI18n.get && MedXI18n.get()==='hr');
                var seconds = Math.floor((new Date() - date) / 1000);
                if (seconds < 60) return hr ? 'upravo sada' : 'just now';
                var minutes = Math.floor(seconds / 60);
                if (minutes < 60) return hr ? ('prije ' + minutes + ' min') : (minutes + 'm ago');
                var hours = Math.floor(minutes / 60);
                if (hours < 24) return hr ? ('prije ' + hours + ' h') : (hours + 'h ago');
                var days = Math.floor(hours / 24);
                if (days < 7) return hr ? ('prije ' + days + ' ' + (days === 1 ? 'dan' : 'dana')) : (days + 'd ago');
                return date.toLocaleDateString(hr ? 'hr-HR' : 'en-US');
            },

            // Show notifications from the grid menu (closes menu first, then shows notifications)
            showNotificationsFromMenu(event) {
                event.stopPropagation();

                // First close the menu
                const menu = document.getElementById('hubMenuExpanded');
                const btn = document.getElementById('hubMenuBtn');
                const greeting = document.querySelector('.hub-greeting');
                const logo = document.querySelector('.hub-header-left');
                const accountBtn = document.querySelector('.hub-account-btn');

                if (menu) {
                    menu.classList.add('closing');
                    btn.style.transform = 'rotate(0deg)';
                    if (greeting) greeting.classList.remove('faded');
                    if (logo) logo.classList.remove('faded');
                    if (accountBtn) accountBtn.classList.remove('faded');

                    setTimeout(() => {
                        menu.classList.remove('active');
                        menu.classList.remove('closing');
                        if (btn) btn.classList.remove('active');

                        // Now show notifications after menu is closed
                        setTimeout(() => {
                            this.toggleNotifications();
                        }, 50);
                    }, 280);
                }
            },

