                // Clear both badge locations
                var menuBtnBadge = document.getElementById('hubMenuBtnBadge');
                var menuItemBadge = document.getElementById('hubMenuNotifBadge');
                if (menuBtnBadge) menuBtnBadge.style.display = 'none';
                if (menuItemBadge) menuItemBadge.style.display = 'none';
                var items = document.querySelectorAll('.hub-notif-item.unread');
                items.forEach(function(item) { item.classList.remove('unread'); });
