                if (!dropdown) return;

                // Close other dropdowns first
                var projectsDropdown = document.getElementById('hubProjectsDropdown');
                var notifDropdown = document.getElementById('hubNotificationsDropdown');
                var projectsWrapper = document.querySelector('.hub-projects-wrapper');
