            updateAccountDropdown() {
                const user = UserPortal.user || { name: 'User', email: 'user@example.com' };

                // Use RewardsPortal.getNextTierInfo() as single source of truth
                let info = { currentTier: 'bronze', currentTierName: 'Bronze', pointsBalance: 0, progress: 0 };
                if (typeof RewardsPortal !== 'undefined' && RewardsPortal.getNextTierInfo) {
                    try { info = RewardsPortal.getNextTierInfo(); } catch(e) { /* userRewards not yet initialized */ }
                }

                // Get user name (handle both name formats)
                const firstName = user.first_name || user.firstName || (user.name ? user.name.split(' ')[0] : 'User');
                const lastName = user.last_name || user.lastName || (user.name ? user.name.split(' ').slice(1).join(' ') : '');
                const fullName = user.name || `${firstName} ${lastName}`.trim() || 'User';

                // Update avatar
                const avatarEl = document.getElementById('hubDropdownAvatar');
                if (avatarEl) {
                    avatarEl.textContent = firstName.charAt(0).toUpperCase();
                }

                // Update name and email
                const nameEl = document.getElementById('hubDropdownName');
                if (nameEl) {
                    nameEl.textContent = fullName;
                }

                const emailEl = document.getElementById('hubDropdownEmail');
                if (emailEl) {
                    emailEl.textContent = user.email || 'user@example.com';
                }

                // Update tier badge (from single source of truth)
                const tierEl = document.getElementById('hubDropdownTier');
                if (tierEl) {
                    tierEl.className = `hub-account-dropdown-tier ${info.currentTier}`;
                    tierEl.innerHTML = `<i class="fas fa-crown"></i> ${Dashboard._locTierName(info.currentTier, info.currentTierName)}`;
                }

                // Update points (pointsBalance, not totalPointsEarned)
                const pointsEl = document.getElementById('hubDropdownPoints');
                if (pointsEl) {
                    pointsEl.innerHTML = Dashboard._ptsHTML(info.pointsBalance.toLocaleString());
                }

                // Update progress bar
                const progressEl = document.getElementById('hubDropdownProgress');
                if (progressEl) {
                    progressEl.style.width = `${info.progress}%`;
                    progressEl.className = `hub-account-dropdown-progress-fill ${info.currentTier}`;
                }

                // Update theme icon
                const themeIcon = document.getElementById('hubDropdownThemeIcon');
                if (themeIcon) {
                    themeIcon.className = UserPortal.theme === 'dark' ? 'fas fa-sun' : 'fas fa-moon';
                }
            },

