            // Toggle required documents section
            toggleRequiredDocs() {
                const body = document.getElementById('axRequiredDocsBody');
                const chevron = document.getElementById('axDocsChevron');
                if (body) {
                    const isHidden = body.style.display === 'none';
                    body.style.display = isHidden ? 'block' : 'none';
                    if (chevron) {
                        chevron.style.transform = isHidden ? 'rotate(180deg)' : 'rotate(0deg)';
                    }
                }
            },

            // Toggle FAQ item
            toggleFaq(element) {
                // Close other open FAQ items
                document.querySelectorAll('.ax-faq-item.open').forEach(item => {
                    if (item !== element) {
                        item.classList.remove('open');
                    }
                });
                // Toggle clicked item
                element.classList.toggle('open');
            },

            // Application Checklist
            checklistItems: [
                { id: 'personal', label: 'Personal info', fields: ['axFirstName', 'axLastName', 'axEmail', 'axDob'] },
                { id: 'education', label: 'Education details', fields: ['axInstitution', 'axDegree', 'axYear'] },
                { id: 'institutions', label: 'Institution preferences', fields: ['axChoice1'] },
                { id: 'motivation', label: 'Motivation statement', fields: ['axStatement'] },
                { id: 'documents', label: 'Documents uploaded', fields: [] },
                { id: 'review', label: 'Application reviewed', fields: [] }
            ],

            updateChecklist() {
                const widget = document.getElementById('axChecklistWidget');
                if (!widget) return;

                let completedCount = 0;
                const items = widget.querySelectorAll('.ax-checklist-item');

                this.checklistItems.forEach((item, idx) => {
                    let isComplete = false;

                    if (item.fields.length > 0) {
                        // Check if all fields have values
                        isComplete = item.fields.every(fieldId => {
                            const field = document.getElementById(fieldId);
                            return field && field.value && field.value.trim() !== '';
                        });
                    }

                    if (items[idx]) {
                        if (isComplete) {
                            items[idx].classList.add('completed');
                            completedCount++;
                        } else {
                            items[idx].classList.remove('completed');
                        }
                    }
                });

                // Update progress bar
                const progressBar = widget.querySelector('.ax-checklist-progress-bar');
                const percentValue = widget.querySelector('.ax-checklist-percent-value');
                const percent = Math.round((completedCount / this.checklistItems.length) * 100);

                if (progressBar) progressBar.style.width = percent + '%';
                if (percentValue) percentValue.textContent = percent + '%';
            },

            initChecklist() {
                // Add input listeners to all form fields
                const formFields = document.querySelectorAll('#ax-panel-apply input, #ax-panel-apply select, #ax-panel-apply textarea');
                formFields.forEach(field => {
                    field.addEventListener('input', () => this.updateChecklist());
                    field.addEventListener('change', () => this.updateChecklist());
                });

                // Initial update
                this.updateChecklist();
            },

            handleFileSelect(input) {
                const feedback = input.nextElementSibling;
                if (!feedback || !feedback.classList.contains('ax-file-feedback')) return;
                if (input.files && input.files.length > 0) {
                    const file = input.files[0];
                    feedback.querySelector('.ax-file-name').textContent = file.name + ' (' + (file.size / 1024).toFixed(1) + ' KB)';
                    feedback.style.display = 'block';
                } else {
                    feedback.style.display = 'none';
                }
                this.updateChecklist();
            },

            // Download document template
            downloadDoc(docType) {
                const docNames = {
                    'cv': 'CV_Template.docx',
                    'motivation': 'Motivation_Letter_Guidelines.pdf',
                    'recommendation': 'Recommendation_Letter_Template.docx',
                    'transcript': 'Transcript_Requirements.pdf',
                    'research': 'Research_Statement_Guidelines.pdf',
                    'passport': 'Passport_Requirements.pdf'
                };

                const docName = docNames[docType] || 'Document.pdf';

                // In production, this would download actual files
                Toast.info(`Downloading: ${docName} Note: This is a demo. In production, actual document templates would be downloaded.`);
            },

