                        <div style="display: flex; align-items: center; gap: 12px; margin-bottom: 16px;">
                            <div style="width: 44px; height: 44px; border-radius: 50%; background: var(--up-bg-muted); display: flex; align-items: center; justify-content: center; color: var(--up-text-muted);"><i class="fas fa-user"></i></div>
                            <div>
                                <div style="font-size: 15px; font-weight: 600; color: var(--up-text);">${escapeHtml(post.author)}</div>
                                <div style="font-size: 12px; color: var(--up-text-muted);">${escapeHtml(post.time)}</div>
                            </div>
                        </div>
