            // ========== MY SCHEDULE VIEW ==========

            renderMySchedule() {
                if (!this.speaker) return;

                const timeline = document.getElementById('spMyScheduleTimeline');
                const empty = document.getElementById('spMyScheduleEmpty');
                if (!timeline || !empty) return;

                // Include speaker's own sessions + bookmarked sessions
                let allItems = [];

                // Add speaker's own sessions
                this.speaker.events.forEach(event => {
                    allItems.push({
                        eventId: event.eventId,
                        eventName: event.eventName,
                        eventDate: event.eventDate,
                        time: event.sessionTime.split(' - ')[0],
                        title: event.sessionTitle,
                        room: event.room,
                        type: 'my-session',
                        isMySession: true
                    });
                });

                // Add bookmarked sessions
                if (this.speaker.mySchedule) {
                    this.speaker.mySchedule.forEach(item => {
                        const event = this.speaker.events.find(e => e.eventId === item.eventId);
                        allItems.push({
                            ...item,
                            eventName: event?.eventName || 'Unknown Event',
                            isMySession: false
                        });
                    });
                }

                // Filter by current filter
                if (this.myScheduleFilter !== 'all') {
                    allItems = allItems.filter(item => item.eventId === this.myScheduleFilter);
                }

                // Sort by date and time
                allItems.sort((a, b) => {
                    const dateCompare = a.eventDate.localeCompare(b.eventDate);
                    if (dateCompare !== 0) return dateCompare;
                    return a.time.localeCompare(b.time);
                });

                if (allItems.length === 0) {
                    timeline.style.display = 'none';
                    empty.style.display = 'block';
                    return;
                }

                timeline.style.display = 'block';
                empty.style.display = 'none';

                // Group by date
                const byDate = {};
                allItems.forEach(item => {
                    if (!byDate[item.eventDate]) byDate[item.eventDate] = [];
                    byDate[item.eventDate].push(item);
                });

                let html = '';
                Object.keys(byDate).sort().forEach(date => {
                    const dateObj = new Date(date);
                    const dateStr = dateObj.toLocaleDateString('en-US', {
                        weekday: 'long', month: 'long', day: 'numeric', year: 'numeric'
                    });

                    html += `
                        <div class="sp-myschedule-day">
                            <div class="sp-myschedule-day-header">
                                <h3>${dateStr}</h3>
                                <span>${byDate[date][0].eventName}</span>
                            </div>
                            <div class="sp-myschedule-items">
                    `;

                    byDate[date].forEach(item => {
                        html += `
                            <div class="sp-myschedule-item ${item.isMySession ? 'my-session' : ''}">
                                <div class="sp-myschedule-item-time">${item.time}</div>
                                <div class="sp-myschedule-item-content">
                                    <div class="sp-myschedule-item-title">${item.title}</div>
                                    <div class="sp-myschedule-item-meta">
                                        ${item.room ? `<span><i class="fas fa-door-open"></i> ${item.room}</span>` : ''}
                                        ${item.isMySession ? '<span class="sp-my-session-badge"><i class="fas fa-microphone"></i> Your Session</span>' : ''}
                                    </div>
                                </div>
                                ${!item.isMySession ? `
                                <div class="sp-myschedule-item-actions">
                                    <button class="sp-myschedule-item-btn" onclick="SpeakerPortal.removeFromMySchedule('${item.eventId}', ${item.sessionIndex})" title="Remove">
                                        <i class="fas fa-times"></i>
                                    </button>
                                </div>
                                ` : ''}
                            </div>
                        `;
                    });

                    html += '</div></div>';
                });

                timeline.innerHTML = html;
            },

            filterMySchedule(filter) {
                this.myScheduleFilter = filter;

                // Update filter buttons
                document.querySelectorAll('.sp-filter-btn').forEach(btn => {
                    btn.classList.toggle('active', btn.dataset.filter === filter);
                });

                this.renderMySchedule();
            },

            removeFromMySchedule(eventId, sessionIndex) {
                if (!this.speaker.mySchedule) return;

                this.speaker.mySchedule = this.speaker.mySchedule.filter(s =>
                    !(s.eventId === eventId && s.sessionIndex === sessionIndex)
                );

                this.saveSpeakerData();
                this.renderMySchedule();
                this.showToast('Removed from schedule');
            },

            downloadMySchedule() {
                if (!this.speaker) return;

                let content = `MY PERSONALIZED SCHEDULE\n`;
                content += `Speaker: ${this.speaker.name}\n`;
                content += `${'='.repeat(50)}\n\n`;

                // Get all items
                let allItems = [];

                this.speaker.events.forEach(event => {
                    allItems.push({
                        eventDate: event.eventDate,
                        eventName: event.eventName,
                        time: event.sessionTime.split(' - ')[0],
                        title: event.sessionTitle,
                        room: event.room,
                        isMySession: true
                    });
                });

                if (this.speaker.mySchedule) {
                    this.speaker.mySchedule.forEach(item => {
                        const event = this.speaker.events.find(e => e.eventId === item.eventId);
                        allItems.push({
                            ...item,
                            eventName: event?.eventName || 'Unknown',
                            isMySession: false
                        });
                    });
                }

                // Sort and format
                allItems.sort((a, b) => {
                    const d = a.eventDate.localeCompare(b.eventDate);
                    return d !== 0 ? d : a.time.localeCompare(b.time);
                });

                let currentDate = '';
                allItems.forEach(item => {
                    if (item.eventDate !== currentDate) {
                        currentDate = item.eventDate;
                        const dateObj = new Date(currentDate);
                        content += `\n${dateObj.toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' })}\n`;
                        content += `${'-'.repeat(40)}\n`;
                    }
                    content += `${item.time} - ${item.title}`;
                    if (item.room) content += ` (${item.room})`;
                    if (item.isMySession) content += ' *** YOUR SESSION ***';
                    content += '\n';
                });

                const blob = new Blob([content], { type: 'text/plain' });
                const link = document.createElement('a');
                link.href = URL.createObjectURL(blob);
                link.download = 'My_MedX_Schedule.txt';
                link.click();

                this.showToast('Schedule downloaded!');
            },

            emailMySchedule() {
                if (!this.speaker) return;

                // In production, this would call the backend to send an email
                // For now, simulate success
                this.showToast(`Schedule will be sent to ${this.speaker.email}`);

            },

