                const initials = this.speaker.name.split(' ').map(n => n[0]).join('').substring(0, 2);

                // Update display elements
                const initialsEl = document.getElementById('spProfileInitials');
                const nameDisplay = document.getElementById('spProfileNameDisplay');
                const titleDisplay = document.getElementById('spProfileTitleDisplay');
                const instDisplay = document.getElementById('spProfileInstDisplay');

                if (initialsEl) initialsEl.textContent = initials;
                if (nameDisplay) nameDisplay.textContent = this.speaker.name;
                if (titleDisplay) titleDisplay.textContent = this.speaker.title || '';
                if (instDisplay) instDisplay.textContent = this.speaker.institution || '';

                // Fill form fields
                const nameInput = document.getElementById('spProfileName');
                const emailInput = document.getElementById('spProfileEmail');
                const titleInput = document.getElementById('spProfileTitle');
                const instInput = document.getElementById('spProfileInstitution');
                const bioInput = document.getElementById('spProfileBio');
                const linkedinInput = document.getElementById('spProfileLinkedIn');
                const twitterInput = document.getElementById('spProfileTwitter');
                const directoryToggle = document.getElementById('spShowInDirectory');

                if (nameInput) nameInput.value = this.speaker.name || '';
                if (emailInput) emailInput.value = this.speaker.email || '';
                if (titleInput) titleInput.value = this.speaker.title || '';
                if (instInput) instInput.value = this.speaker.institution || '';
                if (bioInput) bioInput.value = this.speaker.bio || '';
                if (linkedinInput) linkedinInput.value = this.speaker.linkedin || '';
                if (twitterInput) twitterInput.value = this.speaker.twitter || '';
                if (directoryToggle) directoryToggle.checked = this.speaker.showInDirectory !== false;

                // Load preferences
                this.loadPreferences();
