            saveShift(e) {
                e.preventDefault();
                const shift = {
                    id: 'SHIFT-' + Date.now(),
                    name: document.getElementById('pxShiftName').value,
                    date: document.getElementById('pxShiftDate').value,
                    location: document.getElementById('pxShiftLocation').value,
                    start_time: document.getElementById('pxShiftStart').value,
                    end_time: document.getElementById('pxShiftEnd').value,
                    volunteers_needed: parseInt(document.getElementById('pxShiftVolunteers').value),
                    description: document.getElementById('pxShiftDesc').value,
                    assigned: []
                };

                // Add to mock data
                if (!MOCK_DATA.plexus.volunteerShifts) {
                    MOCK_DATA.plexus.volunteerShifts = [];
                }
                MOCK_DATA.plexus.volunteerShifts.push(shift);

                this.closeShiftModal();
                this.loadPlexusVolunteers();
                this.showToast('Shift created successfully');
            },

            async loadPlexusCheckinStats() {
                let stats;
                try {
                    stats = await this.api('/api/admin/plexus/stats');
                } catch (err) {
                    stats = MOCK_DATA.plexus.stats;
                }

                document.getElementById('pxCheckinTotal').textContent = stats.checked_in || 0;
                document.getElementById('pxCheckinRemaining').textContent = (stats.total_registrations || 0) - (stats.checked_in || 0);

                // Load recent check-ins
                const container = document.getElementById('pxRecentCheckins');
                const recentCheckins = MOCK_DATA.checkin.recent || [];

                if (recentCheckins.length === 0) {
                    container.innerHTML = '<p style="color: var(--text-muted); text-align: center; padding: 20px;">No check-ins yet. Use the input above to check in attendees.</p>';
                } else {
                    container.innerHTML = recentCheckins.slice(0, 10).map(c => `
                        <div class="recent-checkin-item">
                            <div class="check-icon"><i class="fas fa-check"></i></div>
                            <div class="info">
                                <div class="name">${this.escapeHtml(c.name || c.email)}</div>
                                <div class="time">${new Date(c.checked_in_at).toLocaleTimeString()}</div>
                            </div>
                        </div>
                    `).join('');
                }
            },

            async performCheckin() {
                const input = document.getElementById('pxCheckinInput');
                const code = input.value.trim();
                const resultDiv = document.getElementById('pxCheckinResult');

                if (!code) {
                    resultDiv.className = 'checkin-result error';
                    resultDiv.innerHTML = '<i class="fas fa-exclamation-circle"></i> Please enter a registration ID or scan a QR code';
                    return;
                }

                try {
                    const result = await this.api('/api/plexus/checkin', {
                        method: 'POST',
                        body: JSON.stringify({ code })
                    });

                    if (result.success) {
                        if (result.already_checked_in) {
                            resultDiv.className = 'checkin-result already';
                            resultDiv.innerHTML = `<i class="fas fa-info-circle"></i> ${this.escapeHtml(result.name)} was already checked in`;
                        } else {
                            resultDiv.className = 'checkin-result success';
                            resultDiv.innerHTML = `<i class="fas fa-check-circle"></i> Welcome, ${this.escapeHtml(result.name)}!`;
                        }
                        input.value = '';
                        this.loadPlexusCheckinStats();
                    } else {
                        resultDiv.className = 'checkin-result error';
                        resultDiv.innerHTML = `<i class="fas fa-times-circle"></i> ${this.escapeHtml(result.error || 'Registration not found')}`;
                    }
                } catch (err) {
                    resultDiv.className = 'checkin-result error';
                    resultDiv.innerHTML = '<i class="fas fa-times-circle"></i> Check-in failed. Please try again.';
                }
            },

            async loadPlexusPending() {
                let pending;
                try {
                    pending = await this.api('/api/admin/plexus/pending');
                } catch (err) {
                    pending = MOCK_DATA.plexus.pending;
                }
                this.plexusPending = pending;

                // Render each pending section
                this.renderPendingList('pxPendingRefundsList', pending.refunds || [], 'refund');
                this.renderPendingList('pxPendingVisasList', pending.visas || [], 'visa');
                this.renderPendingList('pxPendingScholarshipsList', pending.scholarships || [], 'scholarship');
                this.renderPendingList('pxPendingTransfersList', pending.transfers || [], 'transfer');
                this.renderPendingList('pxPendingSpeakersList', pending.speaker_apps || [], 'speaker');
            },

            renderPendingList(containerId, items, type) {
                const container = document.getElementById(containerId);
                if (!container) return;

                if (!items || items.length === 0) {
                    container.innerHTML = '<p style="color: var(--text-muted); font-size: 13px;">No pending items</p>';
                    return;
                }

                container.innerHTML = items.map(item => `
                    <div style="display: flex; justify-content: space-between; align-items: center; padding: 12px; background: var(--bg-tertiary); border-radius: 8px; margin-bottom: 8px;">
                        <div>
                            <div style="font-weight: 500;">${this.escapeHtml(item.name || item.email || 'Unknown')}</div>
                            <div style="font-size: 12px; color: var(--text-muted);">${item.reason || item.details || ''}</div>
                        </div>
                        <div class="actions">
                            <button class="btn btn-primary" style="padding: 6px 12px;" onclick="App.approvePendingItem('${type}', '${item.id}')">Approve</button>
                            <button class="btn btn-secondary" style="padding: 6px 12px;" onclick="App.rejectPendingItem('${type}', '${item.id}')">Reject</button>
                        </div>
                    </div>
                `).join('');
            },

            async approvePendingItem(type, id) {
                try {
                    await this.api(`/api/admin/plexus/${type}/${id}/approve`, { method: 'POST' });
                    await this.loadPlexusPending();
                    await this.loadPlexusStats();
                } catch (err) {
                    console.error('Failed to approve:', err);
                    Toast.error('Failed to approve item');
                }
            },

            async rejectPendingItem(type, id) {
                try {
                    await ConfirmationModal.show({
                        type: 'warning',
                        title: 'Reject Request?',
                        message: 'Reject this request?',
                        confirmText: 'Reject',
                        cancelText: 'Cancel'
                    });
                } catch (e) { return; }
                try {
                    await this.api(`/api/admin/plexus/${type}/${id}/reject`, { method: 'POST' });
                    await this.loadPlexusPending();
                    await this.loadPlexusStats();
                } catch (err) {
                    console.error('Failed to reject:', err);
                    Toast.error('Failed to reject item');
                }
            },

