            showBridgesTab(tab, btnEl) {
                this.bridgesCurrentTab = tab;

                // Update tab buttons
                document.querySelectorAll('#section-bridges .tab-btn').forEach(t => t.classList.remove('active'));
                if (btnEl) btnEl.classList.add('active');

                // Update content panels
                document.querySelectorAll('.bridges-admin-tab').forEach(c => c.classList.remove('active'));
                const panel = document.getElementById(`bridges-tab-${tab}`);
                if (panel) {
                    panel.classList.add('active');
                    panel.style.display = 'block';
                }

                // Hide other panels
                document.querySelectorAll('.bridges-admin-tab').forEach(c => {
                    if (c.id !== `bridges-tab-${tab}`) {
                        c.style.display = 'none';
                    }
                });

                // Load data for specific tabs
                if (tab === 'speakers') this.loadBridgesSpeakers();
                if (tab === 'program') { this.loadBridgesSpeakers(); this.loadBridgesProgram(); }
            },

