            showAF26SubTab(tab) {
                // Scope to forum-af26 section
                document.querySelectorAll('#forum-af26 .af26-tab').forEach(t => t.classList.remove('active'));
                document.querySelector(`#forum-af26 .af26-tab[onclick*="'${tab}'"]`)?.classList.add('active');

                document.querySelectorAll('#forum-af26 .af26-content').forEach(c => c.classList.remove('active'));
                document.getElementById(`af26-${tab}`)?.classList.add('active');

                switch(tab) {
                    case 'overview': this.loadAF26Overview(); break;
                    case 'registrations': this.loadAF26Registrations(); break;
                    case 'invites': this.loadAF26Invites(); break;
                    case 'speakers': this.loadAF26Speakers(); break;
                    case 'schedule': this.loadAF26Schedule(); break;
                    case 'checkin': this.loadAF26Checkins(); break;
                }
            },

