                    document.getElementById('af26StatInvited').textContent = stats.invited || 0;
                    document.getElementById('af26StatSpeakers').textContent = stats.speakers || 0;
                    document.getElementById('af26StatCheckedIn').textContent = stats.checked_in || 0;
                    document.getElementById('af26Confirmed').textContent = stats.confirmed || 0;
