        const AdminApprovals = {
            pendingUsers: [],

            init() {
                this.load();
                this.render();
            },

            load() {
                // Load pending users from localStorage
                const saved = localStorage.getItem('medx_pending_users');
                if (saved) {
                    this.pendingUsers = JSON.parse(saved);
                } else {
                    // Demo data for initial display
                    this.pendingUsers = [
                        {
                            id: 'pending-1',
                            name: 'Dr. Maria Santos',
                            email: 'maria.santos@hospital.pt',
                            role: 'clinician',
                            interests: ['cardiology', 'sleep'],
                            institution: 'Lisbon University Hospital',
                            linkedin: 'https://linkedin.com/in/mariasantos',
                            appliedAt: new Date(Date.now() - 2 * 60 * 60 * 1000).toISOString(),
                            status: 'pending'
                        },
                        {
                            id: 'pending-2',
                            name: 'James Wilson',
                            email: 'j.wilson@mit.edu',
                            role: 'researcher',
                            interests: ['neuroscience', 'ai-ml'],
                            institution: 'MIT',
                            linkedin: '',
                            appliedAt: new Date(Date.now() - 5 * 60 * 60 * 1000).toISOString(),
                            status: 'pending'
                        },
                        {
                            id: 'pending-3',
                            name: 'Anna Kowalski',
                            email: 'anna.k@student.pl',
                            role: 'student',
                            interests: ['oncology', 'genomics'],
                            institution: 'Warsaw Medical University',
                            linkedin: 'https://linkedin.com/in/annakowalski',
                            appliedAt: new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString(),
                            status: 'pending'
                        }
                    ];
                    this.save();
                }
            },

            save() {
                localStorage.setItem('medx_pending_users', JSON.stringify(this.pendingUsers));
            },

            render() {
                const list = document.getElementById('pendingUsersList');
                const badge = document.getElementById('pendingApprovalsBadge');

                if (!list) return;

                const pending = this.pendingUsers.filter(u => u.status === 'pending');

                if (badge) {
                    badge.textContent = pending.length;
                    badge.style.display = pending.length > 0 ? 'inline' : 'none';
                }

                if (pending.length === 0) {
                    list.innerHTML = `
                        <div class="pending-user-empty" style="text-align: center; padding: 24px; color: var(--text-muted);">
                            <i class="fas fa-check-circle" style="font-size: 32px; color: var(--success); margin-bottom: 12px; display: block;"></i>
                            <p style="margin: 0;">No pending approvals</p>
                        </div>
                    `;
                    return;
                }

                list.innerHTML = pending.map(user => `
                    <div class="pending-user-card" data-user-id="${user.id}">
                        <div class="pending-user-avatar">${this.getInitials(user.name)}</div>
                        <div class="pending-user-info">
                            <div class="pending-user-name">${user.name}</div>
                            <div class="pending-user-email">${user.email}</div>
                            <div class="pending-user-meta">
                                <span class="pending-user-tag role"><i class="fas fa-user"></i> ${this.formatRole(user.role)}</span>
                                ${user.interests.slice(0, 2).map(i => `<span class="pending-user-tag interest"><i class="fas fa-tag"></i> ${this.formatInterest(i)}</span>`).join('')}
                                ${user.linkedin ? `<span class="pending-user-tag linkedin" onclick="window.open('${user.linkedin}', '_blank')"><i class="fab fa-linkedin"></i> LinkedIn</span>` : ''}
                            </div>
                            <div class="pending-user-date">Applied ${this.timeAgo(user.appliedAt)}</div>
                        </div>
                        <div class="pending-user-actions">
                            <button class="pending-user-btn approve" onclick="AdminApprovals.approve('${user.id}')">
                                <i class="fas fa-check"></i> Approve
                            </button>
                            <button class="pending-user-btn reject" onclick="AdminApprovals.reject('${user.id}')">
                                <i class="fas fa-times"></i> Reject
                            </button>
                        </div>
                    </div>
                `).join('');
            },

            approve(userId) {
                const user = this.pendingUsers.find(u => u.id === userId);
                if (!user) return;

                user.status = 'approved';
                user.approvedAt = new Date().toISOString();
                this.save();
                this.render();

                // Show success toast
                if (typeof App !== 'undefined' && App.showToast) {
                    App.showToast(`${user.name} has been approved`, 'success');
                }

                // In a real app, this would send a welcome email
            },

            reject(userId) {
                const user = this.pendingUsers.find(u => u.id === userId);
                if (!user) return;

                user.status = 'rejected';
                user.rejectedAt = new Date().toISOString();
                this.save();
                this.render();

                // Show toast
                if (typeof App !== 'undefined' && App.showToast) {
                    App.showToast(`Application from ${user.name} has been rejected`, 'info');
                }
            },

            addPendingUser(userData) {
                const newUser = {
                    id: 'pending-' + Date.now(),
                    ...userData,
                    appliedAt: new Date().toISOString(),
                    status: 'pending'
                };
                this.pendingUsers.push(newUser);
                this.save();
                this.render();
            },

            getInitials(name) {
                return name.split(' ').map(n => n[0]).join('').toUpperCase().slice(0, 2);
            },

            formatRole(role) {
                const roles = {
                    'student': 'Student',
                    'researcher': 'Researcher',
                    'clinician': 'Clinician',
                    'industry': 'Industry'
                };
                return roles[role] || role;
            },

            formatInterest(interest) {
                const interests = {
                    'neuroscience': 'Neuroscience',
                    'sleep': 'Sleep',
                    'oncology': 'Oncology',
                    'cardiology': 'Cardiology',
                    'immunology': 'Immunology',
                    'genomics': 'Genomics',
                    'ai-ml': 'AI/ML',
                    'public-health': 'Public Health'
                };
                return interests[interest] || interest;
            },

            timeAgo(dateStr) {
                const date = new Date(dateStr);
                const now = new Date();
                const diffMs = now - date;
                const diffHours = Math.floor(diffMs / (1000 * 60 * 60));
                const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));

                if (diffHours < 1) return 'just now';
                if (diffHours < 24) return diffHours + ' hours ago';
                if (diffDays === 1) return 'yesterday';
                return diffDays + ' days ago';
            }
        };

