        // Sparklines for Stats
        const Sparklines = {
            init() {
                // Add sparklines to stat cards on dashboard
                this.renderAll();
            },

            renderAll() {
                const statCards = document.querySelectorAll('.stat-card, .project-stat');
                statCards.forEach((card, index) => {
                    if (!card.querySelector('.stat-sparkline')) {
                        this.addSparkline(card, index);
                    }
                });
            },

            addSparkline(card, seed) {
                // Generate 7 days of trend data
                const data = this.generateTrendData(seed);
                const max = Math.max(...data);
                const min = Math.min(...data);
                const range = max - min || 1;

                const trend = data[6] > data[0] ? 'up' : data[6] < data[0] ? 'down' : 'neutral';
                const changePercent = data[0] !== 0 ? Math.round(((data[6] - data[0]) / data[0]) * 100) : 0;

                const sparklineHtml = '<div class="stat-sparkline">' +
                    data.map((val, i) => {
                        const height = ((val - min) / range) * 100;
                        const barClass = i === 6 ? trend : '';
                        return '<div class="sparkline-bar ' + barClass + '" style="height: ' + Math.max(height, 10) + '%" title="Day ' + (i + 1) + ': ' + val + '"></div>';
                    }).join('') +
                '</div>' +
                '<div class="stat-trend ' + trend + '">' +
                    '<i class="fas fa-arrow-' + (trend === 'up' ? 'up' : trend === 'down' ? 'down' : 'right') + '"></i> ' +
                    (trend === 'neutral' ? 'No change' : Math.abs(changePercent) + '% vs last week') +
                '</div>';

                // Find the right place to insert
                const valueEl = card.querySelector('.stat-value, .project-stat-value, h3');
                if (valueEl) {
                    valueEl.insertAdjacentHTML('afterend', sparklineHtml);
                }
            },

            generateTrendData(seed) {
                // Generate pseudo-random but consistent data based on seed
                const base = 50 + (seed * 17) % 100;
                return Array.from({length: 7}, (_, i) => {
                    return Math.max(1, base + Math.sin(seed + i) * 20 + (Math.random() - 0.5) * 10);
                }).map(Math.round);
            }
        };

