        // =========================================
        // PHASE 4: UI POLISH - MICRO-INTERACTIONS
        // =========================================
        const MicroInteractions = {
            init() {
                this.initRippleEffect();
                this.initCardLift();
                this.initIconBounce();
                this.initStaggerAnimation();
            },

            // Ripple effect on buttons
            initRippleEffect() {
                document.addEventListener('click', (e) => {
                    const btn = e.target.closest('.btn-ripple, button');
                    if (!btn || btn.classList.contains('no-ripple')) return;

                    const rect = btn.getBoundingClientRect();
                    const x = e.clientX - rect.left;
                    const y = e.clientY - rect.top;

                    const ripple = document.createElement('span');
                    ripple.className = 'ripple';
                    ripple.style.left = x + 'px';
                    ripple.style.top = y + 'px';

                    btn.style.position = 'relative';
                    btn.style.overflow = 'hidden';
                    btn.appendChild(ripple);

                    setTimeout(() => ripple.remove(), 600);
                });
            },

            // Add card lift class to cards
            initCardLift() {
                document.querySelectorAll('.hub-card, .up-card, .person-card, .activity-item').forEach(card => {
                    card.classList.add('card-lift');
                });
            },

            // Icon bounce on hover
            initIconBounce() {
                document.querySelectorAll('.hub-program-card, .px-quick-link, .post-event-card').forEach(el => {
                    el.classList.add('icon-bounce');
                });
            },

            // Stagger animation for lists
            initStaggerAnimation() {
                this._staggerObserver = new IntersectionObserver((entries) => {
                    entries.forEach(entry => {
                        if (entry.isIntersecting) {
                            entry.target.classList.add('fade-in-up');
                            this._staggerObserver.unobserve(entry.target);
                        }
                    });
                }, { threshold: 0.1 });

                document.querySelectorAll('.stagger-item').forEach(item => {
                    this._staggerObserver.observe(item);
                });
            },

            // Success animation
            showSuccess(element) {
                const check = document.createElement('span');
                check.className = 'success-check';
                check.innerHTML = '<i class="fas fa-check"></i>';
                element.appendChild(check);
                setTimeout(() => check.remove(), 2000);
            },

            // Shake animation for errors
            shake(element) {
                element.classList.add('shake');
                setTimeout(() => element.classList.remove('shake'), 400);
            },

            // Count up animation
            countUp(element, target, duration = 1000) {
                const start = 0;
                const startTime = performance.now();

                const update = (currentTime) => {
                    const elapsed = currentTime - startTime;
                    const progress = Math.min(elapsed / duration, 1);
                    const eased = 1 - Math.pow(1 - progress, 3); // Ease out cubic
                    const current = Math.floor(start + (target - start) * eased);
                    element.textContent = current.toLocaleString();

                    if (progress < 1) {
                        requestAnimationFrame(update);
                    }
                };

                requestAnimationFrame(update);
            }
        };

        // =========================================
        // PHASE 4: BUTTON UTILITIES
        // =========================================
        const ButtonEffects = {
            // Set button to loading state
            setLoading(button, loading = true) {
                if (loading) {
                    button.classList.add('btn-loading');
                    button.disabled = true;
                    button.dataset.originalText = button.innerHTML;
                } else {
                    button.classList.remove('btn-loading');
                    button.disabled = false;
                    if (button.dataset.originalText) {
                        button.innerHTML = button.dataset.originalText;
                    }
                }
            },

            // Show success state
            showSuccess(button, message = 'Success!') {
                const originalText = button.innerHTML;
                button.classList.add('btn-success-state');
                button.innerHTML = message;

                setTimeout(() => {
                    button.classList.remove('btn-success-state');
                    button.innerHTML = originalText;
                }, 2000);
            },

            // Show error state
            showError(button, message = 'Error') {
                const originalText = button.innerHTML;
                button.classList.add('btn-error-state');
                button.innerHTML = message;

                setTimeout(() => {
                    button.classList.remove('btn-error-state');
                    button.innerHTML = originalText;
                }, 2000);
            }
        };

        // =========================================
        // PHASE 4: TOAST NOTIFICATIONS
        // =========================================
        // Debounce utility
        function debounce(fn, delay) {
            let timer;
            return function(...args) {
                clearTimeout(timer);
                timer = setTimeout(() => fn.apply(this, args), delay);
            };
        }

        // Debounced search handlers
        const debouncedForumSearch = debounce(() => {
            if (typeof ForumPortal !== 'undefined') ForumPortal.filterMembersGrid();
        }, 300);
        const debouncedNetworkSearch = debounce(() => {
            if (typeof NetworkingPortal !== 'undefined') NetworkingPortal.filterMembers();
        }, 300);

        // =========================================
        // Inline field validation helpers
        function showFieldError(input, msg) {
            clearFieldError(input);
            const group = input.closest('.af-form-group, .fm-form-group, .form-group, .accel-form-group, div');
            if (group) {
                group.classList.add('field-error');
                const errEl = document.createElement('div');
                errEl.className = 'field-error-msg';
                errEl.innerHTML = '<i class="fas fa-exclamation-circle"></i> ' + msg;
                group.appendChild(errEl);
            }
            input.addEventListener('input', function handler() {
                clearFieldError(input);
                input.removeEventListener('input', handler);
            }, { once: true });
        }

        function clearFieldError(input) {
            const group = input.closest('.field-error');
            if (group) {
                group.classList.remove('field-error');
                const errMsg = group.querySelector('.field-error-msg');
                if (errMsg) errMsg.remove();
            }
        }

        function clearFormErrors(form) {
            if (!form) return;
            form.querySelectorAll('.field-error').forEach(g => g.classList.remove('field-error'));
            form.querySelectorAll('.field-error-msg').forEach(e => e.remove());
        }

        const Toast = {
            show(message, type = 'info', duration = 3000) {
                const container = document.getElementById('toastContainer');
                if (!container) return;

                const icons = {
                    success: 'fa-check-circle',
                    error: 'fa-exclamation-circle',
                    warning: 'fa-exclamation-triangle',
                    info: 'fa-info-circle'
                };

                const colors = {
                    success: '#2f6b3a',
                    error: '#ef4444',
                    warning: '#f59e0b',
                    info: 'var(--up-gold)'
                };

                const toast = document.createElement('div');
                toast.setAttribute('role', 'alert');
                toast.style.cssText = `
                    display: flex;
                    align-items: center;
                    gap: 12px;
                    padding: 14px 20px;
                    background: var(--bg-secondary);
                    border: 1px solid ${colors[type]};
                    border-radius: 10px;
                    box-shadow: 0 4px 16px rgba(0,0,0,0.3);
                    animation: fadeInUp 0.3s ease;
                    min-width: 280px;
                `;

                toast.innerHTML = `
                    <i class="fas ${icons[type]}" style="color: ${colors[type]}; font-size: 18px;"></i>
                    <span style="color: var(--text-primary); font-size: 14px;">${message}</span>
                    <button onclick="this.parentElement.remove()" style="background: none; border: none; color: var(--text-muted); cursor: pointer; margin-left: auto; padding: 4px;">
                        <i class="fas fa-times"></i>
                    </button>
                `;

                container.appendChild(toast);

                setTimeout(() => {
                    toast.style.animation = 'fadeOutDown 0.3s ease forwards';
                    setTimeout(() => toast.remove(), 300);
                }, duration);

                return toast;
            },

            success(message) { return this.show(message, 'success'); },
            error(message) { return this.show(message, 'error'); },
            warning(message) { return this.show(message, 'warning'); },
            info(message) { return this.show(message, 'info'); }
        };

        // =========================================
        // CHECKOUT FALLBACK PANEL
        // Frontend-only safety net. If a payment initiation call cannot open Stripe checkout
        // (a connection blip or a non-200), the user sees an elegant recovery panel — a retry,
        // an alternate route, and a direct way to reach us — instead of a dead error. This wraps
        // the existing payment calls and never touches the payment code paths themselves.
        // =========================================
        const MedXCheckoutFallback = {
            show(opts = {}) {
                const {
                    eventLabel = 'your reservation',
                    supportEmail = 'laura.rodman@medx.hr',
                    altUrl = '',
                    altLabel = '',
                    retry = null,
                    regId = ''
                } = opts;
                this.close();
                const subject = encodeURIComponent('Plexus 2026 payment — ' + eventLabel + (regId ? (' (ref ' + regId + ')') : ''));
                const mail = 'mailto:' + supportEmail + '?subject=' + subject;
                const overlay = document.createElement('div');
                overlay.id = 'mxCheckoutFallback';
                overlay.setAttribute('role', 'dialog');
                overlay.setAttribute('aria-modal', 'true');
                overlay.setAttribute('aria-label', 'Complete your payment');
                overlay.style.cssText = 'position:fixed;inset:0;z-index:100000;display:flex;align-items:center;justify-content:center;padding:20px;background:rgba(15,17,15,0.55);backdrop-filter:blur(4px);-webkit-backdrop-filter:blur(4px);';
                const btnPrimary = 'display:inline-flex;align-items:center;justify-content:center;gap:8px;width:100%;padding:14px 20px;border:none;border-radius:11px;background:var(--up-crimson,#9b1b22);color:#fff;font-size:14.5px;font-weight:600;font-family:inherit;cursor:pointer;text-decoration:none;transition:all .2s;';
                const btnGhost = 'display:inline-flex;align-items:center;justify-content:center;gap:8px;width:100%;padding:13px 20px;border:1px solid rgba(201,169,98,0.5);border-radius:11px;background:transparent;color:var(--up-text,#15110f);font-size:14px;font-weight:600;font-family:inherit;cursor:pointer;text-decoration:none;transition:all .2s;';
                overlay.innerHTML =
                    '<div style="position:relative;max-width:460px;width:100%;background:var(--up-bg,#fbf9f6);color:var(--up-text,#15110f);border:1px solid rgba(201,169,98,0.35);border-radius:18px;box-shadow:0 24px 60px rgba(0,0,0,0.35);padding:34px 30px;font-family:\'Inter\',-apple-system,BlinkMacSystemFont,system-ui,sans-serif;text-align:center;">' +
                        '<button id="mxcfClose" aria-label="Close" style="position:absolute;top:14px;right:16px;background:none;border:none;font-size:22px;line-height:1;color:var(--up-text-muted,#8a8178);cursor:pointer;padding:4px;">&times;</button>' +
                        '<div style="width:56px;height:56px;border-radius:50%;background:rgba(201,169,98,0.14);display:flex;align-items:center;justify-content:center;margin:0 auto 18px;">' +
                            '<i class="fas fa-shield-halved" style="font-size:22px;color:var(--up-gold,#c9a962);"></i>' +
                        '</div>' +
                        '<h3 style="font-family:\'Fraunces\',Georgia,serif;font-size:22px;font-weight:600;margin:0 0 10px;line-height:1.25;">We could not open secure checkout</h3>' +
                        '<p style="font-size:14.5px;line-height:1.65;color:var(--up-text-muted,#5c554e);margin:0 0 22px;">Your place is held. This is usually a brief connection issue. You can try again now, or reach us and we will send you a secure payment link for ' + escapeHtml(eventLabel) + '.</p>' +
                        '<div style="display:flex;flex-direction:column;gap:10px;">' +
                            (typeof retry === 'function' ? ('<button id="mxcfRetry" style="' + btnPrimary + '"><i class="fas fa-rotate-right"></i> Try again</button>') : '') +
                            (altUrl ? ('<a href="' + safeUrl(altUrl) + '" style="' + btnGhost + '">' + escapeHtml(altLabel || 'Open the registration page') + '</a>') : '') +
                        '</div>' +
                        '<div style="margin-top:18px;font-size:13px;color:var(--up-text-muted,#5c554e);">Or contact us at <a href="' + mail + '" style="color:var(--up-gold,#c9a962);font-weight:600;text-decoration:none;">' + escapeHtml(supportEmail) + '</a></div>' +
                    '</div>';
                document.body.appendChild(overlay);
                const close = () => this.close();
                overlay.addEventListener('click', (e) => { if (e.target === overlay) close(); });
                const cbtn = overlay.querySelector('#mxcfClose'); if (cbtn) cbtn.addEventListener('click', close);
                const rbtn = overlay.querySelector('#mxcfRetry');
                if (rbtn && typeof retry === 'function') {
                    rbtn.addEventListener('click', () => { close(); try { retry(); } catch (e) { console.error('checkout retry failed', e); } });
                }
                if (this._escHandler) document.removeEventListener('keydown', this._escHandler);
                this._escHandler = (e) => { if (e.key === 'Escape') close(); };
                document.addEventListener('keydown', this._escHandler);
                const focusBtn = overlay.querySelector('#mxcfRetry, #mxcfClose'); if (focusBtn) focusBtn.focus();
            },
            close() {
                const el = document.getElementById('mxCheckoutFallback');
                if (el) el.remove();
                if (this._escHandler) { document.removeEventListener('keydown', this._escHandler); this._escHandler = null; }
            }
        };
        window.MedXCheckoutFallback = MedXCheckoutFallback;

        // =========================================
        // PHASE 4: KEYBOARD NAVIGATION
        // =========================================
        const KeyboardNav = {
            commands: [
                { id: 'dashboard', title: 'Go to Dashboard', desc: 'Home', icon: 'fa-home', shortcut: 'G D', action: () => UserPortal.showSection('dashboard') },
                { id: 'plexus', title: 'Go to Plexus', desc: 'Conference', icon: 'fa-users', shortcut: 'G P', action: () => UserPortal.showSection('plexus') },
                { id: 'accelerator', title: 'Go to Accelerator', desc: 'Programs', icon: 'fa-rocket', shortcut: 'G A', action: () => UserPortal.showSection('accelerator') },
                { id: 'network', title: 'Go to Network', desc: 'Connections', icon: 'fa-network-wired', shortcut: 'G N', action: () => UserPortal.showSection('network') },
                { id: 'settings', title: 'Go to Settings', desc: 'Preferences', icon: 'fa-cog', shortcut: 'G S', action: () => UserPortal.showSection('settings') },
                { id: 'theme', title: 'Toggle Theme', desc: 'Dark/Light mode', icon: 'fa-moon', shortcut: 'T', action: () => UserPortal.toggleTheme() },
                { id: 'search', title: 'Search Members', desc: 'Find people', icon: 'fa-search', action: () => UserPortal.showSection('network') }
            ],
            selectedIndex: 0,
            isOpen: false,
            keySequence: '',
            keyTimer: null,

            init() {
                this.initCommandPalette();
                this.initKeyboardShortcuts();
                this.initModalEscape();
                this.initArrowNavigation();
            },

            initCommandPalette() {
                const palette = document.getElementById('userCmdPalette');
                const input = document.getElementById('userCmdInput');
                const results = document.getElementById('userCmdResults');

                if (!palette || !input) return;

                // Open with Cmd+K
                document.addEventListener('keydown', (e) => {
                    if ((e.metaKey || e.ctrlKey) && e.key === 'k') {
                        e.preventDefault();
                        this.togglePalette();
                    }
                });

                // Filter on input
                input.addEventListener('input', () => {
                    this.filterCommands(input.value);
                });

                // Keyboard navigation in palette
                input.addEventListener('keydown', (e) => {
                    if (e.key === 'ArrowDown') {
                        e.preventDefault();
                        this.selectNext();
                    } else if (e.key === 'ArrowUp') {
                        e.preventDefault();
                        this.selectPrev();
                    } else if (e.key === 'Enter') {
                        e.preventDefault();
                        this.executeSelected();
                    } else if (e.key === 'Escape') {
                        this.closePalette();
                    }
                });

                // Click to select
                results.addEventListener('click', (e) => {
                    const item = e.target.closest('.cmd-palette-item');
                    if (item) {
                        const index = Array.from(results.children).indexOf(item);
                        this.selectedIndex = index;
                        this.executeSelected();
                    }
                });

                // Initial render
                this.filterCommands('');
            },

            togglePalette() {
                const palette = document.getElementById('userCmdPalette');
                const input = document.getElementById('userCmdInput');

                if (this.isOpen) {
                    this.closePalette();
                } else {
                    palette.classList.add('active');
                    input.value = '';
                    input.focus();
                    this.filterCommands('');
                    this.isOpen = true;

                    // Close on click outside
                    setTimeout(() => {
                        document.addEventListener('click', this.handleOutsideClick);
                    }, 0);
                }
            },

            closePalette() {
                const palette = document.getElementById('userCmdPalette');
                palette.classList.remove('active');
                this.isOpen = false;
                document.removeEventListener('click', this.handleOutsideClick);
            },

            handleOutsideClick: function(e) {
                if (!e.target.closest('.cmd-palette')) {
                    KeyboardNav.closePalette();
                }
            },

            filterCommands(query) {
                const results = document.getElementById('userCmdResults');
                if (!results) return;

                const filtered = query
                    ? this.commands.filter(c =>
                        c.title.toLowerCase().includes(query.toLowerCase()) ||
                        c.desc.toLowerCase().includes(query.toLowerCase())
                    )
                    : this.commands;

                this.selectedIndex = 0;

                results.innerHTML = filtered.map((cmd, i) => `
                    <div class="cmd-palette-item ${i === 0 ? 'selected' : ''}" role="option" data-id="${cmd.id}">
                        <div class="cmd-palette-item-icon"><i class="fas ${cmd.icon}"></i></div>
                        <div class="cmd-palette-item-text">
                            <div class="cmd-palette-item-title">${cmd.title}</div>
                            <div class="cmd-palette-item-desc">${cmd.desc}</div>
                        </div>
                        ${cmd.shortcut ? `<kbd>${cmd.shortcut}</kbd>` : ''}
                    </div>
                `).join('');
            },

            selectNext() {
                const results = document.getElementById('userCmdResults');
                const items = results.querySelectorAll('.cmd-palette-item');
                if (items.length === 0) return;

                items[this.selectedIndex].classList.remove('selected');
                this.selectedIndex = (this.selectedIndex + 1) % items.length;
                items[this.selectedIndex].classList.add('selected');
                items[this.selectedIndex].scrollIntoView({ block: 'nearest' });
            },

            selectPrev() {
                const results = document.getElementById('userCmdResults');
                const items = results.querySelectorAll('.cmd-palette-item');
                if (items.length === 0) return;

                items[this.selectedIndex].classList.remove('selected');
                this.selectedIndex = (this.selectedIndex - 1 + items.length) % items.length;
                items[this.selectedIndex].classList.add('selected');
                items[this.selectedIndex].scrollIntoView({ block: 'nearest' });
            },

            executeSelected() {
                const results = document.getElementById('userCmdResults');
                const items = results.querySelectorAll('.cmd-palette-item');
                if (items.length === 0) return;

                const selectedId = items[this.selectedIndex].dataset.id;
                const command = this.commands.find(c => c.id === selectedId);
                if (command) {
                    this.closePalette();
                    command.action();
                }
            },

            initKeyboardShortcuts() {
                document.addEventListener('keydown', (e) => {
                    // Don't trigger if typing in input
                    if (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA') return;
                    if (this.isOpen) return;

                    // Build key sequence
                    clearTimeout(this.keyTimer);
                    this.keySequence += e.key.toUpperCase();
                    this.keyTimer = setTimeout(() => this.keySequence = '', 500);

                    // Check sequences
                    if (this.keySequence === 'GD') {
                        UserPortal.showSection('dashboard');
                        this.keySequence = '';
                    } else if (this.keySequence === 'GP') {
                        UserPortal.showSection('plexus');
                        this.keySequence = '';
                    } else if (this.keySequence === 'GA') {
                        UserPortal.showSection('accelerator');
                        this.keySequence = '';
                    } else if (this.keySequence === 'GN') {
                        UserPortal.showSection('network');
                        this.keySequence = '';
                    } else if (this.keySequence === 'GS') {
                        UserPortal.showSection('settings');
                        this.keySequence = '';
                    } else if (e.key === 't' || e.key === 'T') {
                        UserPortal.toggleTheme();
                        this.keySequence = '';
                    } else if (e.key === '?') {
                        this.togglePalette();
                        this.keySequence = '';
                    }
                });
            },

            initModalEscape() {
                document.addEventListener('keydown', (e) => {
                    if (e.key === 'Escape') {
                        // Close any open modal (active class pattern)
                        document.querySelectorAll('.modal-overlay.active, .connect-modal.active, .member-profile-panel.active').forEach(modal => {
                            modal.classList.remove('active');
                        });
                        document.querySelectorAll('.member-profile-backdrop.active').forEach(backdrop => {
                            backdrop.classList.remove('active');
                        });
                        // Close modals using display:flex/block pattern
                        document.querySelectorAll('.modal-overlay').forEach(modal => {
                            if (modal.style.display && modal.style.display !== 'none') {
                                modal.style.display = 'none';
                            }
                        });
                    }
                });
            },

            initArrowNavigation() {
                // Arrow navigation for lists
                document.addEventListener('keydown', (e) => {
                    if (!['ArrowUp', 'ArrowDown'].includes(e.key)) return;

                    const focusedList = document.activeElement.closest('[role="listbox"], .people-grid, .activity-feed');
                    if (!focusedList) return;

                    const items = focusedList.querySelectorAll('[role="option"], .person-card, .activity-item');
                    const currentIndex = Array.from(items).indexOf(document.activeElement);

                    if (e.key === 'ArrowDown' && currentIndex < items.length - 1) {
                        e.preventDefault();
                        items[currentIndex + 1].focus();
                    } else if (e.key === 'ArrowUp' && currentIndex > 0) {
                        e.preventDefault();
                        items[currentIndex - 1].focus();
                    }
                });
            }
        };

        // =========================================
        // PHASE 4: ACCESSIBILITY HELPERS
        // =========================================
        const A11y = {
            init() {
                this.addAriaLabels();
                this.initFocusTrap();
                this.announcePageChanges();
            },

            addAriaLabels() {
                // Add labels to icon-only buttons
                document.querySelectorAll('button:not([aria-label])').forEach(btn => {
                    if (btn.textContent.trim() === '' && btn.querySelector('i')) {
                        const iconClass = btn.querySelector('i').className;
                        let label = 'Button';
                        if (iconClass.includes('fa-times')) label = 'Close';
                        if (iconClass.includes('fa-plus')) label = 'Add';
                        if (iconClass.includes('fa-edit')) label = 'Edit';
                        if (iconClass.includes('fa-trash')) label = 'Delete';
                        if (iconClass.includes('fa-search')) label = 'Search';
                        if (iconClass.includes('fa-cog')) label = 'Settings';
                        if (iconClass.includes('fa-bell')) label = 'Notifications';
                        btn.setAttribute('aria-label', label);
                    }
                });

                // Add roles to interactive elements
                document.querySelectorAll('.person-card, .activity-item, .session-card').forEach(el => {
                    el.setAttribute('role', 'button');
                    el.setAttribute('tabindex', '0');
                });
            },

            initFocusTrap() {
                // Trap focus in modals
                document.addEventListener('keydown', (e) => {
                    if (e.key !== 'Tab') return;

                    const modal = document.querySelector('.modal-overlay.active, .connect-modal.active, .member-profile-panel.active, .cmd-palette.active');
                    if (!modal) return;

                    const focusable = modal.querySelectorAll('button, input, select, textarea, a[href], [tabindex]:not([tabindex="-1"])');
                    const first = focusable[0];
                    const last = focusable[focusable.length - 1];

                    if (e.shiftKey && document.activeElement === first) {
                        e.preventDefault();
                        last.focus();
                    } else if (!e.shiftKey && document.activeElement === last) {
                        e.preventDefault();
                        first.focus();
                    }
                });
            },

            announcePageChanges() {
                // Create live region for announcements
                const liveRegion = document.createElement('div');
                liveRegion.setAttribute('role', 'status');
                liveRegion.setAttribute('aria-live', 'polite');
                liveRegion.className = 'sr-only';
                liveRegion.id = 'a11yAnnouncer';
                document.body.appendChild(liveRegion);
            },

            announce(message) {
                const announcer = document.getElementById('a11yAnnouncer');
                if (announcer) {
                    announcer.textContent = message;
                    setTimeout(() => announcer.textContent = '', 1000);
                }
            }
        };

        // =========================================
        // PHASE 4: INITIALIZE ALL FEATURES
        // =========================================
        const initPhase4 = () => {
            MicroInteractions.init();
            KeyboardNav.init();
            A11y.init();
        };

        // Initialize when DOM is ready
        if (document.readyState === 'loading') {
            document.addEventListener('DOMContentLoaded', initPhase4);
        } else {
            initPhase4();
        }

        // Hook into UserPortal for page change announcements
        const originalShowSectionA11y = UserPortal.showSection;
        // First-party analytics beacon for in-portal navigation (aggregate-only, no cookies/PII).
        // Mirrors the marketing site's beacon: respects Do-Not-Track / Global Privacy Control and
        // best-effort fires once per showSection to the same public endpoint (same origin here, so a
        // relative path). Path is namespaced '/portal/<section>' so portal views never collide with
        // the marketing site's paths in the shared page_views table.
        UserPortal._pvBeacon = function(path) {
            try {
                var dnt = navigator.doNotTrack || window.doNotTrack || navigator.msDoNotTrack;
                if (dnt === '1' || dnt === 'yes' || navigator.globalPrivacyControl === true) return;
                var payload = JSON.stringify({ path: path, ref: '' });
                var url = '/api/public/pv';
                var sent = false;
                if (navigator.sendBeacon) { try { sent = navigator.sendBeacon(url, new Blob([payload], { type: 'text/plain' })); } catch (e) {} }
                if (!sent) { fetch(url, { method: 'POST', body: payload, headers: { 'Content-Type': 'text/plain' }, keepalive: true }).catch(function () {}); }
            } catch (e) {}
        };

        UserPortal.showSection = function(section, addToHistory = true) {
            originalShowSectionA11y.call(this, section, addToHistory);
            try {
                A11y.announce(`Navigated to ${this.sectionTitles[section] || section}`);
            } catch (e) {
                console.error('A11y announce error:', e);
            }
            try { UserPortal._pvBeacon('/portal/' + section); } catch (e) {}
            // Defect 2: refresh the Forum wing CTA when the Biomedical Forum section is opened in-session.
            try { if (section === 'forum' && window.mxRefreshForumEntrance) window.mxRefreshForumEntrance(); } catch (e) {}
        };


        // =========================================
        // PHASE 3: EVENT CALENDAR INTEGRATION
        // =========================================
        const EventCalendar = {
            event: {
                title: 'Plexus Conference 2026',
                description: 'Premier biomedical conference with 2,500+ professionals from 30+ countries. Join us for cutting-edge research, biomedical leaders, and world-class networking.',
                location: 'Zagreb, Croatia',
                startDate: '2026-12-04T08:00:00',
                endDate: '2026-12-05T18:00:00',
                url: 'https://plexus.medx.hr'
            },

            toggleDropdown() {
                const dropdown = document.getElementById('calendarDropdown');
                if (dropdown) {
                    dropdown.classList.toggle('active');
                }

                // Close when clicking outside
                const closeHandler = (e) => {
                    if (!e.target.closest('.calendar-dropdown')) {
                        dropdown.classList.remove('active');
                        document.removeEventListener('click', closeHandler);
                    }
                };
                setTimeout(() => document.addEventListener('click', closeHandler), 0);
            },

            addTo(type) {
                const e = this.event;
                const start = e.startDate.replace(/[-:]/g, '').replace('T', 'T');
                const end = e.endDate.replace(/[-:]/g, '').replace('T', 'T');

                switch(type) {
                    case 'google':
                        const googleUrl = `https://calendar.google.com/calendar/render?action=TEMPLATE&text=${encodeURIComponent(e.title)}&dates=${start}/${end}&details=${encodeURIComponent(e.description)}&location=${encodeURIComponent(e.location)}&sf=true`;
                        window.open(googleUrl, '_blank');
                        break;

                    case 'outlook':
                        const outlookUrl = `https://outlook.live.com/calendar/0/deeplink/compose?subject=${encodeURIComponent(e.title)}&startdt=${e.startDate}&enddt=${e.endDate}&body=${encodeURIComponent(e.description)}&location=${encodeURIComponent(e.location)}`;
                        window.open(outlookUrl, '_blank');
                        break;

                    case 'apple':
                    case 'ics':
                        this.downloadICS();
                        break;
                }

                this.showToast('Event added to calendar!');
                document.getElementById('calendarDropdown').classList.remove('active');
            },

            downloadICS() {
                const e = this.event;
                const formatDate = (dateStr) => {
                    return dateStr.replace(/[-:]/g, '').replace('T', 'T') + '00';
                };

                const icsContent = [
                    'BEGIN:VCALENDAR',
                    'VERSION:2.0',
                    'PRODID:-//MedX//Plexus Conference//EN',
                    'BEGIN:VEVENT',
                    `DTSTART:${formatDate(e.startDate)}`,
                    `DTEND:${formatDate(e.endDate)}`,
                    `SUMMARY:${e.title}`,
                    `DESCRIPTION:${e.description.replace(/\n/g, '\\n')}`,
                    `LOCATION:${e.location}`,
                    `URL:${e.url}`,
                    'END:VEVENT',
                    'END:VCALENDAR'
                ].join('\r\n');

                const blob = new Blob([icsContent], { type: 'text/calendar;charset=utf-8' });
                const link = document.createElement('a');
                link.href = URL.createObjectURL(blob);
                link.download = 'plexus-2026.ics';
                link.click();
            },

            addSessionToCalendar(session) {
                const icsContent = [
                    'BEGIN:VCALENDAR',
                    'VERSION:2.0',
                    'PRODID:-//MedX//Plexus Conference//EN',
                    'BEGIN:VEVENT',
                    `DTSTART:${session.start}`,
                    `DTEND:${session.end}`,
                    `SUMMARY:${session.title}`,
                    `DESCRIPTION:${session.speaker || ''} - ${session.description || ''}`,
                    `LOCATION:${session.room || 'Plexus Conference'}`,
                    'END:VEVENT',
                    'END:VCALENDAR'
                ].join('\r\n');

                const blob = new Blob([icsContent], { type: 'text/calendar;charset=utf-8' });
                const link = document.createElement('a');
                link.href = URL.createObjectURL(blob);
                link.download = `session-${session.id}.ics`;
                link.click();
            },

            showToast(message) {
                message = (window.mxLocalizeToast ? window.mxLocalizeToast(message) : message);
                if (typeof ConnectionSystem !== 'undefined') {
                    ConnectionSystem.showToast(message);
                } else {
                    Toast.info(message);
                }
            }
        };

