        // =========================================
        const SessionBookmarks = {
            bookmarks: [],
            sessions: [
                { id: 's1', title: 'Opening Ceremony & Welcome', speaker: 'Dr. Alen Juginovic', date: '2026-12-04', time: '09:00', duration: 30, room: 'Main Hall', track: 'plenary' },
                { id: 's2', title: 'Keynote: The Future of Precision Medicine', speaker: 'Dr. Richard Henderson', date: '2026-12-04', time: '09:30', duration: 90, room: 'Main Hall', track: 'plenary' },
                { id: 's3', title: 'Sleep and Cancer: New Insights', speaker: 'Dr. Dragana Rogulja', date: '2026-12-04', time: '11:30', duration: 45, room: 'Room A', track: 'neuroscience' },
                { id: 's4', title: 'AI in Radiology: Current State', speaker: 'Dr. Michael Torres', date: '2026-12-04', time: '11:30', duration: 45, room: 'Room B', track: 'ai' },
                { id: 's5', title: 'CAR-T Cell Therapy Workshop', speaker: 'Dr. Sarah Chen', date: '2026-12-04', time: '14:00', duration: 120, room: 'Workshop Room', track: 'oncology' },
                { id: 's6', title: 'Gala Evening & Awards Ceremony', speaker: '', date: '2026-12-05', time: '19:00', duration: 180, room: 'Grand Ballroom, Hotel Esplanade', track: 'social' }
            ],

            init() {
                this.load();
            },

            load() {
                const saved = localStorage.getItem('medx_session_bookmarks');
                if (saved) {
                    this.bookmarks = JSON.parse(saved);
                }
            },

            save() {
                localStorage.setItem('medx_session_bookmarks', JSON.stringify(this.bookmarks));
            },

            async toggle(sessionId) {
                const idx = this.bookmarks.indexOf(sessionId);
                if (idx > -1) {
                    this.bookmarks.splice(idx, 1);
                } else {
                    // Check for conflicts
                    const session = this.sessions.find(s => s.id === sessionId);
                    const conflict = this.checkConflict(session);
                    if (conflict) {
                        try {
                            await ConfirmationModal.show({
                                type: 'warning',
                                title: 'Schedule Conflict',
                                message: `This session conflicts with "${conflict.title}". Add anyway?`,
                                item: conflict.title,
                                confirmText: 'Add Anyway',
                                cancelText: 'Cancel'
                            });
                        } catch (e) { return; }
                    }
                    this.bookmarks.push(sessionId);
                }
                this.save();
                this.renderMySchedule();

                // Award achievement for first bookmark
                if (this.bookmarks.length === 1 && typeof Achievements !== 'undefined') {
                    Achievements.unlock('schedule-builder');
                }
            },

            isBookmarked(sessionId) {
                return this.bookmarks.includes(sessionId);
            },

            checkConflict(newSession) {
                if (!newSession) return null;

                const newStart = this.timeToMinutes(newSession.time);
                const newEnd = newStart + newSession.duration;

                for (const bookmarkId of this.bookmarks) {
                    const session = this.sessions.find(s => s.id === bookmarkId);
                    if (session && session.date === newSession.date && session.id !== newSession.id) {
                        const start = this.timeToMinutes(session.time);
                        const end = start + session.duration;

                        if ((newStart >= start && newStart < end) || (newEnd > start && newEnd <= end)) {
                            return session;
                        }
                    }
                }
                return null;
            },

            timeToMinutes(time) {
                const [h, m] = time.split(':').map(Number);
                return h * 60 + m;
            },

            getBookmarkedSessions() {
                return this.bookmarks.map(id => this.sessions.find(s => s.id === id)).filter(Boolean);
            },

            renderMySchedule() {
                const container = document.getElementById('myScheduleSessions');
                const emptyState = document.getElementById('myScheduleEmpty');

                if (!container) return;

                const sessions = this.getBookmarkedSessions();

                if (sessions.length === 0) {
                    container.style.display = 'none';
                    if (emptyState) emptyState.style.display = 'block';
                    return;
                }

                container.style.display = 'flex';
                if (emptyState) emptyState.style.display = 'none';

                // Group by date
                const byDate = {};
                sessions.forEach(s => {
                    if (!byDate[s.date]) byDate[s.date] = [];
                    byDate[s.date].push(s);
                });

                container.innerHTML = Object.entries(byDate).map(([date, daySessions]) => `
                    <div style="margin-bottom: 16px;">
                        <div style="font-size: 12px; font-weight: 600; color: var(--up-gold); margin-bottom: 8px;">
                            ${new Date(date).toLocaleDateString('en-US', { weekday: 'long', month: 'short', day: 'numeric' })}
                        </div>
                        ${daySessions.sort((a,b) => a.time.localeCompare(b.time)).map(session => `
                            <div class="timeline-session">
                                <div class="timeline-session-title">${session.title}</div>
                                <div class="timeline-session-time">
                                    <i class="fas fa-clock"></i> ${session.time} · ${session.room}
                                    ${session.speaker ? ` · ${session.speaker}` : ''}
                                </div>
                            </div>
                        `).join('')}
                    </div>
                `).join('');
            }
        };

