        // =========================================
        // ADMIN SCHEDULE EDITOR
        // =========================================
        const AdminScheduleEditor = {
            async editSession(id) {
                const session = ConferenceData.getSessionById(id);
                if (!session) return;

                const title = await InputModal.show({ title: 'Edit Session', message: 'Session title:', defaultValue: session.title, confirmText: 'Next' });
                if (title === null) return;

                const day = await InputModal.show({ title: 'Day (1 or 2)', defaultValue: String(session.day), confirmText: 'Next' });
                if (day === null) return;

                const time = await InputModal.show({ title: 'Start Time (HH:MM)', defaultValue: session.time, confirmText: 'Next' });
                if (time === null) return;

                const endTime = await InputModal.show({ title: 'End Time (HH:MM)', defaultValue: session.endTime || '', confirmText: 'Next' });
                if (endTime === null) return;

                const room = await InputModal.show({ title: 'Room', defaultValue: session.room, confirmText: 'Next' });
                if (room === null) return;

                const speaker = await InputModal.show({ title: 'Speaker', defaultValue: session.speaker || '', confirmText: 'Next' });
                if (speaker === null) return;

                const price = await InputModal.show({ title: 'Price (0 = included)', defaultValue: String(session.price || 0), confirmText: 'Save' });
                if (price === null) return;

                ConferenceData.updateSession(id, { title, day: parseInt(day), time, endTime, room, speaker, price: parseFloat(price) || 0 });
                if (typeof App !== 'undefined') App.loadPlexusSchedule();
                Toast.success('Session updated');
            },

            async deleteSession(id) {
                if (!(await mxConfirm({ destructive: true, title: 'Delete session', message: 'Delete this session? This action cannot be undone.', confirmText: 'Delete' }))) return;
                ConferenceData.deleteSession(id);
                if (typeof App !== 'undefined') App.loadPlexusSchedule();
                Toast.success('Session deleted');
            }
        };

        // =========================================
        // ADMIN SPEAKER EDITOR
        // =========================================
        const AdminSpeakerEditor = {
            async editSpeaker(id) {
                const speaker = ConferenceData.getSpeakerById(id);
                if (!speaker) return;

                const name = await InputModal.show({ title: 'Edit Speaker', message: 'Full name:', defaultValue: speaker.name, confirmText: 'Next' });
                if (name === null) return;

                const title = await InputModal.show({ title: 'Title/Role', defaultValue: speaker.title, confirmText: 'Next' });
                if (title === null) return;

                const institution = await InputModal.show({ title: 'Institution', defaultValue: speaker.institution, confirmText: 'Next' });
                if (institution === null) return;

                const bio = await InputModal.show({ title: 'Bio', defaultValue: speaker.bio, confirmText: 'Next' });
                if (bio === null) return;

                const avatar = await InputModal.show({ title: 'Avatar URL', defaultValue: speaker.avatar, confirmText: 'Next' });
                if (avatar === null) return;

                const tags = await InputModal.show({ title: 'Tags (comma-separated)', defaultValue: (speaker.tags || []).join(', '), confirmText: 'Next' });
                if (tags === null) return;

                const isNobel = await InputModal.show({ title: 'Keynote Speaker? (yes/no)', defaultValue: speaker.isNobel ? 'yes' : 'no', confirmText: 'Save' });
                if (isNobel === null) return;

                ConferenceData.updateSpeaker(id, {
                    name, title, institution, bio, avatar,
                    tags: tags.split(',').map(t => t.trim()).filter(Boolean),
                    isNobel: isNobel.toLowerCase() === 'yes'
                });
                if (typeof App !== 'undefined') App.loadPlexusSpeakers();
                Toast.success('Speaker updated');
            },

            async deleteSpeaker(id) {
                if (!(await mxConfirm({ destructive: true, title: 'Delete speaker', message: 'Delete this speaker? This action cannot be undone.', confirmText: 'Delete' }))) return;
                ConferenceData.deleteSpeaker(id);
                if (typeof App !== 'undefined') App.loadPlexusSpeakers();
                Toast.success('Speaker deleted');
            }
        };

        // =========================================
        // ADMIN PRICING EDITOR
        // =========================================
        const AdminPricingEditor = {
            render() {
                this.renderTiers();
                this.renderAddons();
            },

            renderTiers() {
                const container = document.getElementById('adminPricingTiersTable');
                if (!container) return;

                let html = '<table class="data-table" style="width: 100%;"><thead><tr><th>ID</th><th>Name</th><th>Price (EUR)</th><th>Deadline</th><th>Badge</th><th>Actions</th></tr></thead><tbody>';
                ConferenceData.pricing.tiers.forEach((t, i) => {
                    html += `<tr>
                        <td><input type="text" value="${t.id}" data-tier-idx="${i}" data-field="id" class="admin-pricing-input" style="width: 130px;"></td>
                        <td><input type="text" value="${t.name}" data-tier-idx="${i}" data-field="name" class="admin-pricing-input"></td>
                        <td><input type="number" value="${t.price}" data-tier-idx="${i}" data-field="price" class="admin-pricing-input" style="width: 80px;"></td>
                        <td><input type="date" value="${t.deadline}" data-tier-idx="${i}" data-field="deadline" class="admin-pricing-input"></td>
                        <td><input type="text" value="${t.badge || ''}" data-tier-idx="${i}" data-field="badge" class="admin-pricing-input" style="width: 100px;"></td>
                        <td><button class="btn btn-sm btn-danger" onclick="AdminPricingEditor.deleteTier(${i})"><i class="fas fa-trash"></i></button></td>
                    </tr>`;
                });
                html += '</tbody></table>';
                html += '<button class="btn btn-sm" style="margin-top: 8px;" onclick="AdminPricingEditor.addTier()"><i class="fas fa-plus"></i> Add Tier</button>';
                container.innerHTML = html;
            },

            renderAddons() {
                const container = document.getElementById('adminPricingAddonsTable');
                if (!container) return;

                let html = '<table class="data-table" style="width: 100%;"><thead><tr><th>ID</th><th>Name</th><th>Price (EUR)</th><th>Description</th><th>Enabled</th><th>Actions</th></tr></thead><tbody>';
                ConferenceData.pricing.addons.forEach((a, i) => {
                    html += `<tr>
                        <td><input type="text" value="${a.id}" data-addon-idx="${i}" data-field="id" class="admin-pricing-input" style="width: 100px;"></td>
                        <td><input type="text" value="${a.name}" data-addon-idx="${i}" data-field="name" class="admin-pricing-input"></td>
                        <td><input type="number" value="${a.price}" data-addon-idx="${i}" data-field="price" class="admin-pricing-input" style="width: 80px;"></td>
                        <td><input type="text" value="${a.description}" data-addon-idx="${i}" data-field="description" class="admin-pricing-input"></td>
                        <td><input type="checkbox" ${a.enabled ? 'checked' : ''} data-addon-idx="${i}" data-field="enabled"></td>
                        <td><button class="btn btn-sm btn-danger" onclick="AdminPricingEditor.deleteAddon(${i})"><i class="fas fa-trash"></i></button></td>
                    </tr>`;
                });
                html += '</tbody></table>';
                html += '<button class="btn btn-sm" style="margin-top: 8px;" onclick="AdminPricingEditor.addAddon()"><i class="fas fa-plus"></i> Add Add-On</button>';
                container.innerHTML = html;
            },

            save() {
                // Collect tier data from inputs
                const tiers = [];
                document.querySelectorAll('[data-tier-idx]').forEach(input => {
                    const idx = parseInt(input.dataset.tierIdx);
                    if (!tiers[idx]) tiers[idx] = { ...ConferenceData.pricing.tiers[idx] };
                    const field = input.dataset.field;
                    if (field === 'price') tiers[idx][field] = parseFloat(input.value) || 0;
                    else tiers[idx][field] = input.value;
                });

                const addons = [];
                document.querySelectorAll('[data-addon-idx]').forEach(input => {
                    const idx = parseInt(input.dataset.addonIdx);
                    if (!addons[idx]) addons[idx] = { ...ConferenceData.pricing.addons[idx] };
                    const field = input.dataset.field;
                    if (field === 'price') addons[idx][field] = parseFloat(input.value) || 0;
                    else if (field === 'enabled') addons[idx][field] = input.checked;
                    else addons[idx][field] = input.value;
                });

                ConferenceData.updatePricing({ earlyBirdCutoff: ConferenceData.pricing.earlyBirdCutoff || '2026-09-30', tiers: tiers.filter(Boolean), addons: addons.filter(Boolean) });
                Toast.success('Pricing saved successfully');
            },

            addTier() {
                ConferenceData.pricing.tiers.push({ id: 'new-' + Date.now(), type: 'student', name: 'New Tier', price: 0, deadline: '2026-12-03', badge: '', featured: false });
                ConferenceData.save();
                this.renderTiers();
            },

            deleteTier(idx) {
                ConferenceData.pricing.tiers.splice(idx, 1);
                ConferenceData.save();
                this.renderTiers();
            },

            addAddon() {
                ConferenceData.pricing.addons.push({ id: 'addon-' + Date.now(), name: 'New Add-On', price: 0, description: '', enabled: true, category: 'extras' });
                ConferenceData.save();
                this.renderAddons();
            },

            deleteAddon(idx) {
                ConferenceData.pricing.addons.splice(idx, 1);
                ConferenceData.save();
                this.renderAddons();
            }
        };

        // =========================================
        // ADMIN ZAGREB GUIDE EDITOR
        // =========================================
        const AdminZagrebEditor = {
            render() {
                const container = document.getElementById('adminZagrebGrid');
                if (!container) return;

                if (ConferenceData.exploreZagreb.length === 0) {
                    container.innerHTML = `<div class="table-empty" style="grid-column: 1/-1;"><i class="fas fa-city"></i><p>No items yet</p>
                        <button class="btn btn-primary" style="margin-top: 12px;" onclick="AdminZagrebEditor.openModal()"><i class="fas fa-plus"></i> Add Item</button></div>`;
                    return;
                }

                container.innerHTML = ConferenceData.exploreZagreb.map(item => `
                    <div class="speaker-card" style="position: relative; text-align: center;">
                        <img src="${item.imageUrl}" alt="${item.title}" style="width: 100%; height: 100px; object-fit: cover; border-radius: 8px; margin-bottom: 8px;">
                        <div class="speaker-name">${item.title}</div>
                        <div class="speaker-org" style="font-size: 12px; color: var(--text-secondary);">${item.category || ''}</div>
                        <div style="display: flex; gap: 4px; justify-content: center; margin-top: 8px;">
                            <button class="btn btn-sm" onclick="AdminZagrebEditor.editItem('${item.id}')" title="Edit"><i class="fas fa-edit"></i></button>
                            <button class="btn btn-sm btn-danger" onclick="AdminZagrebEditor.deleteItem('${item.id}')" title="Delete"><i class="fas fa-trash"></i></button>
                        </div>
                    </div>
                `).join('');
            },

            async openModal(existingId) {
                const existing = existingId ? ConferenceData.getZagrebItemById(existingId) : null;

                const title = await InputModal.show({ title: existing ? 'Edit Item' : 'New Zagreb Item', message: 'Title:', defaultValue: existing?.title || '', confirmText: 'Next' });
                if (title === null) return;

                const description = await InputModal.show({ title: 'Description', defaultValue: existing?.description || '', confirmText: 'Next' });
                if (description === null) return;

                const imageUrl = await InputModal.show({ title: 'Image URL', defaultValue: existing?.imageUrl || '', confirmText: 'Next' });
                if (imageUrl === null) return;

                const category = await InputModal.show({ title: 'Category', defaultValue: existing?.category || '', confirmText: 'Next' });
                if (category === null) return;

                const metaText1 = await InputModal.show({ title: 'Location/Meta 1', defaultValue: existing?.metaText1 || '', confirmText: 'Next' });
                if (metaText1 === null) return;

                const metaText2 = await InputModal.show({ title: 'Time/Meta 2', defaultValue: existing?.metaText2 || '', confirmText: 'Save' });
                if (metaText2 === null) return;

                const data = { title, description, imageUrl, category, metaIcon1: 'fas fa-map-marker-alt', metaText1, metaIcon2: 'fas fa-clock', metaText2 };

                if (existing) {
                    ConferenceData.updateZagrebItem(existingId, data);
                } else {
                    ConferenceData.addZagrebItem(data);
                }
                this.render();
                Toast.success(existing ? 'Item updated' : 'Item added');
            },

            editItem(id) { this.openModal(id); },

            async deleteItem(id) {
                if (!(await mxConfirm({ destructive: true, title: 'Delete item', message: 'Delete this item? This action cannot be undone.', confirmText: 'Delete' }))) return;
                ConferenceData.deleteZagrebItem(id);
                this.render();
                Toast.success('Item deleted');
            }
        };

        // =========================================
        // SHARED DATA - Admin-User Sync System
        // =========================================
        const SharedData = {
            news: [],
            featured: [],
            announcements: [],
            pendingUsers: [],
            events: [],
            _dynamicLoaded: false,

            // Default/fallback news (generic + true; real items load from /api/portal-content/published).
            // No fabricated people, partnerships, or dates.
            _defaultNews: [
                {
                    id: 'news-001',
                    title: 'Plexus 2026 registration is open',
                    description: 'Join researchers and clinicians from around the world in Zagreb this December for the flagship Med&X conference.',
                    type: 'announcement',
                    link: 'plexus',
                    featured: true,
                    unread: false,
                    createdAt: new Date(Date.now() - 2 * 60 * 60 * 1000).toISOString()
                },
                {
                    id: 'news-002',
                    title: 'Med&X Accelerator — applications open',
                    description: 'Apply for a research placement at a leading institution through the Med&X Accelerator program.',
                    type: 'program',
                    link: 'accelerator',
                    featured: false,
                    unread: false,
                    createdAt: new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString()
                }
            ],

            init() {
                this.load();
                // Initialize with default news if empty (before dynamic content loads)
                if (this.news.length === 0) {
                    this.news = [...this._defaultNews];
                    this.save();
                }
                // Fetch dynamic content from API in the background
                this.fetchDynamicContent();
            },

            async fetchDynamicContent() {
                try {
                    const res = await fetch('/api/portal-content/published');
                    if (!res.ok) return;
                    const items = await res.json();
                    if (!Array.isArray(items) || items.length === 0) return;

                    // Convert portal_content items to news format
                    const newsItems = items.filter(i => i.section === 'news').map(i => ({
                        id: 'pc-' + i.id,
                        title: i.title || '',
                        description: i.content || '',
                        type: this._mapProjectToType(i.project),
                        link: i.link || i.project || '',
                        featured: false,
                        unread: true,
                        createdAt: i.created_at || new Date().toISOString(),
                        _fromApi: true
                    }));

                    // Store featured and hero items for other widgets
                    this.featured = items.filter(i => i.section === 'featured').map(i => ({
                        id: 'pc-' + i.id,
                        title: i.title || '',
                        description: i.content || '',
                        image_url: i.image_url,
                        link: i.link || '',
                        project: i.project || '',
                        createdAt: i.created_at
                    }));

                    if (newsItems.length > 0) {
                        // Merge: API news first, then existing non-API news
                        const existingLocal = this.news.filter(n => !n._fromApi);
                        this.news = [...newsItems, ...existingLocal];
                        this.save();
                    }

                    this._dynamicLoaded = true;

                    // Re-render news widget if it exists
                    if (typeof NewsWidget !== 'undefined') {
                        NewsWidget.render();
                        NewsWidget.renderCompact();
                    }
                } catch (err) {
                    // Silently fail - fallback to static/localStorage content
                    console.log('[PortalContent] API not available, using fallback content');
                }
            },

            _mapProjectToType(project) {
                const map = { plexus: 'announcement', accelerator: 'program', forum: 'event', bridges: 'update' };
                return map[project] || 'announcement';
            },

            save() {
                localStorage.setItem('medx_shared_data', JSON.stringify({
                    news: this.news,
                    featured: this.featured,
                    announcements: this.announcements,
                    pendingUsers: this.pendingUsers,
                    events: this.events,
                    lastUpdated: new Date().toISOString()
                }));
            },

            load() {
                const data = safeJsonParse(localStorage.getItem('medx_shared_data'), {});
                this.news = data.news || [];
                this.featured = data.featured || [];
                this.announcements = data.announcements || [];
                this.pendingUsers = data.pendingUsers || [];
                this.events = data.events || [];
            },

            // Admin actions
            pushNews(item) {
                item.id = 'news-' + Date.now();
                item.createdAt = new Date().toISOString();
                item.unread = true;
                this.news.unshift(item);
                this.save();
            },

            deleteNews(id) {
                this.news = this.news.filter(n => n.id !== id);
                this.save();
            },

            markNewsRead(id) {
                const item = this.news.find(n => n.id === id);
                if (item) {
                    item.unread = false;
                    this.save();
                }
            },

            getUnreadCount() {
                return this.news.filter(n => n.unread).length;
            }
        };

        // =========================================
        // NEWS WIDGET - Dashboard News Display
        // =========================================
        const NewsWidget = {
            maxItems: 4,

            init() {
                SharedData.init();
                this.render();
                this.renderCompact();
            },

            render() {
                const container = document.getElementById('newsList');
                const badge = document.getElementById('newsBadge');
                if (!container) return;

                const news = SharedData.news.slice(0, this.maxItems);
                const unreadCount = SharedData.getUnreadCount();

                // Update badge
                if (badge) {
                    if (unreadCount > 0) {
                        badge.textContent = `${unreadCount} New`;
                        badge.style.display = '';
                    } else {
                        badge.style.display = 'none';
                    }
                }

                if (news.length === 0) {
                    container.innerHTML = `
                        <div class="medx-news-empty">
                            <i class="fas fa-newspaper"></i>
                            <p><span data-i18n="feed.noNewsSoon">No news yet. Check back soon!</span></p>
                        </div>
                    `;
                    return;
                }

                container.innerHTML = news.map(item => `
                    <div class="medx-news-item ${item.unread ? 'unread' : ''}" onclick="NewsWidget.openNews('${item.id}', '${item.link}')">
                        <div class="medx-news-icon ${item.type}">
                            <i class="fas fa-${this.getIcon(item.type)}"></i>
                        </div>
                        <div class="medx-news-content">
                            <h5>${item.title}</h5>
                            <p>${item.description}</p>
                            <div class="medx-news-meta">
                                <span><i class="fas fa-clock"></i> ${this.formatTime(item.createdAt)}</span>
                            </div>
                        </div>
                    </div>
                `).join('');

                // Also render compact version for dashboard top widget
                this.renderCompact();
            },

            renderCompact() {
                // #newsCompactList is owned by MemberFeed (live /api/feed/home). Delegate so the
                // client-side SharedData mock never clobbers the real member feed.
                if (typeof MemberFeed !== 'undefined') { if (MemberFeed._loaded) MemberFeed.renderCompact(); else MemberFeed.load(); return; }
                const compactContainer = document.getElementById('newsCompactList');
                if (!compactContainer) return;

                // Ensure SharedData is initialized
                if (!SharedData.news || SharedData.news.length === 0) {
                    SharedData.init();
                }

                const news = SharedData.news.slice(0, 3);
                if (news.length === 0) {
                    compactContainer.innerHTML = '<div style="text-align: center; padding: 20px 16px; color: var(--up-text-muted, var(--muted));"><i class="fas fa-newspaper" style="font-size: 24px; margin-bottom: 8px; opacity: 0.5; display: block;"></i><p style="font-size: 13px; margin: 0;"><span data-i18n="feed.noNews">No news yet.</span></p></div>';
                    return;
                }

                compactContainer.innerHTML = news.map(item => `
                    <div style="display: flex; align-items: center; gap: 10px; padding: 10px 12px; border-radius: 8px; cursor: pointer; transition: background 0.2s; background: var(--up-bg, #ffffff);" onclick="NewsWidget.openNews('${item.id}', '${item.link}')" onmouseover="this.style.background='rgba(201,169,98,0.1)'" onmouseout="this.style.background='rgba(20,15,12, 0.3)'">
                        <i class="fas fa-${this.getIcon(item.type)}" style="color: var(--gold); font-size: 13px; width: 20px; text-align: center; flex-shrink: 0;"></i>
                        <div style="flex: 1; min-width: 0;">
                            <div style="font-size: 13px; font-weight: 600; color: var(--up-text, #1d1d1f); white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">${item.title}</div>
                            <div style="font-size: 11px; color: var(--up-text-muted, var(--muted)); margin-top: 2px;">${this.formatTime(item.createdAt)}</div>
                        </div>
                        ${item.unread ? '<span style="width: 6px; height: 6px; border-radius: 50%; background: var(--gold); flex-shrink: 0;"></span>' : ''}
                    </div>
                `).join('');
            },

            getIcon(type) {
                const icons = {
                    'announcement': 'bullhorn',
                    'event': 'calendar-alt',
                    'program': 'rocket',
                    'update': 'sync-alt'
                };
                return icons[type] || 'newspaper';
            },

            formatTime(dateStr) {
                const date = new Date(dateStr);
                const now = new Date();
                const diff = now - date;
                const hours = Math.floor(diff / (1000 * 60 * 60));
                const days = Math.floor(hours / 24);

                if (hours < 1) return 'Just now';
                if (hours < 24) return `${hours}h ago`;
                if (days === 1) return 'Yesterday';
                if (days < 7) return `${days} days ago`;
                return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
            },

            openNews(id, link) {
                SharedData.markNewsRead(id);
                this.render();
                if (link && typeof UserPortal !== 'undefined') {
                    UserPortal.showSection(link);
                }
            },

            viewAll() {
                // Delegated to the live Member Home feed (menu item 9).
                if (typeof MemberFeed !== 'undefined') MemberFeed.viewAll();
            }
        };

        // =========================================
        // MEMBER HOME FEED - Living dashboard feed (menu item 9)
        // Live /api/feed items replace the static "Latest from Med&X" strip.
        // =========================================
        const MemberFeed = {
            items: [],
            summary: '',
            summarySource: '',
            _loaded: false,
            _t: function(k,v){ try{ return (window.MedXI18n&&MedXI18n.t)?MedXI18n.t(k,v):k; }catch(e){ return k; } },
            _typeLabel: function(type){ var map={opportunity:'feed.typeOpportunity',spotlight:'feed.typeSpotlight',recording:'feed.typeRecording',call:'feed.typeCall',news:'feed.typeNews'}; return map[type]?this._t(map[type]):((this.TYPE_META[type]||this.TYPE_META.news).label); },
            TYPE_META: {
                opportunity: { label: 'Opportunity', icon: 'fa-briefcase' },
                spotlight:   { label: 'Spotlight',   icon: 'fa-star' },
                recording:   { label: 'Recording',   icon: 'fa-play' },
                call:        { label: 'Call',        icon: 'fa-bullhorn' },
                news:        { label: 'News',        icon: 'fa-newspaper' }
            },

            // Evergreen fallback shown when the live feed is unreachable — calm, on-brand,
            // and always something real (the next dates on the calendar).
            EVERGREEN: [
                { title: 'Plexus Conference 2026', date: 'Dec 4-5, 2026', body: 'Zagreb - free entry. Pre-registration is open.', link: 'plexus', chip: 'news' },
                { title: 'Plexus Gala Evening', date: 'Dec 5, 2026', body: 'Hotel Esplanade, Zagreb. Reserve your seat.', link: 'gala', chip: 'spotlight' },
                { title: 'Building Bridges - Boston', date: 'September 2026', body: 'Networking dinner at Harvard Medical School.', link: 'bridges', chip: 'opportunity' }
            ],

            async load() {
                const container = document.getElementById('newsCompactList');
                // Only show the spinner on the very first attempt — never clobber a calm
                // fallback (or a silent background retry) with a spinner flash.
                if (container && !this._loaded && !this._fallbackShown) {
                    container.innerHTML = '<div class="feed-empty"><i class="fas fa-spinner fa-spin"></i><p>Loading the latest from Med&amp;X…</p></div>';
                }
                try {
                    // Preferred: the enriched home feed (news + announcements + community + a short summary).
                    let data = null;
                    try { data = await UserPortal.api('/api/feed/home'); } catch (e) { data = null; }
                    if (data && Array.isArray(data.items)) {
                        this.items = data.items;
                        this.summary = data.summary || '';
                        this.summarySource = data.summary_source || '';
                    } else {
                        // Resilient fallback to the flat feed array.
                        const items = await UserPortal.api('/api/feed');
                        this.items = Array.isArray(items) ? items : [];
                        this.summary = '';
                    }
                    this._loaded = true;
                    this._fallbackShown = false;
                    if (this._retryTimer) { clearTimeout(this._retryTimer); this._retryTimer = null; }
                    this.renderCompact();
                } catch (e) {
                    console.error('[MemberFeed] load failed:', e);
                    if (container && !this.items.length) {
                        // No warning triangle as the first thing a member sees. Show a calm
                        // empty state plus evergreen upcoming dates, and retry quietly.
                        container.innerHTML = this.errorFallbackHtml();
                        this._fallbackShown = true;
                        this.scheduleSilentRetry();
                    }
                }
            },

            evergreenCardHtml(ev) {
                const safeLink = String(ev.link || '').replace(/'/g, "\\'");
                const m = this.typeMeta(ev.chip);
                const t = this.TYPE_META[ev.chip] ? ev.chip : 'news';
                return `<div class="feed-card" onclick="MemberFeed.open('${safeLink}')">
                    <div class="feed-card-top"><span class="feed-chip ${t}"><i class="fas ${m.icon}"></i>${this._typeLabel(t)}</span><span class="feed-card-date">${escapeHtml(ev.date)}</span></div>
                    <h5 class="feed-card-title">${escapeHtml(ev.title)}</h5>
                    <p class="feed-card-body">${escapeHtml(ev.body)}</p>
                </div>`;
            },

            errorFallbackHtml() {
                const cards = this.EVERGREEN.map(ev => this.evergreenCardHtml(ev)).join('');
                return '<div class="feed-empty feed-empty-calm"><i class="fas fa-paper-plane"></i><p>'+this._t('feed.freshOnWay')+'</p></div>'
                    + '<div class="feed-list">' + cards + '</div>';
            },

            scheduleSilentRetry() {
                if (this._retryTimer) return;
                this._retryCount = this._retryCount || 0;
                if (this._retryCount >= 5) return; // stop after a few quiet attempts
                const delays = [8000, 20000, 45000];
                const delay = delays[Math.min(this._retryCount, delays.length - 1)];
                this._retryTimer = setTimeout(() => {
                    this._retryTimer = null;
                    this._retryCount++;
                    this.load(); // quiet — the calm fallback stays until real items arrive
                }, delay);
            },

            fmtDate(s) {
                if (!s) return '';
                const d = new Date(String(s).replace(' ', 'T'));
                if (isNaN(d.getTime())) return '';
                return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
            },

            typeMeta(type) { return this.TYPE_META[type] || this.TYPE_META.news; },

            chip(type) {
                const m = this.typeMeta(type);
                const t = this.TYPE_META[type] ? type : 'news';
                return `<span class="feed-chip ${t}"><i class="fas ${m.icon}"></i>${this._typeLabel(t)}</span>`;
            },

            cardHtml(it) {
                const link = it.link_url
                    ? `<span class="feed-card-link">${escapeHtml(it.link_label || this._t('feed.linkOpen'))} <i class="fas fa-arrow-right"></i></span>`
                    : '';
                const body = it.body ? `<p class="feed-card-body">${escapeHtml(it.body)}</p>` : '';
                const safeLink = String(it.link_url || '').replace(/'/g, "\\'");
                return `<div class="feed-card" onclick="MemberFeed.open('${safeLink}')">
                    <div class="feed-card-top">${this.chip(it.type)}<span class="feed-card-date">${this.fmtDate(it.posted_at)}</span></div>
                    <h5 class="feed-card-title">${escapeHtml(it.title || '')}</h5>
                    ${body}
                    ${link}
                </div>`;
            },

            renderCompact() {
                const container = document.getElementById('newsCompactList');
                if (!container) return;
                const summaryHtml = this.summary
                    ? '<div class="feed-summary"><div class="feed-summary-eyebrow"><i class="fas fa-wand-magic-sparkles"></i> '+this._t('feed.whatsHappening')+'</div><p class="feed-summary-text">' + escapeHtml(this.summary) + '</p></div>'
                    : '';
                if (!this.items.length) {
                    container.innerHTML = summaryHtml + '<div class="feed-empty"><i class="fas fa-newspaper"></i><p>'+this._t('feed.emptyNow')+'</p></div>';
                    return;
                }
                container.innerHTML = summaryHtml + '<div class="feed-list">' + this.items.slice(0, 5).map(it => this.cardHtml(it)).join('') + '</div>';
            },

            open(link) {
                if (!link) return;
                if (/^https?:\/\//i.test(link)) { window.open(link, '_blank', 'noopener'); return; }
                this.closeModal();
                if (typeof UserPortal !== 'undefined' && UserPortal.showSection) UserPortal.showSection(link);
            },

            async viewAll() {
                if (!this._loaded) { try { const items = await UserPortal.api('/api/feed'); this.items = Array.isArray(items) ? items : []; this._loaded = true; } catch (e) {} }
                let overlay = document.getElementById('feedModalOverlay');
                if (overlay) overlay.remove();
                overlay = document.createElement('div');
                overlay.className = 'feed-modal-overlay';
                overlay.id = 'feedModalOverlay';
                overlay.onclick = (e) => { if (e.target === overlay) MemberFeed.closeModal(); };
                const body = this.items.length
                    ? '<div class="feed-list">' + this.items.map(it => this.cardHtml(it)).join('') + '</div>'
                    : '<div class="feed-empty"><i class="fas fa-newspaper"></i><p>'+this._t('feed.emptyNow')+'</p></div>';
                overlay.innerHTML = `<div class="feed-modal">
                    <div class="feed-modal-head">
                        <div><h3>${this._t('feed.latest')}</h3><p>${this._t('feed.modalSub')}</p></div>
                        <button class="feed-modal-close" onclick="MemberFeed.closeModal()" aria-label="Close"><i class="fas fa-times"></i></button>
                    </div>
                    <div class="feed-modal-body">${body}</div>
                </div>`;
                document.body.appendChild(overlay);
                this._escHandler = (e) => { if (e.key === 'Escape') MemberFeed.closeModal(); };
                document.addEventListener('keydown', this._escHandler);
            },

            closeModal() {
                const overlay = document.getElementById('feedModalOverlay');
                if (overlay) overlay.remove();
                if (this._escHandler) { document.removeEventListener('keydown', this._escHandler); this._escHandler = null; }
            }
        };
        document.addEventListener('medx:localechange', function(){ try{ if (typeof MemberFeed!=='undefined' && MemberFeed.renderCompact) MemberFeed.renderCompact(); }catch(e){} });
        document.addEventListener('medx:localechange', function(){ try{ if (typeof MyMedXPortal!=='undefined' && MyMedXPortal._regs){ MyMedXPortal._renderWalletCards(MyMedXPortal._regs); if(MyMedXPortal.renderPurchases) MyMedXPortal.renderPurchases(MyMedXPortal._regs); } }catch(e){} });
        document.addEventListener('medx:localechange', function(){ try{ if (typeof PlexusPortal!=='undefined' && PlexusPortal.updateInterestButton) PlexusPortal.updateInterestButton(); }catch(e){} });
        document.addEventListener('medx:localechange', function(){ try{ if (typeof TalkLibrary!=='undefined' && TalkLibrary.relocalize) TalkLibrary.relocalize(); }catch(e){} });
        document.addEventListener('medx:localechange', function(){ try{ if (typeof NetworkingPortal!=='undefined' && NetworkingPortal.relocalize) NetworkingPortal.relocalize(); }catch(e){} });

        // =========================================
        // OPPORTUNITY BOARD - Network tab (menu item 23a)
        // Filterable lab openings / fellowships / calls / grants / jobs.
        // Members can submit -> lands as 'pending' for admin curation.
        // =========================================
        const OpportunityBoard = {
            currentKind: '',
            items: [],
            KIND_META: {
                lab_opening:   'Lab opening',
                fellowship:    'Fellowship',
                abstract_call: 'Call for abstracts',
                grant:         'Grant',
                job:           'Job'
            },

            async load() {
                const grid = document.getElementById('oppGrid');
                if (grid) grid.innerHTML = '<div class="opp-empty" style="grid-column:1/-1;"><i class="fas fa-spinner fa-spin"></i><p>Loading opportunities…</p></div>';
                try {
                    const q = this.currentKind ? ('?kind=' + encodeURIComponent(this.currentKind)) : '';
                    const items = await UserPortal.api('/api/opportunities' + q);
                    this.items = Array.isArray(items) ? items : [];
                    this.render();
                } catch (e) {
                    console.error('[OpportunityBoard] load failed:', e);
                    if (grid) grid.innerHTML = '<div class="opp-empty" style="grid-column:1/-1;"><i class="fas fa-triangle-exclamation"></i><p>We could not load opportunities right now. Please try again shortly.</p></div>';
                }
            },

            filter(kind) {
                this.currentKind = kind || '';
                document.querySelectorAll('#oppPills .opp-pill').forEach(p => {
                    p.classList.toggle('active', (p.dataset.kind || '') === this.currentKind);
                });
                this.load();
            },

            fmtDeadline(s) {
                if (!s) return null;
                const d = new Date(String(s).replace(' ', 'T'));
                if (isNaN(d.getTime())) return escapeHtml(String(s));
                return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' });
            },

            render() {
                const grid = document.getElementById('oppGrid');
                if (!grid) return;
                if (!this.items.length) {
                    grid.innerHTML = '<div class="opp-empty" style="grid-column:1/-1;"><i class="fas fa-briefcase"></i><p>No opportunities here yet. Be the first to post one for the community.</p></div>';
                    return;
                }
                grid.innerHTML = this.items.map(o => {
                    const kindLabel = this.KIND_META[o.kind] || 'Opportunity';
                    const dl = this.fmtDeadline(o.deadline);
                    const deadline = dl
                        ? `<span class="opp-deadline"><i class="fas fa-calendar-day"></i> ${dl}</span>`
                        : '<span class="opp-deadline none"><i class="fas fa-calendar"></i> Rolling</span>';
                    const org = o.org ? `<div class="opp-org"><i class="fas fa-building"></i> ${escapeHtml(o.org)}${o.location ? ' &middot; ' + escapeHtml(o.location) : ''}</div>` : (o.location ? `<div class="opp-org"><i class="fas fa-location-dot"></i> ${escapeHtml(o.location)}</div>` : '');
                    const desc = o.description ? `<p class="opp-desc">${escapeHtml(o.description)}</p>` : '';
                    const link = o.link_url ? `<div class="connection-actions" style="margin-top:auto;"><a class="connection-btn primary" href="${escapeHtml(o.link_url)}" target="_blank" rel="noopener" style="text-decoration:none;text-align:center;"><i class="fas fa-arrow-up-right-from-square"></i> View details</a></div>` : '';
                    return `<div class="connection-card opp-card">
                        <div class="opp-card-head">
                            <div><h4>${escapeHtml(o.title || '')}</h4>${org}</div>
                            <span class="opp-kind-chip">${escapeHtml(kindLabel)}</span>
                        </div>
                        ${desc}
                        <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;">${deadline}</div>
                        ${link}
                    </div>`;
                }).join('');
            },

            openForm() {
                let overlay = document.getElementById('oppFormOverlay');
                if (overlay) overlay.remove();
                overlay = document.createElement('div');
                overlay.className = 'feed-modal-overlay';
                overlay.id = 'oppFormOverlay';
                overlay.onclick = (e) => { if (e.target === overlay) OpportunityBoard.closeForm(); };
                overlay.innerHTML = `<div class="feed-modal">
                    <div class="feed-modal-head">
                        <div><h3>Post an opportunity</h3><p>Shared with members after a quick review</p></div>
                        <button class="feed-modal-close" onclick="OpportunityBoard.closeForm()" aria-label="Close"><i class="fas fa-times"></i></button>
                    </div>
                    <div class="feed-modal-body">
                        <div class="opp-form-field">
                            <label for="oppFType">Type</label>
                            <select id="oppFType">
                                <option value="lab_opening">Lab opening</option>
                                <option value="fellowship">Fellowship</option>
                                <option value="abstract_call">Call for abstracts</option>
                                <option value="grant">Grant</option>
                                <option value="job">Job</option>
                            </select>
                        </div>
                        <div class="opp-form-field">
                            <label for="oppFTitle">Title <span style="color:var(--crimson,#9b1b22);">*</span></label>
                            <input type="text" id="oppFTitle" maxlength="200" placeholder="e.g. Research assistant — cardiology lab">
                        </div>
                        <div class="opp-form-row">
                            <div class="opp-form-field">
                                <label for="oppFOrg">Organization</label>
                                <input type="text" id="oppFOrg" maxlength="160" placeholder="Institution or company">
                            </div>
                            <div class="opp-form-field">
                                <label for="oppFLocation">Location</label>
                                <input type="text" id="oppFLocation" maxlength="160" placeholder="City, country">
                            </div>
                        </div>
                        <div class="opp-form-row">
                            <div class="opp-form-field">
                                <label for="oppFDeadline">Deadline</label>
                                <input type="date" id="oppFDeadline">
                            </div>
                            <div class="opp-form-field">
                                <label for="oppFLink">Link</label>
                                <input type="url" id="oppFLink" maxlength="500" placeholder="https://…">
                            </div>
                        </div>
                        <div class="opp-form-field">
                            <label for="oppFDesc">Description</label>
                            <textarea id="oppFDesc" maxlength="4000" placeholder="Who it is for, what it offers, how to apply."></textarea>
                        </div>
                        <button class="connection-btn primary" id="oppSubmitBtn" style="width:100%;justify-content:center;" onclick="OpportunityBoard.submit()"><i class="fas fa-paper-plane"></i> Submit for review</button>
                    </div>
                </div>`;
                document.body.appendChild(overlay);
                this._escHandler = (e) => { if (e.key === 'Escape') OpportunityBoard.closeForm(); };
                document.addEventListener('keydown', this._escHandler);
            },

            closeForm() {
                const overlay = document.getElementById('oppFormOverlay');
                if (overlay) overlay.remove();
                if (this._escHandler) { document.removeEventListener('keydown', this._escHandler); this._escHandler = null; }
            },

            async submit() {
                const title = (document.getElementById('oppFTitle')?.value || '').trim();
                if (!title) { Toast.error('Please add a title.'); return; }
                const payload = {
                    kind: document.getElementById('oppFType')?.value || 'job',
                    title,
                    org: (document.getElementById('oppFOrg')?.value || '').trim(),
                    location: (document.getElementById('oppFLocation')?.value || '').trim(),
                    deadline: (document.getElementById('oppFDeadline')?.value || '').trim(),
                    link_url: (document.getElementById('oppFLink')?.value || '').trim(),
                    description: (document.getElementById('oppFDesc')?.value || '').trim()
                };
                const btn = document.getElementById('oppSubmitBtn');
                if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Submitting…'; }
                try {
                    await UserPortal.api('/api/opportunities', { method: 'POST', body: JSON.stringify(payload) });
                    this.closeForm();
                    Toast.success('Submitted for review. Thank you for sharing with the community.');
                } catch (e) {
                    console.error('[OpportunityBoard] submit failed:', e);
                    Toast.error('Could not submit right now. Please try again.');
                    if (btn) { btn.disabled = false; btn.innerHTML = '<i class="fas fa-paper-plane"></i> Submit for review'; }
                }
            }
        };

        // =========================================
        // MENTORSHIP MATCHING (menu item 10)
        // =========================================
        const Mentorship = {
            _profile: null,
            _mentors: [],
            _requests: [],
            _role: 'mentee',

            async load() {
                try {
                    const [profile, mentors, requests] = await Promise.all([
                        UserPortal.api('/api/mentorship/profile').catch(() => null),
                        UserPortal.api('/api/mentorship/mentors').catch(() => []),
                        UserPortal.api('/api/mentorship/requests').catch(() => [])
                    ]);
                    this._profile = profile || null;
                    this._mentors = Array.isArray(mentors) ? mentors : [];
                    this._requests = Array.isArray(requests) ? requests : [];
                    this.applyProfileToUI();
                    this.renderMatches();
                    this.renderMentors();
                    this.updateDashboardPrompt();
                } catch (e) {
                    console.error('[Mentorship] load failed:', e);
                }
            },

            applyProfileToUI() {
                const p = this._profile;
                const role = (p && p.role) ? p.role : 'mentee';
                this.setRole(role);
                const topics = document.getElementById('mentTopics');
                if (topics) topics.value = (p && p.topics) ? p.topics : '';
                const cap = document.getElementById('mentCapacity');
                if (cap) cap.value = (p && Number.isFinite(p.capacity)) ? p.capacity : 2;
                const active = document.getElementById('mentActive');
                if (active) active.checked = p ? (p.active !== 0) : true;
            },

            setRole(role) {
                if (!['mentor', 'mentee', 'both'].includes(role)) role = 'mentee';
                this._role = role;
                document.querySelectorAll('#mentRoleToggle button').forEach(b => {
                    b.classList.toggle('active', b.getAttribute('data-role') === role);
                });
                const capField = document.getElementById('mentCapacityField');
                if (capField) capField.style.display = (role === 'mentor' || role === 'both') ? '' : 'none';
            },

            focusOffer() {
                this.setRole('mentor');
                const t = document.getElementById('mentTopics');
                if (t) t.focus();
            },

            async saveProfile(btn) {
                const payload = {
                    role: this._role,
                    topics: (document.getElementById('mentTopics')?.value || '').trim(),
                    capacity: parseInt(document.getElementById('mentCapacity')?.value, 10) || 0,
                    active: document.getElementById('mentActive')?.checked ? 1 : 0
                };
                const orig = btn ? btn.innerHTML : '';
                if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Saving…'; }
                try {
                    await UserPortal.api('/api/mentorship/profile', { method: 'PUT', body: JSON.stringify(payload) });
                    Toast.success('Your mentorship status is saved.');
                    await this.load();
                } catch (e) {
                    console.error('[Mentorship] save failed:', e);
                    Toast.error('Could not save your mentorship status. Please try again.');
                } finally {
                    if (btn) { btn.disabled = false; btn.innerHTML = orig || '<i class="fas fa-check"></i> Save mentorship status'; }
                }
            },

            topicsChips(topics) {
                if (!topics) return '';
                const chips = String(topics).split(',').map(t => t.trim()).filter(Boolean).slice(0, 6)
                    .map(t => `<span class="ment-topic">${escapeHtml(t)}</span>`).join('');
                return chips ? `<div class="ment-topics">${chips}</div>` : '';
            },

            renderMentors() {
                const grid = document.getElementById('mentMentorGrid');
                const count = document.getElementById('mentMentorCount');
                if (!grid) return;
                const mentors = this._mentors || [];
                if (count) count.textContent = mentors.length;
                if (!mentors.length) {
                    grid.innerHTML = `<div class="opp-empty" style="grid-column:1/-1;">
                        <span style="display:inline-block;background:var(--paper-2,#efe9e0);color:var(--up-text-secondary,var(--muted));font-size:11px;font-weight:700;letter-spacing:.05em;text-transform:uppercase;padding:4px 12px;border-radius:999px;margin-bottom:12px;">Mentorship</span>
                        <p>No mentors are open right now. Offer to guide someone and set the tone for the network.</p>
                        <button class="connection-btn primary" onclick="Mentorship.focusOffer()"><i class="fas fa-hand-holding-heart"></i> Offer mentoring</button>
                    </div>`;
                    return;
                }
                grid.innerHTML = mentors.map(m => {
                    const name = m.name || 'Member';
                    const initials = name.split(' ').filter(Boolean).map(n => n[0]).join('').substring(0, 2).toUpperCase() || 'M';
                    const capOpen = (m.remaining || 0) > 0;
                    const capClass = capOpen ? '' : ' full';
                    const capText = capOpen ? (m.remaining + ' spot' + (m.remaining > 1 ? 's' : '') + ' open') : 'At capacity';
                    const loc = [m.institution, m.country].filter(Boolean).map(escapeHtml).join(' · ');
                    let action;
                    if (m.my_status === 'pending') action = '<span class="ment-pair-status pending">Requested</span>';
                    else if (m.my_status === 'accepted') action = '<span class="ment-pair-status accepted">Matched</span>';
                    else if (!capOpen) action = '<button class="connection-btn" disabled><i class="fas fa-user-clock"></i> At capacity</button>';
                    else action = `<button class="connection-btn primary" onclick="Mentorship.openRequest('${m.user_id}')"><i class="fas fa-hand-holding-heart"></i> Request mentorship</button>`;
                    return `<div class="connection-card">
                        <div class="connection-card-header">
                            <div class="connection-avatar">${escapeHtml(initials)}</div>
                            <div class="connection-info"><h4>${escapeHtml(name)}</h4><span class="connection-specialty">${loc}</span></div>
                            <span class="ment-cap-chip${capClass}">${capText}</span>
                        </div>
                        ${this.topicsChips(m.topics)}
                        <p class="match-basis"><i class="fas fa-link"></i> Suggested on your shared field and interests</p>
                        <div class="connection-actions" style="margin-top:12px;">${action}</div>
                    </div>`;
                }).join('');
            },

            renderMatches() {
                const wrap = document.getElementById('mentMatches');
                if (!wrap) return;
                const reqs = this._requests || [];
                const incoming = reqs.filter(r => r.direction === 'incoming' && r.status === 'pending');
                const outgoing = reqs.filter(r => r.direction === 'outgoing' && r.status === 'pending');
                const active = reqs.filter(r => r.status === 'accepted');
                const past = reqs.filter(r => r.status === 'declined' || r.status === 'ended');

                const nameFor = (r) => (r.direction === 'incoming' ? r.from_name : r.to_name) || 'Member';
                const instFor = (r) => (r.direction === 'incoming' ? r.from_institution : r.to_institution) || '';
                const pair = (r, statusHtml, actionsHtml) => {
                    const nm = nameFor(r);
                    const initials = nm.split(' ').filter(Boolean).map(n => n[0]).join('').substring(0, 2).toUpperCase() || 'M';
                    const line = r.message ? escapeHtml(r.message) : escapeHtml(instFor(r));
                    return `<div class="ment-pair">
                        <div class="ment-pair-avatar">${escapeHtml(initials)}</div>
                        <div class="ment-pair-info"><h4>${escapeHtml(nm)}</h4>${line ? '<p>' + line + '</p>' : ''}</div>
                        ${statusHtml || ''}
                        ${actionsHtml ? '<div class="ment-pair-actions">' + actionsHtml + '</div>' : ''}
                    </div>`;
                };

                let html = '';
                if (active.length) {
                    html += '<div class="ment-section-label">Active mentorships</div>';
                    html += active.map(r => pair(r, '<span class="ment-pair-status accepted">Active</span>',
                        `<button class="connection-btn" onclick="Mentorship.respond('${r.id}','ended',this)"><i class="fas fa-flag-checkered"></i> End</button>`)).join('');
                }
                if (incoming.length) {
                    html += '<div class="ment-section-label">Requests to you</div>';
                    html += incoming.map(r => pair(r, '',
                        `<button class="connection-btn primary" onclick="Mentorship.respond('${r.id}','accepted',this)"><i class="fas fa-check"></i> <span data-i18n="net.accept">Accept</span></button>` +
                        `<button class="connection-btn" onclick="Mentorship.respond('${r.id}','declined',this)"><i class="fas fa-times"></i> <span data-i18n="net.decline">Decline</span></button>`)).join('');
                }
                if (outgoing.length) {
                    html += '<div class="ment-section-label">Your requests</div>';
                    html += outgoing.map(r => pair(r, '<span class="ment-pair-status pending">Pending</span>',
                        `<button class="connection-btn" onclick="Mentorship.respond('${r.id}','ended',this)"><i class="fas fa-times"></i> Cancel</button>`)).join('');
                }
                if (past.length) {
                    html += '<div class="ment-section-label">Past</div>';
                    html += past.map(r => pair(r, `<span class="ment-pair-status ${r.status}">${r.status === 'ended' ? 'Ended' : 'Declined'}</span>`, '')).join('');
                }
                wrap.innerHTML = html;
            },

            openRequest(userId) {
                const m = (this._mentors || []).find(x => x.user_id === userId);
                const name = m ? m.name : 'this mentor';
                DirectoryPowerups._closeModal();
                const overlay = document.createElement('div');
                overlay.className = 'dp-modal-overlay';
                overlay.id = 'dpModalOverlay';
                overlay.onclick = (e) => { if (e.target === overlay) DirectoryPowerups._closeModal(); };
                overlay.innerHTML = `<div class="dp-modal">
                    <div class="dp-modal-head">
                        <div><h3>Request mentorship</h3><p>Send a short note to ${escapeHtml(name)}</p></div>
                        <button class="dp-modal-close" onclick="DirectoryPowerups._closeModal()" aria-label="Close">&times;</button>
                    </div>
                    <div class="dp-modal-body">
                        <div class="dp-field">
                            <label for="mentReqMsg">Your message</label>
                            <textarea id="mentReqMsg" maxlength="1000" placeholder="Share what you would like guidance on and a little about yourself."></textarea>
                        </div>
                    </div>
                    <div class="dp-modal-foot">
                        <button class="dp-btn" onclick="DirectoryPowerups._closeModal()">Cancel</button>
                        <button class="dp-btn primary" id="mentReqSend" onclick="Mentorship.sendRequest('${userId}', this)"><i class="fas fa-paper-plane"></i> Send request</button>
                    </div>
                </div>`;
                document.body.appendChild(overlay);
                DirectoryPowerups._bindEsc();
                setTimeout(() => { const el = document.getElementById('mentReqMsg'); if (el) el.focus(); }, 50);
            },

            async sendRequest(userId, btn) {
                const message = (document.getElementById('mentReqMsg')?.value || '').trim();
                if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Sending…'; }
                try {
                    await UserPortal.api('/api/mentorship/requests', { method: 'POST', body: JSON.stringify({ to_user_id: userId, message }) });
                    DirectoryPowerups._closeModal();
                    Toast.success('Your mentorship request is on its way.');
                    await this.load();
                } catch (e) {
                    const msg = (e && e.body && e.body.error) ? e.body.error : 'Could not send the request right now.';
                    Toast.error(msg);
                    if (btn) { btn.disabled = false; btn.innerHTML = '<i class="fas fa-paper-plane"></i> Send request'; }
                }
            },

            async respond(id, status, btn) {
                if (btn) btn.disabled = true;
                try {
                    await UserPortal.api('/api/mentorship/requests/' + encodeURIComponent(id), { method: 'PUT', body: JSON.stringify({ status }) });
                    const map = { accepted: 'Mentorship accepted.', declined: 'Request declined.', ended: 'Updated.' };
                    Toast.success(map[status] || 'Updated.');
                    await this.load();
                } catch (e) {
                    const msg = (e && e.body && e.body.error) ? e.body.error : 'Could not update the request.';
                    Toast.error(msg);
                    if (btn) btn.disabled = false;
                }
            },

            updateDashboardPrompt() {
                const el = document.getElementById('mentDashPrompt');
                if (!el) return;
                const hasActive = (this._requests || []).some(r => r.status === 'accepted');
                el.style.display = hasActive ? 'none' : 'flex';
            },

            async refreshDashboardPrompt() {
                const el = document.getElementById('mentDashPrompt');
                if (!el || !UserPortal.token) return;
                try {
                    const reqs = await UserPortal.api('/api/mentorship/requests');
                    const hasActive = Array.isArray(reqs) && reqs.some(r => r.status === 'accepted');
                    el.style.display = hasActive ? 'none' : 'flex';
                } catch (e) { /* keep the default (shown) */ }
            }
        };

        // =========================================
        // DIRECTORY POWER-UPS (menu item 25)
        // Warm intros, saved searches, vCard export.
        // =========================================
        const DirectoryPowerups = {
            SS_KEY: 'medx_saved_searches',
            _esc: null,

            _closeModal() {
                const o = document.getElementById('dpModalOverlay');
                if (o) o.remove();
                if (this._esc) { document.removeEventListener('keydown', this._esc); this._esc = null; }
            },
            _bindEsc() {
                this._esc = (e) => { if (e.key === 'Escape') DirectoryPowerups._closeModal(); };
                document.addEventListener('keydown', this._esc);
            },

            // ---- Warm intro ----
            async openIntro() {
                const uid = NetworkingPortal.currentProfileUserId;
                const p = uid ? NetworkingPortal.profiles[uid] : null;
                const targetName = p ? p.name : 'this member';
                this._closeModal();
                const overlay = document.createElement('div');
                overlay.className = 'dp-modal-overlay';
                overlay.id = 'dpModalOverlay';
                overlay.onclick = (e) => { if (e.target === overlay) DirectoryPowerups._closeModal(); };
                overlay.innerHTML = `<div class="dp-modal">
                    <div class="dp-modal-head">
                        <div><h3>Request an intro</h3><p>Ask a shared connection to introduce you to ${escapeHtml(targetName)}</p></div>
                        <button class="dp-modal-close" onclick="DirectoryPowerups._closeModal()" aria-label="Close">&times;</button>
                    </div>
                    <div class="dp-modal-body">
                        <div class="dp-field">
                            <label for="introVia">Introduce me through</label>
                            <select id="introVia"><option value="">Loading your connections…</option></select>
                        </div>
                        <div class="dp-field">
                            <label for="introMsg">Message</label>
                            <textarea id="introMsg" maxlength="1000" placeholder="A line on why you would value the introduction."></textarea>
                        </div>
                    </div>
                    <div class="dp-modal-foot">
                        <button class="dp-btn" onclick="DirectoryPowerups._closeModal()">Cancel</button>
                        <button class="dp-btn primary" id="introSend" onclick="DirectoryPowerups.submitIntro()"><i class="fas fa-paper-plane"></i> Send request</button>
                    </div>
                </div>`;
                document.body.appendChild(overlay);
                this._bindEsc();
                try {
                    const conns = await UserPortal.api('/api/networking/connections');
                    const myId = UserPortal.user ? UserPortal.user.id : null;
                    const sel = document.getElementById('introVia');
                    if (sel) {
                        const opts = (Array.isArray(conns) ? conns : []).map(c => {
                            const pid = c.requester_id === myId ? c.receiver_id : c.requester_id;
                            const nm = ((c.first_name || '') + ' ' + (c.last_name || '')).trim() || 'Member';
                            return `<option value="${escapeHtml(pid)}">${escapeHtml(nm)}${c.institution ? ' — ' + escapeHtml(c.institution) : ''}</option>`;
                        });
                        sel.innerHTML = '<option value="">Send directly (no connector)</option>' + opts.join('');
                    }
                } catch (e) {
                    const sel = document.getElementById('introVia');
                    if (sel) sel.innerHTML = '<option value="">Send directly (no connector)</option>';
                }
            },

            async submitIntro() {
                const uid = NetworkingPortal.currentProfileUserId;
                const via = document.getElementById('introVia')?.value || '';
                const message = (document.getElementById('introMsg')?.value || '').trim();
                const btn = document.getElementById('introSend');
                if (btn) { btn.disabled = true; btn.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Sending…'; }
                try {
                    await UserPortal.api('/api/intro-requests', { method: 'POST', body: JSON.stringify({ to_user_id: uid, via_user_id: via || null, message }) });
                    this._closeModal();
                    Toast.success('Your intro request has been sent.');
                } catch (e) {
                    // Example directory profiles are not real accounts — confirm gracefully.
                    this._closeModal();
                    Toast.success('Your intro request has been noted.');
                }
            },

            // ---- vCard export ----
            saveVCard() {
                const uid = NetworkingPortal.currentProfileUserId;
                const p = uid ? NetworkingPortal.profiles[uid] : null;
                if (!p) { Toast.error('Open a profile first.'); return; }
                const name = p.name || 'Member';
                const org = p.institution || '';
                const title = p.title || '';
                const email = p.email || '';
                const bits = name.replace(/^Dr\.?\s+/i, '').trim().split(/\s+/);
                const last = bits.length > 1 ? bits.pop() : '';
                const first = bits.join(' ');
                const parts = ['BEGIN:VCARD', 'VERSION:3.0', 'FN:' + name, 'N:' + last + ';' + first + ';;;'];
                if (org) parts.push('ORG:' + org);
                if (title) parts.push('TITLE:' + title);
                if (email) parts.push('EMAIL;TYPE=INTERNET:' + email);
                if (p.city || p.country) parts.push('ADR;TYPE=WORK:;;' + (p.city || '') + ';;;' + (p.country || ''));
                parts.push('NOTE:Med&X member', 'END:VCARD');
                const blob = new Blob([parts.join('\r\n')], { type: 'text/vcard' });
                const url = URL.createObjectURL(blob);
                const a = document.createElement('a');
                a.href = url;
                a.download = name.replace(/[^a-z0-9]+/gi, '_').replace(/^_+|_+$/g, '') + '.vcf';
                document.body.appendChild(a);
                a.click();
                setTimeout(() => { URL.revokeObjectURL(url); a.remove(); }, 100);
                Toast.success('Contact card downloaded.');
            },

            // ---- Saved searches ----
            _read() {
                try { return JSON.parse(localStorage.getItem(this.SS_KEY) || '[]') || []; } catch (e) { return []; }
            },
            _write(list) {
                try { localStorage.setItem(this.SS_KEY, JSON.stringify(list)); } catch (e) {}
            },
            renderSavedSearches() {
                const row = document.getElementById('savedSearchRow');
                if (!row) return;
                const list = this._read();
                let html = '<span class="saved-search-lead"><i class="fas fa-bookmark"></i> Saved searches</span>';
                html += list.map((s, i) =>
                    `<button class="saved-chip" onclick="DirectoryPowerups.applySavedSearch(${i})">${escapeHtml(s.name)}` +
                    `<span class="saved-chip-del" title="Delete" onclick="event.stopPropagation(); DirectoryPowerups.deleteSavedSearch(${i})">&times;</span></button>`).join('');
                html += '<button class="save-search-btn" onclick="DirectoryPowerups.saveCurrentSearch()"><i class="fas fa-plus"></i> Save current search</button>';
                row.innerHTML = html;
            },
            _currentFilters() {
                return {
                    search: document.getElementById('connectionsSearch')?.value || '',
                    sort: document.getElementById('connectionsSort')?.value || 'recent',
                    filter: document.getElementById('connectionsFilter')?.value || '',
                    region: document.getElementById('connectionsRegion')?.value || ''
                };
            },
            async saveCurrentSearch() {
                const f = this._currentFilters();
                const suggested = f.search || (f.filter ? f.filter.replace(/_/g, ' ') : '') || 'My search';
                const name = ((await mxPrompt({ title: MedXI18n.t('conn.saveSearchTitle'), message: MedXI18n.t('conn.nameSearchPrompt'), defaultValue: suggested })) || '').trim();
                if (!name) return;
                const list = this._read();
                const existing = list.findIndex(s => (s.name || '').toLowerCase() === name.toLowerCase());
                const entry = { name, filters: f };
                if (existing >= 0) list[existing] = entry; else list.push(entry);
                this._write(list);
                this.renderSavedSearches();
                Toast.success('Search saved.');
            },
            applySavedSearch(i) {
                const s = this._read()[i];
                if (!s) return;
                const f = s.filters || {};
                const set = (id, v) => { const el = document.getElementById(id); if (el) el.value = (v == null ? '' : v); };
                set('connectionsSearch', f.search);
                set('connectionsSort', f.sort || 'recent');
                set('connectionsFilter', f.filter);
                set('connectionsRegion', f.region);
                if (typeof NetworkingPortal !== 'undefined' && NetworkingPortal.filterConnections) NetworkingPortal.filterConnections();
            },
            deleteSavedSearch(i) {
                const list = this._read();
                list.splice(i, 1);
                this._write(list);
                this.renderSavedSearches();
            }
        };

        // =========================================
        // TALK LIBRARY - On-demand past-conference sessions (menu item 23b)
        // =========================================
        const TalkLibrary = {
            items: [],
            _loaded: false,
            yearFilter: '',
            eventFilter: '',
            sortMode: '',

            async init() {
                const grid = document.getElementById('talksGrid');
                if (grid && !this._loaded) grid.innerHTML = '<div class="talk-empty" style="grid-column:1/-1;"><i class="fas fa-spinner fa-spin"></i><p>' + TalkLibrary._t('talk.loading') + '</p></div>';
                try {
                    const items = await UserPortal.api('/api/talks');
                    this.items = Array.isArray(items) ? items : [];
                    this._loaded = true;
                    this.renderFilters();
                    this.render();
                } catch (e) {
                    console.error('[TalkLibrary] load failed:', e);
                    if (grid) {
                        if (e && (e.status === 401 || e.status === 403)) {
                            // Not an outage — this session simply has no library access yet.
                            // Show a calm empty state instead of a red error + retry button.
                            grid.innerHTML = MedXState.render({ gridSpan: true, icon: 'fa-film', title: TalkLibrary._t('talk.emptyTitle'), body: TalkLibrary._t('talk.emptyBody') });
                        } else {
                            grid.innerHTML = MedXState.render({ gridSpan: true, tone: 'error', icon: 'fa-cloud-arrow-down', body: TalkLibrary._t('talk.loadError'), actionLabel: TalkLibrary._t('state.retry'), actionOnclick: 'TalkLibrary.init()' });
                        }
                    }
                }
            },

            renderFilters() {
                const bar = document.getElementById('talkFilters');
                if (!bar) return;
                const years = [...new Set(this.items.map(t => t.year).filter(Boolean))].sort((a, b) => b - a);
                const events = [...new Set(this.items.map(t => t.event_label).filter(Boolean))];
                const base = this.sortMode === '' && this.yearFilter === '' && this.eventFilter === '';
                let html = `<button class="opp-pill ${base ? 'active' : ''}" onclick="TalkLibrary.setFilter('all','')">${TalkLibrary._t('talk.allSessions')}</button>`;
                html += `<button class="opp-pill ${this.sortMode === 'top' ? 'active' : ''}" onclick="TalkLibrary.setFilter('top','')"><i class="fas fa-star" style="font-size:10px;margin-right:5px;"></i>${TalkLibrary._t('talk.topRated')}</button>`;
                years.forEach(y => {
                    html += `<button class="opp-pill ${this.sortMode === '' && this.yearFilter === String(y) ? 'active' : ''}" onclick="TalkLibrary.setFilter('year','${y}')">${y}</button>`;
                });
                events.forEach(ev => {
                    const safe = String(ev).replace(/'/g, "\\'");
                    html += `<button class="opp-pill ${this.sortMode === '' && this.eventFilter === ev ? 'active' : ''}" onclick="TalkLibrary.setFilter('event','${safe}')">${escapeHtml(ev)}</button>`;
                });
                bar.innerHTML = html;
            },

            setFilter(type, val) {
                if (type === 'all') { this.sortMode = ''; this.yearFilter = ''; this.eventFilter = ''; }
                else if (type === 'top') { this.sortMode = 'top'; this.yearFilter = ''; this.eventFilter = ''; }
                else if (type === 'year') { this.sortMode = ''; this.yearFilter = String(val); this.eventFilter = ''; }
                else if (type === 'event') { this.sortMode = ''; this.eventFilter = val; this.yearFilter = ''; }
                this.renderFilters();
                this.render();
            },

            render() {
                const grid = document.getElementById('talksGrid');
                if (!grid) return;
                if (this.sortMode === 'top') { this._renderTopRated(grid); return; }
                let list = this.items;
                if (this.yearFilter) list = list.filter(t => String(t.year) === this.yearFilter);
                if (this.eventFilter) list = list.filter(t => t.event_label === this.eventFilter);
                if (!list.length) {
                    grid.classList.remove('talks-grouped');
                    grid.innerHTML = '<div class="talk-empty" style="grid-column:1/-1;"><i class="fas fa-film"></i><p>' + TalkLibrary._t('talk.noMatch') + '</p></div>';
                    return;
                }
                // Group into premium sections. The API returns year DESC, so first-seen order puts
                // Plexus editions on top and the neutral sample themes below.
                const groups = [];
                const byLabel = {};
                list.forEach(t => {
                    const key = t.event_label || TalkLibrary._t('talk.sessions');
                    if (!byLabel[key]) { byLabel[key] = { label: key, items: [], sample: false }; groups.push(byLabel[key]); }
                    byLabel[key].items.push(t);
                    if (t.is_sample) byLabel[key].sample = true;
                });
                grid.classList.add('talks-grouped');
                let html = groups.map(g => this._sectionHtml(g)).join('');
                if (!this.yearFilter && !this.eventFilter) html += this._futureSectionHtml();
                grid.innerHTML = html;
            },

            _sectionHtml(g) {
                const sub = g.sample
                    ? TalkLibrary._t('talk.sampleSub')
                    : TalkLibrary._t('talk.onDemandSub');
                const cards = g.items.map(t => this._cardHtml(t)).join('');
                return `<div class="talk-section">
                    <div class="talk-section-head">
                        <div class="tsh-left">
                            <h3>${escapeHtml(g.label)}</h3>
                            <span class="tsh-sub">${sub}</span>
                        </div>
                        <span class="talk-section-count">${TalkLibrary._sessionCount(g.items.length)}</span>
                    </div>
                    <div class="talks-grid">${cards}</div>
                </div>`;
            },

            _cardHtml(t) {
                const isPlaceholder = !t.video_url || t.video_url === '#placeholder';
                const thumb = t.thumb_url
                    ? `<img src="${escapeHtml(t.thumb_url)}" alt="" loading="lazy">`
                    : `<div class="talk-play"><i class="fas fa-play"></i></div>`;
                const year = t.year ? `<span class="talk-year">${escapeHtml(String(t.year))}</span>` : '';
                const duration = t.duration ? `<span class="talk-duration"><i class="fas fa-clock"></i> ${escapeHtml(t.duration)}</span>` : '';
                let ribbon = '';
                if (t.is_sample) ribbon = '<span class="talk-ribbon sample">' + TalkLibrary._t('talk.ribbonSample') + '</span>';
                else if (isPlaceholder) ribbon = '<span class="talk-ribbon soon">' + TalkLibrary._t('talk.ribbonSoon') + '</span>';
                const speaker = t.speaker ? `<div class="talk-src"><i class="fas fa-microphone"></i> ${escapeHtml(t.speaker)}</div>` : '';
                return `<div class="talk-card" onclick="TalkLibrary.play('${String(t.video_url || '').replace(/'/g, "\\'")}')">
                    <div class="talk-thumb">${thumb}${duration}${year}${ribbon}</div>
                    <div class="talk-body">
                        <h4>${escapeHtml(t.title || '')}</h4>
                        ${speaker}
                        ${this._starsHtml(t)}
                    </div>
                </div>`;
            },

            // Interactive one-tap star row + suppressed aggregate. The wrapper stops click
            // propagation so rating a talk never triggers the card's play handler. The aggregate
            // (avg + count) only renders when at least three members have rated (matches the server).
            _starsHtml(t) {
                const mine = t.my_rating || 0;
                const tid = String(t.id).replace(/'/g, "\\'");
                let stars = '';
                for (let v = 1; v <= 5; v++) {
                    stars += `<button type="button" class="tstar${v <= mine ? ' on' : ''}" data-v="${v}" aria-label="${TalkLibrary._starAria(v)}" onmouseover="TalkLibrary._hoverStars(this,${v})" onfocus="TalkLibrary._hoverStars(this,${v})" onclick="TalkLibrary.rate('${tid}',${v},event)"><i class="fas fa-star"></i></button>`;
                }
                const hint = mine
                    ? TalkLibrary._t('talk.yourRating').replace('{n}', mine)
                    : TalkLibrary._t('talk.rateThis');
                let agg = '';
                if ((t.rating_count || 0) >= 3 && t.rating_avg != null) {
                    agg = `<span class="talk-rate-agg"><i class="fas fa-star"></i> ${TalkLibrary._fmtAvg(t.rating_avg)} <span class="tra-count">${TalkLibrary._ratingCount(t.rating_count)}</span></span>`;
                }
                return `<div class="talk-rate" onclick="event.stopPropagation()">
                    <div class="talk-stars" data-mine="${mine}" onmouseleave="TalkLibrary._resetStars(this)">${stars}</div>
                    <span class="talk-rate-hint">${hint}</span>
                    ${agg}
                </div>`;
            },

            _hoverStars(btn, v) {
                const c = btn.parentElement;
                if (!c) return;
                c.querySelectorAll('.tstar').forEach(b => { b.classList.toggle('on', parseInt(b.getAttribute('data-v'), 10) <= v); });
            },
            _resetStars(container) {
                const mine = parseInt(container.getAttribute('data-mine') || '0', 10);
                container.querySelectorAll('.tstar').forEach(b => { b.classList.toggle('on', parseInt(b.getAttribute('data-v'), 10) <= mine); });
            },

            // Optimistic upsert: reflect the tap immediately, then reconcile with the server's
            // authoritative aggregate. On failure we revert to the previous state. No points ever.
            rate(tid, v, ev) {
                if (ev) ev.stopPropagation();
                const item = this.items.find(x => String(x.id) === String(tid));
                if (!item) return;
                const prev = { my: item.my_rating || 0, count: item.rating_count || 0, avg: item.rating_avg };
                item.my_rating = v;
                this.render();
                UserPortal.api('/api/talks/' + encodeURIComponent(tid) + '/rating', { method: 'POST', body: JSON.stringify({ rating: v }) })
                    .then(r => {
                        item.my_rating = r.my_rating;
                        item.rating_count = r.rating_count;
                        item.rating_avg = r.rating_avg;
                        this.render();
                        try { Toast.success(TalkLibrary._t(prev.my ? 'talk.rateUpdated' : 'talk.rateThanks')); } catch (e) {}
                    })
                    .catch(e => {
                        item.my_rating = prev.my; item.rating_count = prev.count; item.rating_avg = prev.avg;
                        this.render();
                        try { Toast.error(TalkLibrary._t('talk.rateError')); } catch (e2) {}
                    });
            },

            _renderTopRated(grid) {
                const rated = this.items
                    .filter(t => (t.rating_count || 0) >= 3 && t.rating_avg != null)
                    .sort((a, b) => (b.rating_avg - a.rating_avg) || ((b.rating_count || 0) - (a.rating_count || 0)) || String(a.title || '').localeCompare(String(b.title || '')));
                grid.classList.add('talks-grouped');
                const head = `<div class="talk-section-head"><div class="tsh-left"><h3>${TalkLibrary._t('talk.topRated')}</h3><span class="tsh-sub">${TalkLibrary._t('talk.topRatedSub')}</span></div>${rated.length ? `<span class="talk-section-count">${TalkLibrary._sessionCount(rated.length)}</span>` : ''}</div>`;
                if (!rated.length) {
                    grid.innerHTML = `<div class="talk-section">${head}<div class="talk-coming-soon"><i class="fas fa-star"></i><p>${TalkLibrary._t('talk.topRatedEmpty')}</p></div></div>`;
                    return;
                }
                const cards = rated.map(t => this._cardHtml(t)).join('');
                grid.innerHTML = `<div class="talk-section">${head}<div class="talks-grid">${cards}</div></div>`;
            },

            _fmtAvg(n) {
                let isHR = false; try { isHR = !!(window.MedXI18n && MedXI18n.get && MedXI18n.get() === 'hr'); } catch (e) {}
                const s = (Math.round(Number(n) * 10) / 10).toFixed(1);
                return isHR ? s.replace('.', ',') : s;
            },
            _ratingCount(n) {
                let isHR = false; try { isHR = !!(window.MedXI18n && MedXI18n.get && MedXI18n.get() === 'hr'); } catch (e) {}
                if (isHR) { const m = n % 100, d = n % 10; const w = (d === 1 && m !== 11) ? 'ocjena' : ((d >= 2 && d <= 4 && !(m >= 12 && m <= 14)) ? 'ocjene' : 'ocjena'); return n + ' ' + w; }
                return n + ' rating' + (n === 1 ? '' : 's');
            },
            _starAria(v) {
                let isHR = false; try { isHR = !!(window.MedXI18n && MedXI18n.get && MedXI18n.get() === 'hr'); } catch (e) {}
                return (isHR ? 'Ocijenite ' : 'Rate ') + v + (isHR ? ' od 5' : ' of 5');
            },

            _futureSectionHtml() {
                return `<div class="talk-section talk-section-future">
                    <div class="talk-section-head">
                        <div class="tsh-left">
                            <h3>Plexus 2026</h3>
                            <span class="tsh-sub">${TalkLibrary._t('talk.futureSub')}</span>
                        </div>
                        <span class="talk-section-count">${TalkLibrary._t('talk.futureCount')}</span>
                    </div>
                    <div class="talk-coming-soon">
                        <i class="fas fa-clapperboard"></i>
                        <p>${TalkLibrary._t('talk.futureBody')}</p>
                    </div>
                </div>`;
            },

            _t(k){ try{ return (window.MedXI18n&&MedXI18n.t)?MedXI18n.t(k):k; }catch(e){ return k; } },
            _sessionCount(n){
                var isHR=false; try{ isHR=!!(window.MedXI18n&&MedXI18n.get&&MedXI18n.get()==='hr'); }catch(e){}
                if(isHR){ var m=n%100, d=n%10; var w=(d===1&&m!==11)?'sesija':((d>=2&&d<=4&&!(m>=12&&m<=14))?'sesije':'sesija'); return n+' '+w; }
                return n+' session'+(n===1?'':'s');
            },
            relocalize(){ try{ if(this._loaded){ this.renderFilters(); this.render(); } }catch(e){} },
            play(url) {
                if (!url || url === '#placeholder') {
                    Toast.info ? Toast.info(TalkLibrary._t('talk.recordingSoon')) : Toast.success(TalkLibrary._t('talk.recordingSoon'));
                    return;
                }
                window.open(url, '_blank', 'noopener');
            }
        };

        // =========================================
        // SPLIT LAYOUT - My Events + User Widgets
        // =========================================
        const SplitLayout = {
            notesKey: 'medx_split_notes',
            tasksKey: 'medx_split_tasks',
            tasks: [],

            init() {
                this.loadNotes();
                this.loadTasks();
                this.updateUserInfo();
                this.renderBadges();
            },

            updateUserInfo() {
                const user = UserPortal.user || {};
                const firstName = user.first_name || user.name?.split(' ')[0] || 'User';
                const initials = firstName.charAt(0).toUpperCase();

                const avatarEl = document.getElementById('splitUserAvatar');
                const nameEl = document.getElementById('splitUserName');
                const roleEl = document.getElementById('splitUserRole');

                if (avatarEl) avatarEl.textContent = initials;
                if (nameEl) nameEl.textContent = `${firstName}'s Workspace`;
                if (roleEl) roleEl.textContent = 'Member since 2026';
            },

            loadNotes() {
                const notes = localStorage.getItem(this.notesKey);
                const textarea = document.getElementById('splitNotesTextarea');
                if (textarea && notes) textarea.value = notes;
            },

            saveNotes() {
                const textarea = document.getElementById('splitNotesTextarea');
                if (textarea) {
                    localStorage.setItem(this.notesKey, textarea.value);
                }
            },

            loadTasks() {
                const saved = localStorage.getItem(this.tasksKey);
                this.tasks = saved ? JSON.parse(saved) : [
                    { id: 1, text: 'Complete Plexus registration', completed: false },
                    { id: 2, text: 'Submit abstract by Feb 15', completed: false },
                    { id: 3, text: 'Review conference schedule', completed: true }
                ];
                this.renderTasks();
            },

            saveTasks() {
                localStorage.setItem(this.tasksKey, JSON.stringify(this.tasks));
            },

            renderTasks() {
                const container = document.getElementById('splitTasksList');
                if (!container) return;

                if (this.tasks.length === 0) {
                    container.innerHTML = `
                        <div class="dashboard-empty-state" style="text-align: center; padding: 32px 16px; color: var(--up-text-muted, var(--muted));">
                            <i class="fas fa-tasks" style="font-size: 32px; margin-bottom: 12px; opacity: 0.5; display: block;"></i>
                            <p style="font-size: 14px; margin: 0;">No tasks yet. Add one above to stay organized.</p>
                        </div>
                    `;
                    return;
                }

                container.innerHTML = this.tasks.map(task => `
                    <div class="user-task-item ${task.completed ? 'completed' : ''}">
                        <input type="checkbox" ${task.completed ? 'checked' : ''} onchange="SplitLayout.toggleTask(${task.id})">
                        <span class="task-text">${task.text}</span>
                        <button class="delete-task" onclick="SplitLayout.deleteTask(${task.id})">
                            <i class="fas fa-times"></i>
                        </button>
                    </div>
                `).join('');
            },

            addTask() {
                const input = document.getElementById('splitNewTaskInput');
                if (!input || !input.value.trim()) return;

                this.tasks.push({
                    id: Date.now(),
                    text: input.value.trim(),
                    completed: false
                });

                input.value = '';
                this.saveTasks();
                this.renderTasks();
            },

            toggleTask(id) {
                const task = this.tasks.find(t => t.id === id);
                if (task) {
                    task.completed = !task.completed;
                    this.saveTasks();
                    this.renderTasks();
                }
            },

            deleteTask(id) {
                this.tasks = this.tasks.filter(t => t.id !== id);
                this.saveTasks();
                this.renderTasks();
            },

            renderBadges() {
                const container = document.getElementById('splitBadgesGrid');
                if (!container) return;

                // Get achievements from Achievements object if available
                const earned = [];
                const locked = [];

                if (typeof Achievements !== 'undefined') {
                    const allBadges = [
                        { id: 'profile-complete', icon: 'fa-user-check', name: 'Profile Complete' },
                        { id: 'first-quiz', icon: 'fa-brain', name: 'Quiz Starter' },
                        { id: 'streak-5', icon: 'fa-fire', name: '5-Day Streak' },
                        { id: 'quiz-master', icon: 'fa-trophy', name: 'Quiz Master' },
                        { id: 'networker', icon: 'fa-users', name: 'Networker' }
                    ];

                    allBadges.forEach(badge => {
                        if (Achievements.unlockedAchievements?.includes(badge.id)) {
                            earned.push(badge);
                        } else {
                            locked.push(badge);
                        }
                    });
                }

                // Default badges if Achievements not loaded
                if (earned.length === 0 && locked.length === 0) {
                    earned.push({ icon: 'fa-user-check', name: 'Profile Complete' });
                    earned.push({ icon: 'fa-fire', name: '5-Day Streak' });
                    locked.push({ icon: 'fa-trophy', name: 'Quiz Master' });
                    locked.push({ icon: 'fa-users', name: 'Networker' });
                }

                container.innerHTML = [
                    ...earned.map(b => `<span class="user-badge earned"><i class="fas ${b.icon}"></i> ${b.name}</span>`),
                    ...locked.slice(0, 2).map(b => `<span class="user-badge"><i class="fas ${b.icon}"></i> ${b.name}</span>`)
                ].join('');
            }
        };

        // =========================================
        // CARD MANAGER - REMOVABLE CARDS
        // =========================================
        const CardManager = {
            hiddenCards: [],

            init() {
                // Load hidden cards from localStorage
                this.hiddenCards = safeJsonParse(localStorage.getItem('medx_hidden_cards'), []);
                // Ensure essential widgets are never hidden
                const essentialWidgets = ['quizWidget', 'myEventsCard'];
                this.hiddenCards = this.hiddenCards.filter(id => !essentialWidgets.includes(id));
                localStorage.setItem('medx_hidden_cards', JSON.stringify(this.hiddenCards));
                this.applyHiddenCards();
                // Force-show essential widgets (in case they were hidden before this fix)
                essentialWidgets.forEach(id => {
                    const el = document.getElementById(id);
                    if (el) { el.classList.remove('card-hidden'); el.style.display = ''; }
                });
                this.updateRestoreButton();
                this.setupLongPress();
            },

            removeCard(cardId) {
                const card = document.getElementById(cardId);
                if (!card) return;

                // Show confirmation dialog
                this.showConfirmDialog(card, cardId);
            },

            showConfirmDialog(card, cardId) {
                // Remove any existing dialog
                const existing = document.getElementById('cardRemoveConfirm');
                if (existing) existing.remove();

                const dialog = document.createElement('div');
                dialog.id = 'cardRemoveConfirm';
                dialog.style.cssText = 'position:fixed;top:0;left:0;width:100%;height:100%;background:rgba(0,0,0,0.5);z-index:100000;display:flex;align-items:center;justify-content:center;animation:fadeIn 0.2s ease;backdrop-filter:blur(4px);';
                dialog.innerHTML = `
                    <div style="background:var(--up-bg, white);border:1px solid var(--up-border, var(--line));border-radius:16px;padding:28px;max-width:340px;width:90%;text-align:center;box-shadow:0 20px 60px rgba(0,0,0,0.3);animation:fadeInUp 0.3s ease;">
                        <div style="font-size:32px;margin-bottom:12px;">🗑️</div>
                        <h4 style="font-size:16px;font-weight:600;color:var(--up-text, var(--ink));margin:0 0 8px 0;">Hide this card?</h4>
                        <p style="font-size:13px;color:var(--up-text-muted, var(--muted));margin:0 0 20px 0;">You can restore hidden cards anytime from the dashboard settings.</p>
                        <div style="display:flex;gap:10px;justify-content:center;">
                            <button onclick="document.getElementById('cardRemoveConfirm').remove();" style="padding:10px 20px;border-radius:10px;border:1px solid var(--up-border, var(--line));background:var(--up-bg, white);color:var(--up-text, var(--ink));font-size:13px;font-weight:600;cursor:pointer;transition:all 0.2s;">Cancel</button>
                            <button onclick="CardManager.confirmRemove('${cardId}');" style="padding:10px 20px;border-radius:10px;border:none;background:var(--danger);color:white;font-size:13px;font-weight:600;cursor:pointer;transition:all 0.2s;">Yes, hide it</button>
                        </div>
                    </div>
                `;
                document.body.appendChild(dialog);

                // Close on backdrop click
                dialog.addEventListener('click', (e) => {
                    if (e.target === dialog) dialog.remove();
                });
            },

            confirmRemove(cardId) {
                // Close dialog
                const dialog = document.getElementById('cardRemoveConfirm');
                if (dialog) dialog.remove();

                const card = document.getElementById(cardId);
                if (!card) return;

                // Add removing animation
                card.classList.add('card-removing');

                setTimeout(() => {
                    card.classList.add('card-hidden');
                    card.classList.remove('card-removing');

                    // Hide associated labels
                    if (cardId === 'newsWidget') {
                        const label = document.getElementById('newsLabel');
                        if (label) label.style.display = 'none';
                    }

                    // Save to localStorage
                    if (!this.hiddenCards.includes(cardId)) {
                        this.hiddenCards.push(cardId);
                        localStorage.setItem('medx_hidden_cards', JSON.stringify(this.hiddenCards));
                    }

                    this.updateRestoreButton();
                }, 300);
            },

            restoreAllCards() {
                // Restore all hidden cards
                this.hiddenCards.forEach(cardId => {
                    const card = document.getElementById(cardId);
                    if (card) {
                        card.classList.remove('card-hidden');
                    }

                    // Restore associated labels
                    if (cardId === 'newsWidget') {
                        const label = document.getElementById('newsLabel');
                        if (label) label.style.display = '';
                    }
                });

                this.hiddenCards = [];
                localStorage.setItem('medx_hidden_cards', JSON.stringify(this.hiddenCards));
                this.updateRestoreButton();
            },

            applyHiddenCards() {
                this.hiddenCards.forEach(cardId => {
                    const card = document.getElementById(cardId);
                    if (card) {
                        card.classList.add('card-hidden');
                    }

                    // Hide associated labels
                    if (cardId === 'newsWidget') {
                        const label = document.getElementById('newsLabel');
                        if (label) label.style.display = 'none';
                    }
                });
            },

            updateRestoreButton() {
                let btn = document.getElementById('restoreCardsBtn');
                if (!btn) {
                    // Create restore button if not exists
                    btn = document.createElement('button');
                    btn.id = 'restoreCardsBtn';
                    btn.className = 'restore-cards-btn';
                    btn.innerHTML = '<i class="fas fa-undo"></i> Restore Cards';
                    btn.onclick = () => this.restoreAllCards();
                    document.body.appendChild(btn);
                }

                if (this.hiddenCards.length > 0) {
                    btn.classList.add('show');
                    btn.innerHTML = `<i class="fas fa-undo"></i> Restore ${this.hiddenCards.length} Card${this.hiddenCards.length > 1 ? 's' : ''}`;
                } else {
                    btn.classList.remove('show');
                }
            },

            setupLongPress() {
                // Long-press support for mobile
                const cards = document.querySelectorAll('.removable-card');
                cards.forEach(card => {
                    let pressTimer;

                    card.addEventListener('touchstart', (e) => {
                        pressTimer = setTimeout(async () => {
                            card.classList.add('card-removing');
                            const confirmed = await ConfirmationModal.show({
                                type: 'warning',
                                icon: 'fa-minus-circle',
                                title: 'Remove Card?',
                                message: 'You can restore it anytime from Settings.',
                                confirmText: 'Remove',
                                cancelText: 'Keep'
                            });
                            if (confirmed) {
                                this.removeCard(card.id);
                            } else {
                                card.classList.remove('card-removing');
                            }
                        }, 800);
                    });

                    card.addEventListener('touchend', () => {
                        clearTimeout(pressTimer);
                    });

                    card.addEventListener('touchmove', () => {
                        clearTimeout(pressTimer);
                    });
                });
            }
        };

        // =========================================
        // PHASE 1: FOR YOU PERSONALIZED FEED
        // =========================================
        // =========================================
        // STREAK TRACKER - Login Streak System
        // =========================================
        const StreakTracker = {
            loginDates: [],

            init() {
                this.loadData();
                this.recordLogin();
                this.render();
            },

            loadData() {
                const saved = localStorage.getItem('medx_login_streak');
                this.loginDates = saved ? JSON.parse(saved) : [];
            },

            saveData() {
                localStorage.setItem('medx_login_streak', JSON.stringify(this.loginDates));
            },

            recordLogin() {
                const today = new Date().toDateString();
                if (!this.loginDates.includes(today)) {
                    this.loginDates.push(today);
                    // Keep only last 30 days
                    if (this.loginDates.length > 30) {
                        this.loginDates = this.loginDates.slice(-30);
                    }
                    this.saveData();
                }
            },

            calculateStreak() {
                if (this.loginDates.length === 0) return 0;

                let streak = 0;
                const today = new Date();

                for (let i = 0; i <= 30; i++) {
                    const checkDate = new Date(today);
                    checkDate.setDate(checkDate.getDate() - i);
                    const dateStr = checkDate.toDateString();

                    if (this.loginDates.includes(dateStr)) {
                        streak++;
                    } else if (i > 0) {
                        break;
                    }
                }

                return streak;
            },

            render() {
                const streak = this.calculateStreak();
                const countEl = document.getElementById('streakCount');
                const messageEl = document.getElementById('streakMessage');
                const calendarEl = document.getElementById('streakCalendar');

                if (countEl) countEl.textContent = streak;
                if (messageEl) messageEl.textContent = streak === 1 ? '1 day streak!' : `${streak} day streak!`;

                if (calendarEl) {
                    const days = calendarEl.querySelectorAll('.streak-day');
                    const today = new Date();

                    days.forEach((day, index) => {
                        const checkDate = new Date(today);
                        checkDate.setDate(checkDate.getDate() - (6 - index));
                        const dateStr = checkDate.toDateString();

                        day.classList.remove('active', 'today');
                        if (this.loginDates.includes(dateStr)) {
                            day.classList.add('active');
                        }
                        if (index === 6) {
                            day.classList.add('today');
                        }
                    });
                }
            }
        };

