        // =========================================
        // HOMEPAGE NOTIFICATIONS (Admin-managed)
        // =========================================
        const HomepageNotifications = {
            notifications: [],
            dismissedIds: [],

            async init() {
                this.loadDismissed();
                await this.load();
                this.render();
            },

            loadDismissed() {
                try {
                    this.dismissedIds = JSON.parse(localStorage.getItem('medx_homepage_notifs_dismissed') || '[]');
                } catch (e) {
                    this.dismissedIds = [];
                }
            },

            saveDismissed() {
                localStorage.setItem('medx_homepage_notifs_dismissed', JSON.stringify(this.dismissedIds));
            },

            async load() {
                try {
                    const token = localStorage.getItem('medx_user_token');
                    if (!token) return;
                    const authHeaders = { 'Authorization': `Bearer ${token}` };
                    // Fetch notifications placed on homepage or both
                    const [resp1, resp2] = await Promise.all([
                        fetch('/api/user-notifications?placement=homepage&limit=10', { headers: authHeaders }),
                        fetch('/api/user-notifications?placement=both&limit=10', { headers: authHeaders })
                    ]);
                    let notifs = [];
                    if (resp1.ok) { const d = await resp1.json(); notifs = notifs.concat(d.notifications || []); }
                    if (resp2.ok) { const d = await resp2.json(); notifs = notifs.concat(d.notifications || []); }
                    // Deduplicate by id and filter out dismissed
                    const seen = new Set();
                    this.notifications = notifs.filter(n => {
                        if (seen.has(n.id) || this.dismissedIds.includes(n.id)) return false;
                        seen.add(n.id);
                        return true;
                    });
                } catch (err) {
                    console.warn('Failed to load homepage notifications:', err);
                }
            },

            formatTimeAgo(dateStr) {
                if (!dateStr) return '';
                const date = new Date(dateStr);
                const now = new Date();
                const diffMs = now - date;
                const diffHours = Math.floor(diffMs / 3600000);
                const diffDays = Math.floor(diffMs / 86400000);
                if (diffHours < 1) return 'Just now';
                if (diffHours < 24) return `${diffHours}h ago`;
                if (diffDays < 7) return `${diffDays}d ago`;
                return date.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
            },

            render() {
                const container = document.getElementById('homepageNotifications');
                if (!container) return;

                if (!this.notifications.length) {
                    container.innerHTML = '';
                    container.style.display = 'none';
                    return;
                }

                container.style.display = 'flex';
                container.innerHTML = this.notifications.map(n => {
                    const type = n.notification_type || 'info';
                    const icon = n.icon || 'fa-bell';
                    const escapedLink = (n.link || '').replace(/'/g, "\\'");
                    return `<div class="homepage-notif-item ${type}" onclick="HomepageNotifications.handleClick('${n.id}', '${escapedLink}')">
                        <div class="homepage-notif-icon"><i class="fas ${icon}"></i></div>
                        <div class="homepage-notif-content">
                            <div class="homepage-notif-title">${n.title}</div>
                            ${n.message ? `<div class="homepage-notif-message">${n.message}</div>` : ''}
                        </div>
                        <span class="homepage-notif-time">${this.formatTimeAgo(n.created_at)}</span>
                        <button class="homepage-notif-dismiss" onclick="event.stopPropagation(); HomepageNotifications.dismiss('${n.id}')" aria-label="Dismiss"><i class="fas fa-times"></i></button>
                    </div>`;
                }).join('');
            },

            handleClick(id, link) {
                fetch(`/api/user-notifications/${id}/read`, { method: 'PUT', headers: { 'Authorization': `Bearer ${localStorage.getItem('medx_user_token')}` } }).catch(() => {});
                if (link) {
                    if (link.startsWith('#')) {
                        const section = link.replace('#', '').split('/')[0];
                        UserPortal.showSection(section);
                    } else if (link.startsWith('http')) {
                        window.open(link, '_blank');
                    }
                }
            },

            dismiss(id) {
                this.dismissedIds.push(id);
                this.saveDismissed();
                this.notifications = this.notifications.filter(n => n.id !== id);
                this.render();
                fetch(`/api/user-notifications/${id}/read`, { method: 'PUT', headers: { 'Authorization': `Bearer ${localStorage.getItem('medx_user_token')}` } }).catch(() => {});
            }
        };

