        // QUICK POLL WIDGET
        // =========================================
        const QuickPoll = {
            polls: [
                { question: 'What session topic interests you most?', options: ['AI in Medicine', 'Sleep Science', 'Neuroscience', 'Cardiology'] },
                { question: 'Which networking format do you prefer?', options: ['Coffee chats', 'Panel discussions', 'Workshops', 'Speed networking'] },
                { question: 'What career stage are you at?', options: ['Student', 'Resident', 'Fellow', 'Attending/Faculty'] },
                { question: 'How did you hear about Med&X?', options: ['Colleague', 'Social media', 'Academic event', 'Google search'] }
            ],

            init() {
                if (this.hasVoted()) {
                    this.showResults();
                } else {
                    this.render();
                }
            },

            getCurrentPoll() {
                // Select poll based on day of year
                const dayOfYear = Math.floor((Date.now() - new Date(new Date().getFullYear(), 0, 0)) / 86400000);
                return this.polls[dayOfYear % this.polls.length];
            },

            hasVoted() {
                const votes = safeJsonParse(localStorage.getItem('medx_poll_votes'), {});
                const today = new Date().toDateString();
                return !!votes[today];
            },

            vote(option) {
                const votes = safeJsonParse(localStorage.getItem('medx_poll_votes'), {});
                const today = new Date().toDateString();
                votes[today] = option;
                localStorage.setItem('medx_poll_votes', JSON.stringify(votes));

                // Award points
                if (typeof RewardsPortal !== 'undefined' && RewardsPortal.addPoints) {
                    RewardsPortal.addPoints(5, 'Quick Poll');
                }

                this.showResults(option);
            },

            render() {
                const poll = this.getCurrentPoll();
                const questionEl = document.getElementById('pollQuestion');
                const optionsEl = document.getElementById('pollOptions');
                const resultsEl = document.getElementById('pollResults');

                if (questionEl) questionEl.textContent = poll.question;
                if (optionsEl) {
                    optionsEl.style.display = '';
                    optionsEl.innerHTML = poll.options.map((opt, i) =>
                        `<button class="poll-option" data-option="${i}" onclick="QuickPoll.vote('${opt}')">${opt}</button>`
                    ).join('');
                }
                if (resultsEl) resultsEl.style.display = 'none';
            },

            showResults(userVote) {
                const poll = this.getCurrentPoll();
                const optionsEl = document.getElementById('pollOptions');
                const resultsEl = document.getElementById('pollResults');

                if (optionsEl) optionsEl.style.display = 'none';
                if (resultsEl) {
                    // Generate fake results
                    const results = poll.options.map(opt => ({
                        text: opt,
                        percent: Math.floor(Math.random() * 40) + 15,
                        isUser: opt === userVote
                    }));
                    // Normalize to 100%
                    const total = results.reduce((sum, r) => sum + r.percent, 0);
                    results.forEach(r => r.percent = Math.round((r.percent / total) * 100));

                    resultsEl.style.display = '';
                    resultsEl.innerHTML = results.map(r => `
                        <div class="poll-result-item ${r.isUser ? 'user-vote' : ''}">
                            <div class="poll-result-bar">
                                <div class="poll-result-fill" style="width: ${r.percent}%"></div>
                                <span class="poll-result-text">${r.text}</span>
                                <span class="poll-result-percent">${r.percent}%</span>
                            </div>
                        </div>
                    `).join('');
                }
            }
        };

