        // =========================================
        const EnhancedSearch = {
            members: [
                { id: 'user1', name: 'Dr. Sarah Chen', institution: 'Harvard Medical School', type: 'member' },
                { id: 'user2', name: 'Dr. Michael Torres', institution: 'Mayo Clinic', type: 'member' },
                { id: 'user3', name: 'Dr. Emily Johnson', institution: 'Stanford Medicine', type: 'member' },
                { id: 'user4', name: 'Dr. James Park', institution: 'MIT', type: 'member' },
                { id: 'user5', name: 'Dr. Anna Schmidt', institution: 'Cleveland Clinic', type: 'member' }
            ],
            events: [
                { id: 'plexus', name: 'Plexus Conference 2026', date: 'Dec 4-5, 2026', type: 'event' },
                { id: 'gala', name: 'Gala Evening 2026', date: 'Dec 5, 2026', type: 'event' },
                { id: 'forum', name: 'Biomedical Forum Annual Meeting', date: 'TBD', type: 'event' }
            ],
            sections: [
                { id: 'dashboard', name: 'Dashboard', icon: 'fa-home', type: 'nav' },
                { id: 'plexus', name: 'Plexus Conference', icon: 'fa-users', type: 'nav' },
                { id: 'accelerator', name: 'Accelerator Program', icon: 'fa-rocket', type: 'nav' },
                { id: 'forum', name: 'Biomedical Forum', icon: 'fa-landmark', type: 'nav' },
                { id: 'network', name: 'My Network', icon: 'fa-user-friends', type: 'nav' },
                { id: 'settings', name: 'Settings', icon: 'fa-cog', type: 'nav' }
            ],

            search(query) {
                if (!query || query.length < 2) return [];
                const q = query.toLowerCase();
                const results = [];

                // Search members
                const matchedMembers = this.members.filter(m =>
                    m.name.toLowerCase().includes(q) || m.institution.toLowerCase().includes(q)
                ).slice(0, 3);
                if (matchedMembers.length) {
                    results.push({ category: 'Members', items: matchedMembers });
                }

                // Search events
                const matchedEvents = this.events.filter(e =>
                    e.name.toLowerCase().includes(q)
                ).slice(0, 3);
                if (matchedEvents.length) {
                    results.push({ category: 'Events', items: matchedEvents });
                }

                // Search navigation
                const matchedSections = this.sections.filter(s =>
                    s.name.toLowerCase().includes(q)
                ).slice(0, 3);
                if (matchedSections.length) {
                    results.push({ category: 'Pages', items: matchedSections });
                }

                return results;
            },

            getInitials(name) {
                return name.split(' ').map(n => n[0]).join('').slice(0, 2).toUpperCase();
            }
        };

        // =========================================
        // PHASE 2: ACTION ITEMS WIDGET
