        // =========================================
        // PHASE 4.2: SPEAKER CHAT
        // =========================================
        const SpeakerChat = {
            isOpen: false,
            messages: [],

            toggle() {
                this.isOpen = !this.isOpen;
                document.getElementById('speakerChatPanel').classList.toggle('active', this.isOpen);
            },

            send() {
                const input = document.getElementById('speakerChatInput');
                const message = input.value.trim();
                if (!message) return;

                const messagesEl = document.getElementById('speakerChatMessages');
                messagesEl.innerHTML += `
                    <div class="speaker-chat-message sent">
                        ${escapeHtml(message)}
                        <div style="font-size:10px;opacity:0.7;margin-top:4px;">Just now</div>
                    </div>
                `;
                input.value = '';
                messagesEl.scrollTop = messagesEl.scrollHeight;

                // Simulate response
                setTimeout(() => {
                    messagesEl.innerHTML += `
                        <div class="speaker-chat-message received">
                            Thanks for your message! I'll get back to you shortly.
                            <div style="font-size:10px;color:var(--text-muted);margin-top:4px;">Just now</div>
                        </div>
                    `;
                    messagesEl.scrollTop = messagesEl.scrollHeight;
                }, 1500);
            },

            show() {
                document.getElementById('speakerChatWidget').style.display = 'block';
            }
        };

        // =========================================
