            showConflict(userName) {
                document.getElementById('conflictUser').textContent = userName;
                document.getElementById('collabConflictWarning').classList.add('active');
            },

            dismissConflict() {
                document.getElementById('collabConflictWarning').classList.remove('active');
            },

            refreshData() {
                this.dismissConflict();
                ToastSystem.info('Data refreshed');
            },

            addActivity(user, action, target) {
                this.activities.unshift({
                    user,
                    action,
                    target,
                    time: 'Just now'
                });
            }
