        // =========================================
        // PHASE 4.4: REPORT BUILDER
        // =========================================
        const ReportBuilder = {
            selectedFields: [],
            chartType: 'table',

            open() {
                document.getElementById('reportBuilderModal').classList.add('active');
                this.initDragDrop();
            },

            close() {
                document.getElementById('reportBuilderModal').classList.remove('active');
            },

            initDragDrop() {
                const fields = document.querySelectorAll('.report-field-item');
                const dropZone = document.getElementById('reportDropZone');

                fields.forEach(field => {
                    field.addEventListener('dragstart', (e) => {
                        e.dataTransfer.setData('text/plain', field.dataset.field);
                        field.classList.add('dragging');
                    });
                    field.addEventListener('dragend', () => {
                        field.classList.remove('dragging');
                    });
                });

                if (dropZone) {
                    dropZone.addEventListener('dragover', (e) => {
                        e.preventDefault();
                        dropZone.classList.add('drag-over');
                    });
                    dropZone.addEventListener('dragleave', () => {
                        dropZone.classList.remove('drag-over');
                    });
                    dropZone.addEventListener('drop', (e) => {
                        e.preventDefault();
                        dropZone.classList.remove('drag-over');
                        const fieldName = e.dataTransfer.getData('text/plain');
                        this.addField(fieldName);
                    });
                }

                // Chart type buttons
                document.querySelectorAll('.report-chart-type').forEach(btn => {
                    btn.addEventListener('click', () => {
                        document.querySelectorAll('.report-chart-type').forEach(b => b.classList.remove('active'));
                        btn.classList.add('active');
                        this.chartType = btn.dataset.type;
                    });
                });
            },

            addField(fieldName) {
                if (this.selectedFields.includes(fieldName)) return;
                this.selectedFields.push(fieldName);
                this.renderSelectedFields();
            },

            removeField(fieldName) {
                this.selectedFields = this.selectedFields.filter(f => f !== fieldName);
                this.renderSelectedFields();
            },

            renderSelectedFields() {
                const container = document.getElementById('reportSelectedFields');
                if (!container) return;

                container.innerHTML = this.selectedFields.map(field => `
                    <div class="report-selected-field" style="display:flex;align-items:center;gap:8px;padding:8px 12px;background:var(--bg-secondary);border:1px solid var(--border);border-radius:6px;font-size:12px;">
                        ${field}
                        <button onclick="ReportBuilder.removeField('${field}')" style="background:none;border:none;color:var(--text-muted);cursor:pointer;">
                            <i class="fas fa-times"></i>
                        </button>
                    </div>
                `).join('');
            },

            exportCSV() {
                ToastSystem.success('Exporting to CSV...');
            },

            exportPDF() {
                ToastSystem.success('Generating PDF report...');
            },

            save() {
                if (!this.selectedFields.length) {
                    ToastSystem.warning('Please add at least one field to the report');
                    return;
                }
                ToastSystem.success('Report saved');
                this.close();
            }
        };

        // Initialize all Phase 1-4 features
        document.addEventListener('DOMContentLoaded', function() {
            FilterBuilder.init();
            TaskAssignment.loadTasks();
            // Only initialize notifications if user is authenticated
            if (localStorage.getItem('medx_user_token')) {
                NotificationSystem.init();
            }
            // Push client loop: SW resubscribe bridge + badge sync (guarded, no-op when unsupported).
            try { if (window.MedXPush) MedXPush.init(); } catch (e) {}

            // Initialize drag-drop for report builder when opened
            document.querySelectorAll('[onclick*="ReportBuilder.open"]').forEach(btn => {
                btn.addEventListener('click', () => ReportBuilder.initDragDrop());
            });
        });

        // ===== Quick QR Check-in Modal =====
        function showQuickQR() {
            const existing = document.getElementById('quickQRModal');
            if (existing) existing.remove();

            const user = UserPortal.user || {};
            const name = ((user.first_name || '') + ' ' + (user.last_name || '')).trim() || 'Member';
            const tier = (typeof RewardsPortal !== 'undefined' && RewardsPortal.userRewards) ? RewardsPortal.userRewards.tier : 'bronze';
            const tierColors = { bronze: '#cd7f32', silver: '#94a3b8', gold: 'var(--gold)', platinum: '#e2e8f0' };
            const tierColor = tierColors[tier] || 'var(--gold)';

            const modal = document.createElement('div');
            modal.id = 'quickQRModal';
            modal.style.cssText = 'position:fixed; inset:0; background:rgba(0,0,0,0.85); z-index:10000; display:flex; align-items:center; justify-content:center; padding:20px;';
            modal.innerHTML = `
                <div id="quickQRCard" style="background: linear-gradient(160deg, #1d1a17, #14110f); border-radius: 16px; padding: 40px 32px; text-align: center; max-width: 340px; width: 100%; position: relative; border: 1px solid rgba(155,27,34,0.35);">
                    <button class="qr-modal-close-btn" style="position:absolute; top:16px; right:16px; background:none; border:none; color: var(--muted); font-size:20px; cursor:pointer;"><i class="fas fa-times"></i></button>
                    <div style="font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 1.5px; color: var(--gold); margin-bottom: 20px;">Med&X Member</div>
                    <div style="display:flex; justify-content:center; align-items:center;">
                        <canvas id="quickQRCanvas" style="border-radius: 12px; background: white; padding: 16px; width: 220px; height: 220px;"></canvas>
                    </div>
                    <div style="margin-top: 20px;">
                        <div style="font-size: 18px; font-weight: 700; color: #ffffff;">${escapeHtml(name)}</div>
                        <div style="display: inline-block; margin-top: 8px; padding: 4px 12px; border-radius: 6px; font-size: 11px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.5px; background: ${tierColor}20; color: ${tierColor}; border: 1px solid ${tierColor}40;">${tier}</div>
                    </div>
                    <div style="display: flex; gap: 10px; justify-content: center; margin-top: 24px;">
                        <button onclick="downloadQuickQR()" style="background: rgba(201,169,98,0.15); color: var(--gold); border: 1px solid rgba(201,169,98,0.3); border-radius: 10px; padding: 10px 20px; font-size: 13px; font-weight: 600; cursor: pointer;"><i class="fas fa-download"></i> Save QR</button>
                    </div>
                    <div style="margin-top: 16px; font-size: 11px; color: var(--muted);">Show this QR code at Med&X events for check-in</div>
                </div>
            `;
            document.body.appendChild(modal);

            // Simple close handlers — no hiding/showing the floating button
            modal.addEventListener('click', (e) => {
                if (e.target === modal) modal.remove();
            });
            modal.querySelector('.qr-modal-close-btn')?.addEventListener('click', () => {
                document.getElementById('quickQRModal')?.remove();
            });

            // Generate QR
            const qrData = JSON.stringify({
                type: 'MEDX_MEMBER',
                userId: user.id || '',
                email: user.email || '',
                name: name
            });

            if (typeof QRCode !== 'undefined') {
                const canvas = document.getElementById('quickQRCanvas');
                QRCode.toCanvas(canvas, qrData, {
                    width: 300,
                    margin: 3,
                    color: { dark: '#000000', light: '#ffffff' }
                }, function(err) {
                    if (err) console.error('QR generation failed:', err);
                });
            }
        }

        async function downloadQuickQR() {
            const card = document.getElementById('quickQRCard');
            if (!card) return;
            try {
                if (typeof html2canvas !== 'undefined') {
                    const canvas = await html2canvas(card, { scale: 3, backgroundColor: '#14110f', useCORS: true });
                    const link = document.createElement('a');
                    link.download = 'medx-qr-code.png';
                    link.href = canvas.toDataURL('image/png');
                    link.click();
                } else {
                    // Fallback: just save the QR canvas
                    const qrCanvas = document.getElementById('quickQRCanvas');
                    if (qrCanvas) {
                        const link = document.createElement('a');
                        link.download = 'medx-qr-code.png';
                        link.href = qrCanvas.toDataURL('image/png');
                        link.click();
                    }
                }
            } catch(e) {
                console.error('QR download failed:', e);
            }
        }

        // ===== Direct Invite — redirect to server-rendered standalone page =====
